export const verifiedQuizPacks = [{"id":"cbse-11-micro-ch1","board":"CBSE","classLevel":11,"subject":"Economics","title":"Economics and Economy","chapter":"Reference Chapter 1","sourceLabel":"T.R. Jain & V.K. Ohri — Introductory Microeconomics, Class XI (2020-21 reference edition); filtered to the CBSE 2026–27 Introductory Microeconomics scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Scarcity\"?","options":["resources are limited relative to human wants","selection among available alternatives because resources are scarce and have alternative uses","study of aggregates and economic problems at the level of the economy as a whole","a system through which people of an area earn their living and organise production, distribution and consumption"],"answer":0,"explanation":"Scarcity: resources are limited relative to human wants"},{"q":"Which statement best explains \"Choice\"?","options":["study of economic behaviour and problems of individual units such as consumers, firms, industries or specific markets","selection among available alternatives because resources are scarce and have alternative uses","analysis of statements that can be verified as true or false","a single consumer, household, firm, industry or specific market studied in microeconomics"],"answer":1,"explanation":"Choice: selection among available alternatives because resources are scarce and have alternative uses"},{"q":"Which statement best explains \"Microeconomics\"?","options":["study of aggregates and economic problems at the level of the economy as a whole","analysis involving value judgements about what ought to be","study of economic behaviour and problems of individual units such as consumers, firms, industries or specific markets","a total or economy-wide magnitude such as national income, total employment or general price level"],"answer":2,"explanation":"Microeconomics: study of economic behaviour and problems of individual units such as consumers, firms, industries or specific markets"},{"q":"Which statement best explains \"Macroeconomics\"?","options":["analysis of statements that can be verified as true or false","a system through which people of an area earn their living and organise production, distribution and consumption","scarcity together with alternative uses of resources creates the need to choose and allocate resources","study of aggregates and economic problems at the level of the economy as a whole"],"answer":3,"explanation":"Macroeconomics: study of aggregates and economic problems at the level of the economy as a whole"},{"q":"Which statement best explains \"Positive economics\"?","options":["analysis of statements that can be verified as true or false","analysis involving value judgements about what ought to be","a single consumer, household, firm, industry or specific market studied in microeconomics","resources are limited relative to human wants"],"answer":0,"explanation":"Positive economics: analysis of statements that can be verified as true or false"},{"q":"Which statement best explains \"Normative economics\"?","options":["a system through which people of an area earn their living and organise production, distribution and consumption","analysis involving value judgements about what ought to be","a total or economy-wide magnitude such as national income, total employment or general price level","selection among available alternatives because resources are scarce and have alternative uses"],"answer":1,"explanation":"Normative economics: analysis involving value judgements about what ought to be"},{"q":"Which statement best explains \"Economy\"?","options":["a single consumer, household, firm, industry or specific market studied in microeconomics","scarcity together with alternative uses of resources creates the need to choose and allocate resources","a system through which people of an area earn their living and organise production, distribution and consumption","study of economic behaviour and problems of individual units such as consumers, firms, industries or specific markets"],"answer":2,"explanation":"Economy: a system through which people of an area earn their living and organise production, distribution and consumption"},{"q":"Which statement best explains \"Individual economic unit\"?","options":["a total or economy-wide magnitude such as national income, total employment or general price level","resources are limited relative to human wants","study of aggregates and economic problems at the level of the economy as a whole","a single consumer, household, firm, industry or specific market studied in microeconomics"],"answer":3,"explanation":"Individual economic unit: a single consumer, household, firm, industry or specific market studied in microeconomics"},{"q":"Which statement best explains \"Economic aggregate\"?","options":["a total or economy-wide magnitude such as national income, total employment or general price level","scarcity together with alternative uses of resources creates the need to choose and allocate resources","selection among available alternatives because resources are scarce and have alternative uses","analysis of statements that can be verified as true or false"],"answer":0,"explanation":"Economic aggregate: a total or economy-wide magnitude such as national income, total employment or general price level"},{"q":"Which statement best explains \"Scarcity-and-choice link\"?","options":["resources are limited relative to human wants","scarcity together with alternative uses of resources creates the need to choose and allocate resources","study of economic behaviour and problems of individual units such as consumers, firms, industries or specific markets","analysis involving value judgements about what ought to be"],"answer":1,"explanation":"Scarcity-and-choice link: scarcity together with alternative uses of resources creates the need to choose and allocate resources"}],"Moderate":[{"q":"Which concept best matches this situation? A household has limited income but many competing wants.","options":["Choice","Scarcity","Macroeconomics","Economy"],"answer":1,"explanation":"Scarcity: resources are limited relative to human wants"},{"q":"Which concept best matches this situation? A student chooses books instead of a movie with the same limited money.","options":["Microeconomics","Positive economics","Choice","Individual economic unit"],"answer":2,"explanation":"Choice: selection among available alternatives because resources are scarce and have alternative uses"},{"q":"Which concept best matches this situation? A researcher studies the demand for tea in one market.","options":["Macroeconomics","Normative economics","Economic aggregate","Microeconomics"],"answer":3,"explanation":"Microeconomics: study of economic behaviour and problems of individual units such as consumers, firms, industries or specific markets"},{"q":"Which concept best matches this situation? A researcher studies national income, total employment and the general price level.","options":["Macroeconomics","Positive economics","Economy","Scarcity-and-choice link"],"answer":0,"explanation":"Macroeconomics: study of aggregates and economic problems at the level of the economy as a whole"},{"q":"Which concept best matches this situation? A claim about an observed tax rate is checked against official data.","options":["Normative economics","Positive economics","Individual economic unit","Scarcity"],"answer":1,"explanation":"Positive economics: analysis of statements that can be verified as true or false"},{"q":"Which concept best matches this situation? Someone argues that the government should increase subsidies.","options":["Economy","Economic aggregate","Normative economics","Choice"],"answer":2,"explanation":"Normative economics: analysis involving value judgements about what ought to be"},{"q":"Which concept best matches this situation? Production and exchange activities together allow people in a country to earn income.","options":["Individual economic unit","Scarcity-and-choice link","Microeconomics","Economy"],"answer":3,"explanation":"Economy: a system through which people of an area earn their living and organise production, distribution and consumption"},{"q":"Which concept best matches this situation? The pricing decision of one firm is analysed.","options":["Individual economic unit","Economic aggregate","Scarcity","Macroeconomics"],"answer":0,"explanation":"Individual economic unit: a single consumer, household, firm, industry or specific market studied in microeconomics"},{"q":"Which concept best matches this situation? Total employment for the country is measured.","options":["Scarcity-and-choice link","Economic aggregate","Choice","Positive economics"],"answer":1,"explanation":"Economic aggregate: a total or economy-wide magnitude such as national income, total employment or general price level"},{"q":"Which concept best matches this situation? Land can grow wheat or hold a factory, so its use must be chosen.","options":["Scarcity","Microeconomics","Scarcity-and-choice link","Normative economics"],"answer":2,"explanation":"Scarcity-and-choice link: scarcity together with alternative uses of resources creates the need to choose and allocate resources"}]}},{"id":"cbse-11-micro-ch2","board":"CBSE","classLevel":11,"subject":"Economics","title":"Central Problems of an Economy","chapter":"Reference Chapter 2","sourceLabel":"T.R. Jain & V.K. Ohri — Introductory Microeconomics, Class XI (2020-21 reference edition); filtered to the CBSE 2026–27 Introductory Microeconomics scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Economic problem\"?","options":["the problem of allocating scarce resources with alternative uses among competing wants","the central problem of choosing which goods and services to produce and in what quantities","the central problem concerning distribution of output and purchasing power among people","an attainable combination showing underutilisation or inefficient utilisation of resources"],"answer":0,"explanation":"Economic problem: the problem of allocating scarce resources with alternative uses among competing wants"},{"q":"Which statement best explains \"What to produce\"?","options":["the central problem of choosing the technique or factor combination used in production","the central problem of choosing which goods and services to produce and in what quantities","all output combinations that can be produced with given resources and technology","a combination unattainable with current resources and technology"],"answer":1,"explanation":"What to produce: the central problem of choosing which goods and services to produce and in what quantities"},{"q":"Which statement best explains \"How to produce\"?","options":["the central problem concerning distribution of output and purchasing power among people","the boundary showing maximum attainable combinations of two goods with given resources, technology and efficient use","the central problem of choosing the technique or factor combination used in production","the value of the next best alternative forgone when a choice is made"],"answer":2,"explanation":"How to produce: the central problem of choosing the technique or factor combination used in production"},{"q":"Which statement best explains \"For whom to produce\"?","options":["all output combinations that can be produced with given resources and technology","an attainable combination showing underutilisation or inefficient utilisation of resources","an increase in productive capacity caused by more or better resources or improved technology","the central problem concerning distribution of output and purchasing power among people"],"answer":3,"explanation":"For whom to produce: the central problem concerning distribution of output and purchasing power among people"},{"q":"Which statement best explains \"Production possibility set\"?","options":["all output combinations that can be produced with given resources and technology","the boundary showing maximum attainable combinations of two goods with given resources, technology and efficient use","a combination unattainable with current resources and technology","the problem of allocating scarce resources with alternative uses among competing wants"],"answer":0,"explanation":"Production possibility set: all output combinations that can be produced with given resources and technology"},{"q":"Which statement best explains \"Production Possibility Frontier\"?","options":["an attainable combination showing underutilisation or inefficient utilisation of resources","the boundary showing maximum attainable combinations of two goods with given resources, technology and efficient use","the value of the next best alternative forgone when a choice is made","the central problem of choosing which goods and services to produce and in what quantities"],"answer":1,"explanation":"Production Possibility Frontier: the boundary showing maximum attainable combinations of two goods with given resources, technology and efficient use"},{"q":"Which statement best explains \"Point inside PPC\"?","options":["a combination unattainable with current resources and technology","an increase in productive capacity caused by more or better resources or improved technology","an attainable combination showing underutilisation or inefficient utilisation of resources","the central problem of choosing the technique or factor combination used in production"],"answer":2,"explanation":"Point inside PPC: an attainable combination showing underutilisation or inefficient utilisation of resources"},{"q":"Which statement best explains \"Point outside PPC\"?","options":["the value of the next best alternative forgone when a choice is made","the problem of allocating scarce resources with alternative uses among competing wants","the central problem concerning distribution of output and purchasing power among people","a combination unattainable with current resources and technology"],"answer":3,"explanation":"Point outside PPC: a combination unattainable with current resources and technology"},{"q":"Which statement best explains \"Opportunity cost\"?","options":["the value of the next best alternative forgone when a choice is made","an increase in productive capacity caused by more or better resources or improved technology","the central problem of choosing which goods and services to produce and in what quantities","all output combinations that can be produced with given resources and technology"],"answer":0,"explanation":"Opportunity cost: the value of the next best alternative forgone when a choice is made"},{"q":"Which statement best explains \"Outward shift of PPC\"?","options":["the problem of allocating scarce resources with alternative uses among competing wants","an increase in productive capacity caused by more or better resources or improved technology","the central problem of choosing the technique or factor combination used in production","the boundary showing maximum attainable combinations of two goods with given resources, technology and efficient use"],"answer":1,"explanation":"Outward shift of PPC: an increase in productive capacity caused by more or better resources or improved technology"}],"Moderate":[{"q":"Which concept best matches this situation? A government decides how to use limited land, labour and capital.","options":["What to produce","Economic problem","For whom to produce","Point inside PPC"],"answer":1,"explanation":"Economic problem: the problem of allocating scarce resources with alternative uses among competing wants"},{"q":"Which concept best matches this situation? An economy chooses between more consumer goods and more capital goods.","options":["How to produce","Production possibility set","What to produce","Point outside PPC"],"answer":2,"explanation":"What to produce: the central problem of choosing which goods and services to produce and in what quantities"},{"q":"Which concept best matches this situation? A factory chooses between labour-intensive and capital-intensive methods.","options":["For whom to produce","Production Possibility Frontier","Opportunity cost","How to produce"],"answer":3,"explanation":"How to produce: the central problem of choosing the technique or factor combination used in production"},{"q":"Which concept best matches this situation? An economy considers how much output is accessible to different income groups.","options":["For whom to produce","Production possibility set","Point inside PPC","Outward shift of PPC"],"answer":0,"explanation":"For whom to produce: the central problem concerning distribution of output and purchasing power among people"},{"q":"Which concept best matches this situation? An economy lists feasible combinations of wheat and cloth.","options":["Production Possibility Frontier","Production possibility set","Point outside PPC","Economic problem"],"answer":1,"explanation":"Production possibility set: all output combinations that can be produced with given resources and technology"},{"q":"Which concept best matches this situation? Every point on the curve uses available resources fully and efficiently.","options":["Point inside PPC","Opportunity cost","Production Possibility Frontier","What to produce"],"answer":2,"explanation":"Production Possibility Frontier: the boundary showing maximum attainable combinations of two goods with given resources, technology and efficient use"},{"q":"Which concept best matches this situation? Unemployment leaves the economy producing below its potential.","options":["Point outside PPC","Outward shift of PPC","How to produce","Point inside PPC"],"answer":3,"explanation":"Point inside PPC: an attainable combination showing underutilisation or inefficient utilisation of resources"},{"q":"Which concept best matches this situation? The economy wants an output combination beyond its present capacity.","options":["Point outside PPC","Opportunity cost","Economic problem","For whom to produce"],"answer":0,"explanation":"Point outside PPC: a combination unattainable with current resources and technology"},{"q":"Which concept best matches this situation? Choosing a job paying ₹50,000 over the next-best job paying ₹42,000 has an opportunity cost of ₹42,000.","options":["Outward shift of PPC","Opportunity cost","What to produce","Production possibility set"],"answer":1,"explanation":"Opportunity cost: the value of the next best alternative forgone when a choice is made"},{"q":"Which concept best matches this situation? Better technology allows more of both goods to be produced.","options":["Economic problem","How to produce","Outward shift of PPC","Production Possibility Frontier"],"answer":2,"explanation":"Outward shift of PPC: an increase in productive capacity caused by more or better resources or improved technology"}]}},{"id":"cbse-11-micro-ch3","board":"CBSE","classLevel":11,"subject":"Economics","title":"Consumer’s Equilibrium — Utility Analysis","chapter":"Reference Chapter 3","sourceLabel":"T.R. Jain & V.K. Ohri — Introductory Microeconomics, Class XI (2020-21 reference edition); filtered to the CBSE 2026–27 Introductory Microeconomics scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Utility\"?","options":["the want-satisfying power of a commodity for a consumer","the approach that assumes utility can be measured numerically in units such as utils","the change in total utility caused by consuming one additional unit of a commodity","total utility reaches its maximum when marginal utility becomes zero"],"answer":0,"explanation":"Utility: the want-satisfying power of a commodity for a consumer"},{"q":"Which statement best explains \"Cardinal utility\"?","options":["the total satisfaction obtained from consuming all units of a commodity","the approach that assumes utility can be measured numerically in units such as utils","as consumption of a commodity increases, marginal utility tends to decline, other things remaining the same","negative marginal utility reduces total utility"],"answer":1,"explanation":"Cardinal utility: the approach that assumes utility can be measured numerically in units such as utils"},{"q":"Which statement best explains \"Total utility\"?","options":["the change in total utility caused by consuming one additional unit of a commodity","total utility rises as long as marginal utility remains positive","the total satisfaction obtained from consuming all units of a commodity","the consumer is in equilibrium when marginal utility in money terms equals the price, subject to diminishing marginal utility"],"answer":2,"explanation":"Total utility: the total satisfaction obtained from consuming all units of a commodity"},{"q":"Which statement best explains \"Marginal utility\"?","options":["as consumption of a commodity increases, marginal utility tends to decline, other things remaining the same","total utility reaches its maximum when marginal utility becomes zero","with several goods, satisfaction is maximised by allocating expenditure so marginal utility per rupee is equal across goods","the change in total utility caused by consuming one additional unit of a commodity"],"answer":3,"explanation":"Marginal utility: the change in total utility caused by consuming one additional unit of a commodity"},{"q":"Which statement best explains \"Law of diminishing marginal utility\"?","options":["as consumption of a commodity increases, marginal utility tends to decline, other things remaining the same","total utility rises as long as marginal utility remains positive","negative marginal utility reduces total utility","the want-satisfying power of a commodity for a consumer"],"answer":0,"explanation":"Law of diminishing marginal utility: as consumption of a commodity increases, marginal utility tends to decline, other things remaining the same"},{"q":"Which statement best explains \"TU–MU relation while MU is positive\"?","options":["total utility reaches its maximum when marginal utility becomes zero","total utility rises as long as marginal utility remains positive","the consumer is in equilibrium when marginal utility in money terms equals the price, subject to diminishing marginal utility","the approach that assumes utility can be measured numerically in units such as utils"],"answer":1,"explanation":"TU–MU relation while MU is positive: total utility rises as long as marginal utility remains positive"},{"q":"Which statement best explains \"TU maximum when MU is zero\"?","options":["negative marginal utility reduces total utility","with several goods, satisfaction is maximised by allocating expenditure so marginal utility per rupee is equal across goods","total utility reaches its maximum when marginal utility becomes zero","the total satisfaction obtained from consuming all units of a commodity"],"answer":2,"explanation":"TU maximum when MU is zero: total utility reaches its maximum when marginal utility becomes zero"},{"q":"Which statement best explains \"TU falls when MU is negative\"?","options":["the consumer is in equilibrium when marginal utility in money terms equals the price, subject to diminishing marginal utility","the want-satisfying power of a commodity for a consumer","the change in total utility caused by consuming one additional unit of a commodity","negative marginal utility reduces total utility"],"answer":3,"explanation":"TU falls when MU is negative: negative marginal utility reduces total utility"},{"q":"Which statement best explains \"Single-commodity consumer equilibrium\"?","options":["the consumer is in equilibrium when marginal utility in money terms equals the price, subject to diminishing marginal utility","with several goods, satisfaction is maximised by allocating expenditure so marginal utility per rupee is equal across goods","the approach that assumes utility can be measured numerically in units such as utils","as consumption of a commodity increases, marginal utility tends to decline, other things remaining the same"],"answer":0,"explanation":"Single-commodity consumer equilibrium: the consumer is in equilibrium when marginal utility in money terms equals the price, subject to diminishing marginal utility"},{"q":"Which statement best explains \"Law of equi-marginal utility\"?","options":["the want-satisfying power of a commodity for a consumer","with several goods, satisfaction is maximised by allocating expenditure so marginal utility per rupee is equal across goods","the total satisfaction obtained from consuming all units of a commodity","total utility rises as long as marginal utility remains positive"],"answer":1,"explanation":"Law of equi-marginal utility: with several goods, satisfaction is maximised by allocating expenditure so marginal utility per rupee is equal across goods"}],"Moderate":[{"q":"Which concept best matches this situation? A glass of water gives satisfaction to a thirsty consumer.","options":["Cardinal utility","Utility","Marginal utility","TU maximum when MU is zero"],"answer":1,"explanation":"Utility: the want-satisfying power of a commodity for a consumer"},{"q":"Which concept best matches this situation? A consumer assigns 20 utils to one unit and 15 utils to the next.","options":["Total utility","Law of diminishing marginal utility","Cardinal utility","TU falls when MU is negative"],"answer":2,"explanation":"Cardinal utility: the approach that assumes utility can be measured numerically in units such as utils"},{"q":"Which concept best matches this situation? Utility from four units taken together is measured.","options":["Marginal utility","TU–MU relation while MU is positive","Single-commodity consumer equilibrium","Total utility"],"answer":3,"explanation":"Total utility: the total satisfaction obtained from consuming all units of a commodity"},{"q":"Which concept best matches this situation? TU rises from 60 to 72 when one more unit is consumed, so the extra 12 is MU.","options":["Marginal utility","Law of diminishing marginal utility","TU maximum when MU is zero","Law of equi-marginal utility"],"answer":0,"explanation":"Marginal utility: the change in total utility caused by consuming one additional unit of a commodity"},{"q":"Which concept best matches this situation? Successive slices of pizza give a hungry person less additional satisfaction.","options":["TU–MU relation while MU is positive","Law of diminishing marginal utility","TU falls when MU is negative","Utility"],"answer":1,"explanation":"Law of diminishing marginal utility: as consumption of a commodity increases, marginal utility tends to decline, other things remaining the same"},{"q":"Which concept best matches this situation? Each additional unit adds some positive satisfaction to total utility.","options":["TU maximum when MU is zero","Single-commodity consumer equilibrium","TU–MU relation while MU is positive","Cardinal utility"],"answer":2,"explanation":"TU–MU relation while MU is positive: total utility rises as long as marginal utility remains positive"},{"q":"Which concept best matches this situation? An extra unit adds no satisfaction and TU stops rising.","options":["TU falls when MU is negative","Law of equi-marginal utility","Total utility","TU maximum when MU is zero"],"answer":3,"explanation":"TU maximum when MU is zero: total utility reaches its maximum when marginal utility becomes zero"},{"q":"Which concept best matches this situation? Overconsumption makes an extra unit reduce satisfaction.","options":["TU falls when MU is negative","Single-commodity consumer equilibrium","Utility","Marginal utility"],"answer":0,"explanation":"TU falls when MU is negative: negative marginal utility reduces total utility"},{"q":"Which concept best matches this situation? The consumer keeps buying until the utility from the next rupee spent matches its price.","options":["Law of equi-marginal utility","Single-commodity consumer equilibrium","Cardinal utility","Law of diminishing marginal utility"],"answer":1,"explanation":"Single-commodity consumer equilibrium: the consumer is in equilibrium when marginal utility in money terms equals the price, subject to diminishing marginal utility"},{"q":"Which concept best matches this situation? The consumer reallocates spending until MUx/Px equals MUy/Py.","options":["Utility","Total utility","Law of equi-marginal utility","TU–MU relation while MU is positive"],"answer":2,"explanation":"Law of equi-marginal utility: with several goods, satisfaction is maximised by allocating expenditure so marginal utility per rupee is equal across goods"}]}},{"id":"cbse-11-micro-ch4","board":"CBSE","classLevel":11,"subject":"Economics","title":"Consumer’s Equilibrium — Indifference Curve Analysis","chapter":"Reference Chapter 4","sourceLabel":"T.R. Jain & V.K. Ohri — Introductory Microeconomics, Class XI (2020-21 reference edition); filtered to the CBSE 2026–27 Introductory Microeconomics scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Indifference set\"?","options":["a set of commodity combinations that give the consumer the same level of satisfaction","a curve joining combinations of two goods that provide equal satisfaction","as the consumer gets more of one good, the amount of the other good willingly sacrificed for additional units tends to fall","two indifference curves cannot intersect because that would create contradictory satisfaction rankings"],"answer":0,"explanation":"Indifference set: a set of commodity combinations that give the consumer the same level of satisfaction"},{"q":"Which statement best explains \"Indifference curve\"?","options":["the amount of one good the consumer is willing to sacrifice for one more unit of another while maintaining the same satisfaction","a curve joining combinations of two goods that provide equal satisfaction","the usual IC shape resulting from diminishing marginal rate of substitution","all combinations of goods affordable with the consumer’s income at given prices"],"answer":1,"explanation":"Indifference curve: a curve joining combinations of two goods that provide equal satisfaction"},{"q":"Which statement best explains \"Marginal Rate of Substitution\"?","options":["as the consumer gets more of one good, the amount of the other good willingly sacrificed for additional units tends to fall","an indifference curve farther from the origin represents a higher satisfaction level under monotonic preferences","the amount of one good the consumer is willing to sacrifice for one more unit of another while maintaining the same satisfaction","combinations of two goods that exactly exhaust the consumer’s income at given prices"],"answer":2,"explanation":"Marginal Rate of Substitution: the amount of one good the consumer is willing to sacrifice for one more unit of another while maintaining the same satisfaction"},{"q":"Which statement best explains \"Diminishing MRS\"?","options":["the usual IC shape resulting from diminishing marginal rate of substitution","two indifference curves cannot intersect because that would create contradictory satisfaction rankings","the highest attainable indifference curve is reached where the budget line is tangent to a convex IC, so MRS equals the price ratio","as the consumer gets more of one good, the amount of the other good willingly sacrificed for additional units tends to fall"],"answer":3,"explanation":"Diminishing MRS: as the consumer gets more of one good, the amount of the other good willingly sacrificed for additional units tends to fall"},{"q":"Which statement best explains \"Convex indifference curve\"?","options":["the usual IC shape resulting from diminishing marginal rate of substitution","an indifference curve farther from the origin represents a higher satisfaction level under monotonic preferences","all combinations of goods affordable with the consumer’s income at given prices","a set of commodity combinations that give the consumer the same level of satisfaction"],"answer":0,"explanation":"Convex indifference curve: the usual IC shape resulting from diminishing marginal rate of substitution"},{"q":"Which statement best explains \"Higher indifference curve\"?","options":["two indifference curves cannot intersect because that would create contradictory satisfaction rankings","an indifference curve farther from the origin represents a higher satisfaction level under monotonic preferences","combinations of two goods that exactly exhaust the consumer’s income at given prices","a curve joining combinations of two goods that provide equal satisfaction"],"answer":1,"explanation":"Higher indifference curve: an indifference curve farther from the origin represents a higher satisfaction level under monotonic preferences"},{"q":"Which statement best explains \"Non-intersection of indifference curves\"?","options":["all combinations of goods affordable with the consumer’s income at given prices","the highest attainable indifference curve is reached where the budget line is tangent to a convex IC, so MRS equals the price ratio","two indifference curves cannot intersect because that would create contradictory satisfaction rankings","the amount of one good the consumer is willing to sacrifice for one more unit of another while maintaining the same satisfaction"],"answer":2,"explanation":"Non-intersection of indifference curves: two indifference curves cannot intersect because that would create contradictory satisfaction rankings"},{"q":"Which statement best explains \"Budget set\"?","options":["combinations of two goods that exactly exhaust the consumer’s income at given prices","a set of commodity combinations that give the consumer the same level of satisfaction","as the consumer gets more of one good, the amount of the other good willingly sacrificed for additional units tends to fall","all combinations of goods affordable with the consumer’s income at given prices"],"answer":3,"explanation":"Budget set: all combinations of goods affordable with the consumer’s income at given prices"},{"q":"Which statement best explains \"Budget line\"?","options":["combinations of two goods that exactly exhaust the consumer’s income at given prices","the highest attainable indifference curve is reached where the budget line is tangent to a convex IC, so MRS equals the price ratio","a curve joining combinations of two goods that provide equal satisfaction","the usual IC shape resulting from diminishing marginal rate of substitution"],"answer":0,"explanation":"Budget line: combinations of two goods that exactly exhaust the consumer’s income at given prices"},{"q":"Which statement best explains \"IC consumer equilibrium\"?","options":["a set of commodity combinations that give the consumer the same level of satisfaction","the highest attainable indifference curve is reached where the budget line is tangent to a convex IC, so MRS equals the price ratio","the amount of one good the consumer is willing to sacrifice for one more unit of another while maintaining the same satisfaction","an indifference curve farther from the origin represents a higher satisfaction level under monotonic preferences"],"answer":1,"explanation":"IC consumer equilibrium: the highest attainable indifference curve is reached where the budget line is tangent to a convex IC, so MRS equals the price ratio"}],"Moderate":[{"q":"Which concept best matches this situation? Bundles A and B are different but the consumer is equally satisfied with both.","options":["Indifference curve","Indifference set","Diminishing MRS","Non-intersection of indifference curves"],"answer":1,"explanation":"Indifference set: a set of commodity combinations that give the consumer the same level of satisfaction"},{"q":"Which concept best matches this situation? The consumer is indifferent among all bundles lying on one curve.","options":["Marginal Rate of Substitution","Convex indifference curve","Indifference curve","Budget set"],"answer":2,"explanation":"Indifference curve: a curve joining combinations of two goods that provide equal satisfaction"},{"q":"Which concept best matches this situation? The consumer gives up fewer units of Y for each additional unit of X.","options":["Diminishing MRS","Higher indifference curve","Budget line","Marginal Rate of Substitution"],"answer":3,"explanation":"Marginal Rate of Substitution: the amount of one good the consumer is willing to sacrifice for one more unit of another while maintaining the same satisfaction"},{"q":"Which concept best matches this situation? Moving rightward on an IC, the sacrifice of Y for each extra X becomes smaller.","options":["Diminishing MRS","Convex indifference curve","Non-intersection of indifference curves","IC consumer equilibrium"],"answer":0,"explanation":"Diminishing MRS: as the consumer gets more of one good, the amount of the other good willingly sacrificed for additional units tends to fall"},{"q":"Which concept best matches this situation? The curve becomes flatter as the consumer substitutes X for Y.","options":["Higher indifference curve","Convex indifference curve","Budget set","Indifference set"],"answer":1,"explanation":"Convex indifference curve: the usual IC shape resulting from diminishing marginal rate of substitution"},{"q":"Which concept best matches this situation? A bundle on IC2 contains more of at least one good than a comparable bundle on IC1.","options":["Non-intersection of indifference curves","Budget line","Higher indifference curve","Indifference curve"],"answer":2,"explanation":"Higher indifference curve: an indifference curve farther from the origin represents a higher satisfaction level under monotonic preferences"},{"q":"Which concept best matches this situation? One bundle cannot simultaneously imply equal and higher satisfaction through intersecting curves.","options":["Budget set","IC consumer equilibrium","Marginal Rate of Substitution","Non-intersection of indifference curves"],"answer":3,"explanation":"Non-intersection of indifference curves: two indifference curves cannot intersect because that would create contradictory satisfaction rankings"},{"q":"Which concept best matches this situation? Every bundle whose total expenditure does not exceed income is affordable.","options":["Budget set","Budget line","Indifference set","Diminishing MRS"],"answer":0,"explanation":"Budget set: all combinations of goods affordable with the consumer’s income at given prices"},{"q":"Which concept best matches this situation? PxX + PyY = M describes the boundary of affordable bundles.","options":["IC consumer equilibrium","Budget line","Indifference curve","Convex indifference curve"],"answer":1,"explanation":"Budget line: combinations of two goods that exactly exhaust the consumer’s income at given prices"},{"q":"Which concept best matches this situation? At equilibrium MRSxy = Px/Py and the chosen IC is attainable.","options":["Indifference set","Marginal Rate of Substitution","IC consumer equilibrium","Higher indifference curve"],"answer":2,"explanation":"IC consumer equilibrium: the highest attainable indifference curve is reached where the budget line is tangent to a convex IC, so MRS equals the price ratio"}]}},{"id":"cbse-11-micro-ch5","board":"CBSE","classLevel":11,"subject":"Economics","title":"Theory of Demand","chapter":"Reference Chapter 5","sourceLabel":"T.R. Jain & V.K. Ohri — Introductory Microeconomics, Class XI (2020-21 reference edition); filtered to the CBSE 2026–27 Introductory Microeconomics scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Demand\"?","options":["the quantity of a commodity a consumer is willing and able to buy at a given price during a given period","a table showing quantities demanded at different possible prices","a graphical representation of the relationship between price and quantity demanded","a decrease in quantity demanded caused solely by a rise in the commodity’s own price"],"answer":0,"explanation":"Demand: the quantity of a commodity a consumer is willing and able to buy at a given price during a given period"},{"q":"Which statement best explains \"Demand schedule\"?","options":["the total quantity demanded by all consumers in the market at a given price","a table showing quantities demanded at different possible prices","other things remaining constant, quantity demanded generally varies inversely with own price","a rightward shift of the demand curve caused by a favourable non-price determinant"],"answer":1,"explanation":"Demand schedule: a table showing quantities demanded at different possible prices"},{"q":"Which statement best explains \"Market demand\"?","options":["a graphical representation of the relationship between price and quantity demanded","an increase in quantity demanded caused solely by a fall in the commodity’s own price","the total quantity demanded by all consumers in the market at a given price","goods for which a rise in the price of one tends to increase demand for the other"],"answer":2,"explanation":"Market demand: the total quantity demanded by all consumers in the market at a given price"},{"q":"Which statement best explains \"Demand curve\"?","options":["other things remaining constant, quantity demanded generally varies inversely with own price","a decrease in quantity demanded caused solely by a rise in the commodity’s own price","goods used together so a rise in the price of one tends to reduce demand for the other","a graphical representation of the relationship between price and quantity demanded"],"answer":3,"explanation":"Demand curve: a graphical representation of the relationship between price and quantity demanded"},{"q":"Which statement best explains \"Law of demand\"?","options":["other things remaining constant, quantity demanded generally varies inversely with own price","an increase in quantity demanded caused solely by a fall in the commodity’s own price","a rightward shift of the demand curve caused by a favourable non-price determinant","the quantity of a commodity a consumer is willing and able to buy at a given price during a given period"],"answer":0,"explanation":"Law of demand: other things remaining constant, quantity demanded generally varies inversely with own price"},{"q":"Which statement best explains \"Extension of demand\"?","options":["a decrease in quantity demanded caused solely by a rise in the commodity’s own price","an increase in quantity demanded caused solely by a fall in the commodity’s own price","goods for which a rise in the price of one tends to increase demand for the other","a table showing quantities demanded at different possible prices"],"answer":1,"explanation":"Extension of demand: an increase in quantity demanded caused solely by a fall in the commodity’s own price"},{"q":"Which statement best explains \"Contraction of demand\"?","options":["a rightward shift of the demand curve caused by a favourable non-price determinant","goods used together so a rise in the price of one tends to reduce demand for the other","a decrease in quantity demanded caused solely by a rise in the commodity’s own price","the total quantity demanded by all consumers in the market at a given price"],"answer":2,"explanation":"Contraction of demand: a decrease in quantity demanded caused solely by a rise in the commodity’s own price"},{"q":"Which statement best explains \"Increase in demand\"?","options":["goods for which a rise in the price of one tends to increase demand for the other","the quantity of a commodity a consumer is willing and able to buy at a given price during a given period","a graphical representation of the relationship between price and quantity demanded","a rightward shift of the demand curve caused by a favourable non-price determinant"],"answer":3,"explanation":"Increase in demand: a rightward shift of the demand curve caused by a favourable non-price determinant"},{"q":"Which statement best explains \"Substitute goods\"?","options":["goods for which a rise in the price of one tends to increase demand for the other","goods used together so a rise in the price of one tends to reduce demand for the other","a table showing quantities demanded at different possible prices","other things remaining constant, quantity demanded generally varies inversely with own price"],"answer":0,"explanation":"Substitute goods: goods for which a rise in the price of one tends to increase demand for the other"},{"q":"Which statement best explains \"Complementary goods\"?","options":["the quantity of a commodity a consumer is willing and able to buy at a given price during a given period","goods used together so a rise in the price of one tends to reduce demand for the other","the total quantity demanded by all consumers in the market at a given price","an increase in quantity demanded caused solely by a fall in the commodity’s own price"],"answer":1,"explanation":"Complementary goods: goods used together so a rise in the price of one tends to reduce demand for the other"}],"Moderate":[{"q":"Which concept best matches this situation? At ₹20 a buyer both wants and can afford 3 units this week.","options":["Demand schedule","Demand","Demand curve","Contraction of demand"],"answer":1,"explanation":"Demand: the quantity of a commodity a consumer is willing and able to buy at a given price during a given period"},{"q":"Which concept best matches this situation? A table lists price ₹10, ₹20 and ₹30 with corresponding quantities.","options":["Market demand","Law of demand","Demand schedule","Increase in demand"],"answer":2,"explanation":"Demand schedule: a table showing quantities demanded at different possible prices"},{"q":"Which concept best matches this situation? Demand of A, B and C is added horizontally at each price.","options":["Demand curve","Extension of demand","Substitute goods","Market demand"],"answer":3,"explanation":"Market demand: the total quantity demanded by all consumers in the market at a given price"},{"q":"Which concept best matches this situation? Price is shown on the vertical axis and quantity on the horizontal axis.","options":["Demand curve","Law of demand","Contraction of demand","Complementary goods"],"answer":0,"explanation":"Demand curve: a graphical representation of the relationship between price and quantity demanded"},{"q":"Which concept best matches this situation? When price falls, quantity demanded rises while other determinants stay unchanged.","options":["Extension of demand","Law of demand","Increase in demand","Demand"],"answer":1,"explanation":"Law of demand: other things remaining constant, quantity demanded generally varies inversely with own price"},{"q":"Which concept best matches this situation? A movement downward along the same demand curve occurs after price falls.","options":["Contraction of demand","Substitute goods","Extension of demand","Demand schedule"],"answer":2,"explanation":"Extension of demand: an increase in quantity demanded caused solely by a fall in the commodity’s own price"},{"q":"Which concept best matches this situation? A movement upward along the same demand curve occurs after price rises.","options":["Increase in demand","Complementary goods","Market demand","Contraction of demand"],"answer":3,"explanation":"Contraction of demand: a decrease in quantity demanded caused solely by a rise in the commodity’s own price"},{"q":"Which concept best matches this situation? At every price consumers buy more after income rises for a normal good.","options":["Increase in demand","Substitute goods","Demand","Demand curve"],"answer":0,"explanation":"Increase in demand: a rightward shift of the demand curve caused by a favourable non-price determinant"},{"q":"Which concept best matches this situation? If tea becomes dearer, some consumers switch toward coffee.","options":["Complementary goods","Substitute goods","Demand schedule","Law of demand"],"answer":1,"explanation":"Substitute goods: goods for which a rise in the price of one tends to increase demand for the other"},{"q":"Which concept best matches this situation? A sharp rise in petrol price may reduce demand for petrol-intensive car use.","options":["Demand","Market demand","Complementary goods","Extension of demand"],"answer":2,"explanation":"Complementary goods: goods used together so a rise in the price of one tends to reduce demand for the other"}]}},{"id":"cbse-11-micro-ch6","board":"CBSE","classLevel":11,"subject":"Economics","title":"Price Elasticity of Demand","chapter":"Reference Chapter 6","sourceLabel":"T.R. Jain & V.K. Ohri — Introductory Microeconomics, Class XI (2020-21 reference edition); filtered to the CBSE 2026–27 Introductory Microeconomics scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Price elasticity of demand\"?","options":["the responsiveness of quantity demanded to a change in the commodity’s own price","elasticity measured as percentage change in quantity demanded divided by percentage change in price, usually taken in absolute magnitude","an extremely small price change causes an unlimited response in quantity demanded, represented by a horizontal demand curve","percentage change in quantity demanded is smaller than the percentage change in price, so elasticity is less than one"],"answer":0,"explanation":"Price elasticity of demand: the responsiveness of quantity demanded to a change in the commodity’s own price"},{"q":"Which statement best explains \"Percentage method\"?","options":["quantity demanded does not change when price changes, so elasticity is zero","elasticity measured as percentage change in quantity demanded divided by percentage change in price, usually taken in absolute magnitude","percentage change in quantity demanded equals percentage change in price in magnitude","more and closer substitutes generally make demand more price elastic"],"answer":1,"explanation":"Percentage method: elasticity measured as percentage change in quantity demanded divided by percentage change in price, usually taken in absolute magnitude"},{"q":"Which statement best explains \"Perfectly inelastic demand\"?","options":["an extremely small price change causes an unlimited response in quantity demanded, represented by a horizontal demand curve","percentage change in quantity demanded is greater than the percentage change in price, so elasticity exceeds one","quantity demanded does not change when price changes, so elasticity is zero","necessities generally have less elastic demand than luxuries, other things equal"],"answer":2,"explanation":"Perfectly inelastic demand: quantity demanded does not change when price changes, so elasticity is zero"},{"q":"Which statement best explains \"Perfectly elastic demand\"?","options":["percentage change in quantity demanded equals percentage change in price in magnitude","percentage change in quantity demanded is smaller than the percentage change in price, so elasticity is less than one","when price and total expenditure move in opposite directions demand is elastic, while the same direction indicates inelastic demand","an extremely small price change causes an unlimited response in quantity demanded, represented by a horizontal demand curve"],"answer":3,"explanation":"Perfectly elastic demand: an extremely small price change causes an unlimited response in quantity demanded, represented by a horizontal demand curve"},{"q":"Which statement best explains \"Unitary elastic demand\"?","options":["percentage change in quantity demanded equals percentage change in price in magnitude","percentage change in quantity demanded is greater than the percentage change in price, so elasticity exceeds one","more and closer substitutes generally make demand more price elastic","the responsiveness of quantity demanded to a change in the commodity’s own price"],"answer":0,"explanation":"Unitary elastic demand: percentage change in quantity demanded equals percentage change in price in magnitude"},{"q":"Which statement best explains \"Relatively elastic demand\"?","options":["percentage change in quantity demanded is smaller than the percentage change in price, so elasticity is less than one","percentage change in quantity demanded is greater than the percentage change in price, so elasticity exceeds one","necessities generally have less elastic demand than luxuries, other things equal","elasticity measured as percentage change in quantity demanded divided by percentage change in price, usually taken in absolute magnitude"],"answer":1,"explanation":"Relatively elastic demand: percentage change in quantity demanded is greater than the percentage change in price, so elasticity exceeds one"},{"q":"Which statement best explains \"Relatively inelastic demand\"?","options":["more and closer substitutes generally make demand more price elastic","when price and total expenditure move in opposite directions demand is elastic, while the same direction indicates inelastic demand","percentage change in quantity demanded is smaller than the percentage change in price, so elasticity is less than one","quantity demanded does not change when price changes, so elasticity is zero"],"answer":2,"explanation":"Relatively inelastic demand: percentage change in quantity demanded is smaller than the percentage change in price, so elasticity is less than one"},{"q":"Which statement best explains \"Availability of substitutes\"?","options":["necessities generally have less elastic demand than luxuries, other things equal","the responsiveness of quantity demanded to a change in the commodity’s own price","an extremely small price change causes an unlimited response in quantity demanded, represented by a horizontal demand curve","more and closer substitutes generally make demand more price elastic"],"answer":3,"explanation":"Availability of substitutes: more and closer substitutes generally make demand more price elastic"},{"q":"Which statement best explains \"Nature of commodity\"?","options":["necessities generally have less elastic demand than luxuries, other things equal","when price and total expenditure move in opposite directions demand is elastic, while the same direction indicates inelastic demand","elasticity measured as percentage change in quantity demanded divided by percentage change in price, usually taken in absolute magnitude","percentage change in quantity demanded equals percentage change in price in magnitude"],"answer":0,"explanation":"Nature of commodity: necessities generally have less elastic demand than luxuries, other things equal"},{"q":"Which statement best explains \"Total expenditure relation\"?","options":["the responsiveness of quantity demanded to a change in the commodity’s own price","when price and total expenditure move in opposite directions demand is elastic, while the same direction indicates inelastic demand","quantity demanded does not change when price changes, so elasticity is zero","percentage change in quantity demanded is greater than the percentage change in price, so elasticity exceeds one"],"answer":1,"explanation":"Total expenditure relation: when price and total expenditure move in opposite directions demand is elastic, while the same direction indicates inelastic demand"}],"Moderate":[{"q":"Which concept best matches this situation? A 10% price fall causes quantity demanded to rise by 20%.","options":["Percentage method","Price elasticity of demand","Perfectly elastic demand","Relatively inelastic demand"],"answer":1,"explanation":"Price elasticity of demand: the responsiveness of quantity demanded to a change in the commodity’s own price"},{"q":"Which concept best matches this situation? Quantity changes 20% when price changes 10%, giving elasticity magnitude 2.","options":["Perfectly inelastic demand","Unitary elastic demand","Percentage method","Availability of substitutes"],"answer":2,"explanation":"Percentage method: elasticity measured as percentage change in quantity demanded divided by percentage change in price, usually taken in absolute magnitude"},{"q":"Which concept best matches this situation? The demand curve is vertical.","options":["Perfectly elastic demand","Relatively elastic demand","Nature of commodity","Perfectly inelastic demand"],"answer":3,"explanation":"Perfectly inelastic demand: quantity demanded does not change when price changes, so elasticity is zero"},{"q":"Which concept best matches this situation? At one market price the firm can sell any quantity under the idealised case.","options":["Perfectly elastic demand","Unitary elastic demand","Relatively inelastic demand","Total expenditure relation"],"answer":0,"explanation":"Perfectly elastic demand: an extremely small price change causes an unlimited response in quantity demanded, represented by a horizontal demand curve"},{"q":"Which concept best matches this situation? Price falls 10% and quantity demanded rises 10%.","options":["Relatively elastic demand","Unitary elastic demand","Availability of substitutes","Price elasticity of demand"],"answer":1,"explanation":"Unitary elastic demand: percentage change in quantity demanded equals percentage change in price in magnitude"},{"q":"Which concept best matches this situation? Price falls 5% and quantity demanded rises 15%.","options":["Relatively inelastic demand","Nature of commodity","Relatively elastic demand","Percentage method"],"answer":2,"explanation":"Relatively elastic demand: percentage change in quantity demanded is greater than the percentage change in price, so elasticity exceeds one"},{"q":"Which concept best matches this situation? Price rises 10% and quantity demanded falls only 3%.","options":["Availability of substitutes","Total expenditure relation","Perfectly inelastic demand","Relatively inelastic demand"],"answer":3,"explanation":"Relatively inelastic demand: percentage change in quantity demanded is smaller than the percentage change in price, so elasticity is less than one"},{"q":"Which concept best matches this situation? Consumers can easily switch among several similar brands.","options":["Availability of substitutes","Nature of commodity","Price elasticity of demand","Perfectly elastic demand"],"answer":0,"explanation":"Availability of substitutes: more and closer substitutes generally make demand more price elastic"},{"q":"Which concept best matches this situation? Essential medicines are usually less price-responsive than discretionary luxury purchases.","options":["Total expenditure relation","Nature of commodity","Percentage method","Unitary elastic demand"],"answer":1,"explanation":"Nature of commodity: necessities generally have less elastic demand than luxuries, other things equal"},{"q":"Which concept best matches this situation? Price falls and total spending rises, indicating elastic demand.","options":["Price elasticity of demand","Perfectly inelastic demand","Total expenditure relation","Relatively elastic demand"],"answer":2,"explanation":"Total expenditure relation: when price and total expenditure move in opposite directions demand is elastic, while the same direction indicates inelastic demand"}]}},{"id":"cbse-11-micro-ch7","board":"CBSE","classLevel":11,"subject":"Economics","title":"Production Function and Returns to a Factor","chapter":"Reference Chapter 7","sourceLabel":"T.R. Jain & V.K. Ohri — Introductory Microeconomics, Class XI (2020-21 reference edition); filtered to the CBSE 2026–27 Introductory Microeconomics scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Production function\"?","options":["the technical relationship between physical inputs and maximum output obtainable with given technology","a period in which at least one factor of production is fixed","the total output produced by all units of the variable factor with given fixed factors","the initial phase where marginal product rises as more units of the variable factor are combined with fixed factors"],"answer":0,"explanation":"Production function: the technical relationship between physical inputs and maximum output obtainable with given technology"},{"q":"Which statement best explains \"Short run\"?","options":["a period long enough for all factors of production to be variable","a period in which at least one factor of production is fixed","the change in total product caused by employing one additional unit of the variable factor","the phase where marginal product remains positive but declines as more variable factor is added to fixed factors"],"answer":1,"explanation":"Short run: a period in which at least one factor of production is fixed"},{"q":"Which statement best explains \"Long run\"?","options":["the total output produced by all units of the variable factor with given fixed factors","total product per unit of the variable factor","a period long enough for all factors of production to be variable","the phase where marginal product becomes negative and total product falls"],"answer":2,"explanation":"Long run: a period long enough for all factors of production to be variable"},{"q":"Which statement best explains \"Total product\"?","options":["the change in total product caused by employing one additional unit of the variable factor","the initial phase where marginal product rises as more units of the variable factor are combined with fixed factors","AP rises when MP is above AP, is maximum when MP equals AP, and falls when MP is below AP","the total output produced by all units of the variable factor with given fixed factors"],"answer":3,"explanation":"Total product: the total output produced by all units of the variable factor with given fixed factors"},{"q":"Which statement best explains \"Marginal product\"?","options":["the change in total product caused by employing one additional unit of the variable factor","total product per unit of the variable factor","the phase where marginal product remains positive but declines as more variable factor is added to fixed factors","the technical relationship between physical inputs and maximum output obtainable with given technology"],"answer":0,"explanation":"Marginal product: the change in total product caused by employing one additional unit of the variable factor"},{"q":"Which statement best explains \"Average product\"?","options":["the initial phase where marginal product rises as more units of the variable factor are combined with fixed factors","total product per unit of the variable factor","the phase where marginal product becomes negative and total product falls","a period in which at least one factor of production is fixed"],"answer":1,"explanation":"Average product: total product per unit of the variable factor"},{"q":"Which statement best explains \"Increasing returns to a factor\"?","options":["the phase where marginal product remains positive but declines as more variable factor is added to fixed factors","AP rises when MP is above AP, is maximum when MP equals AP, and falls when MP is below AP","the initial phase where marginal product rises as more units of the variable factor are combined with fixed factors","a period long enough for all factors of production to be variable"],"answer":2,"explanation":"Increasing returns to a factor: the initial phase where marginal product rises as more units of the variable factor are combined with fixed factors"},{"q":"Which statement best explains \"Diminishing returns to a factor\"?","options":["the phase where marginal product becomes negative and total product falls","the technical relationship between physical inputs and maximum output obtainable with given technology","the total output produced by all units of the variable factor with given fixed factors","the phase where marginal product remains positive but declines as more variable factor is added to fixed factors"],"answer":3,"explanation":"Diminishing returns to a factor: the phase where marginal product remains positive but declines as more variable factor is added to fixed factors"},{"q":"Which statement best explains \"Negative returns to a factor\"?","options":["the phase where marginal product becomes negative and total product falls","AP rises when MP is above AP, is maximum when MP equals AP, and falls when MP is below AP","a period in which at least one factor of production is fixed","the change in total product caused by employing one additional unit of the variable factor"],"answer":0,"explanation":"Negative returns to a factor: the phase where marginal product becomes negative and total product falls"},{"q":"Which statement best explains \"AP–MP relation\"?","options":["the technical relationship between physical inputs and maximum output obtainable with given technology","AP rises when MP is above AP, is maximum when MP equals AP, and falls when MP is below AP","a period long enough for all factors of production to be variable","total product per unit of the variable factor"],"answer":1,"explanation":"AP–MP relation: AP rises when MP is above AP, is maximum when MP equals AP, and falls when MP is below AP"}],"Moderate":[{"q":"Which concept best matches this situation? A firm relates labour and capital inputs to units of output.","options":["Short run","Production function","Total product","Increasing returns to a factor"],"answer":1,"explanation":"Production function: the technical relationship between physical inputs and maximum output obtainable with given technology"},{"q":"Which concept best matches this situation? Plant size is fixed while labour hours can be changed.","options":["Long run","Marginal product","Short run","Diminishing returns to a factor"],"answer":2,"explanation":"Short run: a period in which at least one factor of production is fixed"},{"q":"Which concept best matches this situation? The firm can change both plant capacity and labour.","options":["Total product","Average product","Negative returns to a factor","Long run"],"answer":3,"explanation":"Long run: a period long enough for all factors of production to be variable"},{"q":"Which concept best matches this situation? Six workers together produce 120 units.","options":["Total product","Marginal product","Increasing returns to a factor","AP–MP relation"],"answer":0,"explanation":"Total product: the total output produced by all units of the variable factor with given fixed factors"},{"q":"Which concept best matches this situation? TP rises from 100 to 118 when one worker is added, so MP is 18.","options":["Average product","Marginal product","Diminishing returns to a factor","Production function"],"answer":1,"explanation":"Marginal product: the change in total product caused by employing one additional unit of the variable factor"},{"q":"Which concept best matches this situation? 120 units produced by 6 workers gives AP of 20.","options":["Increasing returns to a factor","Negative returns to a factor","Average product","Short run"],"answer":2,"explanation":"Average product: total product per unit of the variable factor"},{"q":"Which concept best matches this situation? Specialisation improves output additions as early workers are added.","options":["Diminishing returns to a factor","AP–MP relation","Long run","Increasing returns to a factor"],"answer":3,"explanation":"Increasing returns to a factor: the initial phase where marginal product rises as more units of the variable factor are combined with fixed factors"},{"q":"Which concept best matches this situation? Additional workers still raise output but by smaller amounts.","options":["Diminishing returns to a factor","Negative returns to a factor","Production function","Total product"],"answer":0,"explanation":"Diminishing returns to a factor: the phase where marginal product remains positive but declines as more variable factor is added to fixed factors"},{"q":"Which concept best matches this situation? Overcrowding causes an additional worker to reduce total output.","options":["AP–MP relation","Negative returns to a factor","Short run","Marginal product"],"answer":1,"explanation":"Negative returns to a factor: the phase where marginal product becomes negative and total product falls"},{"q":"Which concept best matches this situation? A high marginal contribution pulls the average upward.","options":["Production function","Long run","AP–MP relation","Average product"],"answer":2,"explanation":"AP–MP relation: AP rises when MP is above AP, is maximum when MP equals AP, and falls when MP is below AP"}]}},{"id":"cbse-11-micro-ch8","board":"CBSE","classLevel":11,"subject":"Economics","title":"Concepts of Cost","chapter":"Reference Chapter 8","sourceLabel":"T.R. Jain & V.K. Ohri — Introductory Microeconomics, Class XI (2020-21 reference edition); filtered to the CBSE 2026–27 Introductory Microeconomics scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Total fixed cost\"?","options":["cost that remains unchanged with output in the short run","cost that changes with the level of output","total fixed cost divided by output","the change in total cost caused by producing one additional unit"],"answer":0,"explanation":"Total fixed cost: cost that remains unchanged with output in the short run"},{"q":"Which statement best explains \"Total variable cost\"?","options":["the sum of total fixed cost and total variable cost","cost that changes with the level of output","total variable cost divided by output","the vertical difference between total cost and total variable cost equals total fixed cost"],"answer":1,"explanation":"Total variable cost: cost that changes with the level of output"},{"q":"Which statement best explains \"Total cost\"?","options":["total fixed cost divided by output","total cost divided by output and also equal to AFC plus AVC","the sum of total fixed cost and total variable cost","AC falls when MC is below AC, is minimum when MC equals AC, and rises when MC is above AC"],"answer":2,"explanation":"Total cost: the sum of total fixed cost and total variable cost"},{"q":"Which statement best explains \"Average fixed cost\"?","options":["total variable cost divided by output","the change in total cost caused by producing one additional unit","AVC falls when MC is below AVC, is minimum when MC equals AVC, and rises when MC is above AVC","total fixed cost divided by output"],"answer":3,"explanation":"Average fixed cost: total fixed cost divided by output"},{"q":"Which statement best explains \"Average variable cost\"?","options":["total variable cost divided by output","total cost divided by output and also equal to AFC plus AVC","the vertical difference between total cost and total variable cost equals total fixed cost","cost that remains unchanged with output in the short run"],"answer":0,"explanation":"Average variable cost: total variable cost divided by output"},{"q":"Which statement best explains \"Average cost\"?","options":["the change in total cost caused by producing one additional unit","total cost divided by output and also equal to AFC plus AVC","AC falls when MC is below AC, is minimum when MC equals AC, and rises when MC is above AC","cost that changes with the level of output"],"answer":1,"explanation":"Average cost: total cost divided by output and also equal to AFC plus AVC"},{"q":"Which statement best explains \"Marginal cost\"?","options":["the vertical difference between total cost and total variable cost equals total fixed cost","AVC falls when MC is below AVC, is minimum when MC equals AVC, and rises when MC is above AVC","the change in total cost caused by producing one additional unit","the sum of total fixed cost and total variable cost"],"answer":2,"explanation":"Marginal cost: the change in total cost caused by producing one additional unit"},{"q":"Which statement best explains \"TFC–TC–TVC relation\"?","options":["AC falls when MC is below AC, is minimum when MC equals AC, and rises when MC is above AC","cost that remains unchanged with output in the short run","total fixed cost divided by output","the vertical difference between total cost and total variable cost equals total fixed cost"],"answer":3,"explanation":"TFC–TC–TVC relation: the vertical difference between total cost and total variable cost equals total fixed cost"},{"q":"Which statement best explains \"MC–AC relation\"?","options":["AC falls when MC is below AC, is minimum when MC equals AC, and rises when MC is above AC","AVC falls when MC is below AVC, is minimum when MC equals AVC, and rises when MC is above AVC","cost that changes with the level of output","total variable cost divided by output"],"answer":0,"explanation":"MC–AC relation: AC falls when MC is below AC, is minimum when MC equals AC, and rises when MC is above AC"},{"q":"Which statement best explains \"MC–AVC relation\"?","options":["cost that remains unchanged with output in the short run","AVC falls when MC is below AVC, is minimum when MC equals AVC, and rises when MC is above AVC","the sum of total fixed cost and total variable cost","total cost divided by output and also equal to AFC plus AVC"],"answer":1,"explanation":"MC–AVC relation: AVC falls when MC is below AVC, is minimum when MC equals AVC, and rises when MC is above AVC"}],"Moderate":[{"q":"Which concept best matches this situation? Factory rent is ₹50,000 whether output is zero or 1,000 units.","options":["Total variable cost","Total fixed cost","Average fixed cost","Marginal cost"],"answer":1,"explanation":"Total fixed cost: cost that remains unchanged with output in the short run"},{"q":"Which concept best matches this situation? Raw-material cost rises as more units are produced.","options":["Total cost","Average variable cost","Total variable cost","TFC–TC–TVC relation"],"answer":2,"explanation":"Total variable cost: cost that changes with the level of output"},{"q":"Which concept best matches this situation? TFC ₹100 plus TVC ₹300 gives TC ₹400.","options":["Average fixed cost","Average cost","MC–AC relation","Total cost"],"answer":3,"explanation":"Total cost: the sum of total fixed cost and total variable cost"},{"q":"Which concept best matches this situation? A fixed cost of ₹100 over 20 units gives AFC ₹5.","options":["Average fixed cost","Average variable cost","Marginal cost","MC–AVC relation"],"answer":0,"explanation":"Average fixed cost: total fixed cost divided by output"},{"q":"Which concept best matches this situation? TVC ₹300 over 20 units gives AVC ₹15.","options":["Average cost","Average variable cost","TFC–TC–TVC relation","Total fixed cost"],"answer":1,"explanation":"Average variable cost: total variable cost divided by output"},{"q":"Which concept best matches this situation? If AFC is ₹5 and AVC is ₹15, AC is ₹20.","options":["Marginal cost","MC–AC relation","Average cost","Total variable cost"],"answer":2,"explanation":"Average cost: total cost divided by output and also equal to AFC plus AVC"},{"q":"Which concept best matches this situation? TC rises from ₹400 to ₹430 when output rises by one unit, so MC is ₹30.","options":["TFC–TC–TVC relation","MC–AVC relation","Total cost","Marginal cost"],"answer":3,"explanation":"Marginal cost: the change in total cost caused by producing one additional unit"},{"q":"Which concept best matches this situation? TC and TVC curves remain separated by the constant fixed cost.","options":["TFC–TC–TVC relation","MC–AC relation","Total fixed cost","Average fixed cost"],"answer":0,"explanation":"TFC–TC–TVC relation: the vertical difference between total cost and total variable cost equals total fixed cost"},{"q":"Which concept best matches this situation? A marginal cost lower than the current average pulls the average down.","options":["MC–AVC relation","MC–AC relation","Total variable cost","Average variable cost"],"answer":1,"explanation":"MC–AC relation: AC falls when MC is below AC, is minimum when MC equals AC, and rises when MC is above AC"},{"q":"Which concept best matches this situation? The marginal value pulls the variable-cost average toward itself.","options":["Total fixed cost","Total cost","MC–AVC relation","Average cost"],"answer":2,"explanation":"MC–AVC relation: AVC falls when MC is below AVC, is minimum when MC equals AVC, and rises when MC is above AVC"}]}},{"id":"cbse-11-micro-ch9","board":"CBSE","classLevel":11,"subject":"Economics","title":"Concept of Revenue","chapter":"Reference Chapter 9","sourceLabel":"T.R. Jain & V.K. Ohri — Introductory Microeconomics, Class XI (2020-21 reference edition); filtered to the CBSE 2026–27 Introductory Microeconomics scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Total revenue\"?","options":["the total receipts from sale of output, equal to price multiplied by quantity sold","total revenue per unit sold and therefore equal to price","the average revenue curve shows the price the firm can obtain at different quantities and therefore represents its demand curve","when AR falls with output, marginal revenue lies below average revenue because lowering price affects additional revenue"],"answer":0,"explanation":"Total revenue: the total receipts from sale of output, equal to price multiplied by quantity sold"},{"q":"Which statement best explains \"Average revenue\"?","options":["the change in total revenue from selling one additional unit","total revenue per unit sold and therefore equal to price","when the firm can sell every unit at the same price, both average and marginal revenue equal that price","positive marginal revenue adds to total revenue"],"answer":1,"explanation":"Average revenue: total revenue per unit sold and therefore equal to price"},{"q":"Which statement best explains \"Marginal revenue\"?","options":["the average revenue curve shows the price the firm can obtain at different quantities and therefore represents its demand curve","when price must be lowered to sell more output, average revenue falls as output rises","the change in total revenue from selling one additional unit","total revenue reaches a maximum where marginal revenue becomes zero"],"answer":2,"explanation":"Marginal revenue: the change in total revenue from selling one additional unit"},{"q":"Which statement best explains \"AR as firm demand curve\"?","options":["when the firm can sell every unit at the same price, both average and marginal revenue equal that price","when AR falls with output, marginal revenue lies below average revenue because lowering price affects additional revenue","negative marginal revenue means additional sales reduce total revenue","the average revenue curve shows the price the firm can obtain at different quantities and therefore represents its demand curve"],"answer":3,"explanation":"AR as firm demand curve: the average revenue curve shows the price the firm can obtain at different quantities and therefore represents its demand curve"},{"q":"Which statement best explains \"AR = MR under constant price\"?","options":["when the firm can sell every unit at the same price, both average and marginal revenue equal that price","when price must be lowered to sell more output, average revenue falls as output rises","positive marginal revenue adds to total revenue","the total receipts from sale of output, equal to price multiplied by quantity sold"],"answer":0,"explanation":"AR = MR under constant price: when the firm can sell every unit at the same price, both average and marginal revenue equal that price"},{"q":"Which statement best explains \"Downward-sloping AR\"?","options":["when AR falls with output, marginal revenue lies below average revenue because lowering price affects additional revenue","when price must be lowered to sell more output, average revenue falls as output rises","total revenue reaches a maximum where marginal revenue becomes zero","total revenue per unit sold and therefore equal to price"],"answer":1,"explanation":"Downward-sloping AR: when price must be lowered to sell more output, average revenue falls as output rises"},{"q":"Which statement best explains \"MR below AR\"?","options":["positive marginal revenue adds to total revenue","negative marginal revenue means additional sales reduce total revenue","when AR falls with output, marginal revenue lies below average revenue because lowering price affects additional revenue","the change in total revenue from selling one additional unit"],"answer":2,"explanation":"MR below AR: when AR falls with output, marginal revenue lies below average revenue because lowering price affects additional revenue"},{"q":"Which statement best explains \"TR rises when MR is positive\"?","options":["total revenue reaches a maximum where marginal revenue becomes zero","the total receipts from sale of output, equal to price multiplied by quantity sold","the average revenue curve shows the price the firm can obtain at different quantities and therefore represents its demand curve","positive marginal revenue adds to total revenue"],"answer":3,"explanation":"TR rises when MR is positive: positive marginal revenue adds to total revenue"},{"q":"Which statement best explains \"TR maximum when MR is zero\"?","options":["total revenue reaches a maximum where marginal revenue becomes zero","negative marginal revenue means additional sales reduce total revenue","total revenue per unit sold and therefore equal to price","when the firm can sell every unit at the same price, both average and marginal revenue equal that price"],"answer":0,"explanation":"TR maximum when MR is zero: total revenue reaches a maximum where marginal revenue becomes zero"},{"q":"Which statement best explains \"TR falls when MR is negative\"?","options":["the total receipts from sale of output, equal to price multiplied by quantity sold","negative marginal revenue means additional sales reduce total revenue","the change in total revenue from selling one additional unit","when price must be lowered to sell more output, average revenue falls as output rises"],"answer":1,"explanation":"TR falls when MR is negative: negative marginal revenue means additional sales reduce total revenue"}],"Moderate":[{"q":"Which concept best matches this situation? Selling 10 units at ₹20 each gives TR ₹200.","options":["Average revenue","Total revenue","AR as firm demand curve","MR below AR"],"answer":1,"explanation":"Total revenue: the total receipts from sale of output, equal to price multiplied by quantity sold"},{"q":"Which concept best matches this situation? TR ₹200 from 10 units gives AR ₹20.","options":["Marginal revenue","AR = MR under constant price","Average revenue","TR rises when MR is positive"],"answer":2,"explanation":"Average revenue: total revenue per unit sold and therefore equal to price"},{"q":"Which concept best matches this situation? TR rises from ₹200 to ₹218 when one more unit is sold, so MR is ₹18.","options":["AR as firm demand curve","Downward-sloping AR","TR maximum when MR is zero","Marginal revenue"],"answer":3,"explanation":"Marginal revenue: the change in total revenue from selling one additional unit"},{"q":"Which concept best matches this situation? Each point gives price received per unit at a particular sales quantity.","options":["AR as firm demand curve","AR = MR under constant price","MR below AR","TR falls when MR is negative"],"answer":0,"explanation":"AR as firm demand curve: the average revenue curve shows the price the firm can obtain at different quantities and therefore represents its demand curve"},{"q":"Which concept best matches this situation? At a constant market price of ₹10, every additional unit adds ₹10 to TR.","options":["Downward-sloping AR","AR = MR under constant price","TR rises when MR is positive","Total revenue"],"answer":1,"explanation":"AR = MR under constant price: when the firm can sell every unit at the same price, both average and marginal revenue equal that price"},{"q":"Which concept best matches this situation? A firm reduces price from ₹20 to ₹18 to sell more units.","options":["MR below AR","TR maximum when MR is zero","Downward-sloping AR","Average revenue"],"answer":2,"explanation":"Downward-sloping AR: when price must be lowered to sell more output, average revenue falls as output rises"},{"q":"Which concept best matches this situation? The extra revenue from another unit is less than its selling price when price must be cut.","options":["TR rises when MR is positive","TR falls when MR is negative","Marginal revenue","MR below AR"],"answer":3,"explanation":"MR below AR: when AR falls with output, marginal revenue lies below average revenue because lowering price affects additional revenue"},{"q":"Which concept best matches this situation? Each extra unit still increases total receipts.","options":["TR rises when MR is positive","TR maximum when MR is zero","Total revenue","AR as firm demand curve"],"answer":0,"explanation":"TR rises when MR is positive: positive marginal revenue adds to total revenue"},{"q":"Which concept best matches this situation? Selling one more unit adds no extra total revenue.","options":["TR falls when MR is negative","TR maximum when MR is zero","Average revenue","AR = MR under constant price"],"answer":1,"explanation":"TR maximum when MR is zero: total revenue reaches a maximum where marginal revenue becomes zero"},{"q":"Which concept best matches this situation? A price cut needed for more sales lowers total receipts overall.","options":["Total revenue","Marginal revenue","TR falls when MR is negative","Downward-sloping AR"],"answer":2,"explanation":"TR falls when MR is negative: negative marginal revenue means additional sales reduce total revenue"}]}},{"id":"cbse-11-micro-ch10","board":"CBSE","classLevel":11,"subject":"Economics","title":"Producer’s Equilibrium","chapter":"Reference Chapter 10","sourceLabel":"T.R. Jain & V.K. Ohri — Introductory Microeconomics, Class XI (2020-21 reference edition); filtered to the CBSE 2026–27 Introductory Microeconomics scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Producer\"?","options":["an economic unit that organises production of goods or services for sale","the excess of total revenue over total cost","at equilibrium marginal revenue must equal marginal cost","when marginal cost exceeds marginal revenue, the extra unit reduces profit so output should contract"],"answer":0,"explanation":"Producer: an economic unit that organises production of goods or services for sale"},{"q":"Which statement best explains \"Profit\"?","options":["the output level at which the producer maximises profit or minimises loss and has no incentive to change output","the excess of total revenue over total cost","marginal cost must be rising or cut marginal revenue from below at the equilibrium output","producer equilibrium depends on marginal comparison and can occur even when economic profit is only normal"],"answer":1,"explanation":"Profit: the excess of total revenue over total cost"},{"q":"Which statement best explains \"Producer equilibrium\"?","options":["at equilibrium marginal revenue must equal marginal cost","when marginal revenue exceeds marginal cost, producing an additional unit adds to profit so output should expand","the output level at which the producer maximises profit or minimises loss and has no incentive to change output","in the short run a producer can be in equilibrium while incurring a loss if changing output would make the loss larger"],"answer":2,"explanation":"Producer equilibrium: the output level at which the producer maximises profit or minimises loss and has no incentive to change output"},{"q":"Which statement best explains \"First MR–MC condition\"?","options":["marginal cost must be rising or cut marginal revenue from below at the equilibrium output","when marginal cost exceeds marginal revenue, the extra unit reduces profit so output should contract","output should be adjusted until the additional revenue from the last unit equals its additional cost with the stability condition satisfied","at equilibrium marginal revenue must equal marginal cost"],"answer":3,"explanation":"First MR–MC condition: at equilibrium marginal revenue must equal marginal cost"},{"q":"Which statement best explains \"Second MR–MC condition\"?","options":["marginal cost must be rising or cut marginal revenue from below at the equilibrium output","when marginal revenue exceeds marginal cost, producing an additional unit adds to profit so output should expand","producer equilibrium depends on marginal comparison and can occur even when economic profit is only normal","an economic unit that organises production of goods or services for sale"],"answer":0,"explanation":"Second MR–MC condition: marginal cost must be rising or cut marginal revenue from below at the equilibrium output"},{"q":"Which statement best explains \"MR greater than MC\"?","options":["when marginal cost exceeds marginal revenue, the extra unit reduces profit so output should contract","when marginal revenue exceeds marginal cost, producing an additional unit adds to profit so output should expand","in the short run a producer can be in equilibrium while incurring a loss if changing output would make the loss larger","the excess of total revenue over total cost"],"answer":1,"explanation":"MR greater than MC: when marginal revenue exceeds marginal cost, producing an additional unit adds to profit so output should expand"},{"q":"Which statement best explains \"MC greater than MR\"?","options":["producer equilibrium depends on marginal comparison and can occur even when economic profit is only normal","output should be adjusted until the additional revenue from the last unit equals its additional cost with the stability condition satisfied","when marginal cost exceeds marginal revenue, the extra unit reduces profit so output should contract","the output level at which the producer maximises profit or minimises loss and has no incentive to change output"],"answer":2,"explanation":"MC greater than MR: when marginal cost exceeds marginal revenue, the extra unit reduces profit so output should contract"},{"q":"Which statement best explains \"Normal-profit equilibrium logic\"?","options":["in the short run a producer can be in equilibrium while incurring a loss if changing output would make the loss larger","an economic unit that organises production of goods or services for sale","at equilibrium marginal revenue must equal marginal cost","producer equilibrium depends on marginal comparison and can occur even when economic profit is only normal"],"answer":3,"explanation":"Normal-profit equilibrium logic: producer equilibrium depends on marginal comparison and can occur even when economic profit is only normal"},{"q":"Which statement best explains \"Loss-minimising equilibrium\"?","options":["in the short run a producer can be in equilibrium while incurring a loss if changing output would make the loss larger","output should be adjusted until the additional revenue from the last unit equals its additional cost with the stability condition satisfied","the excess of total revenue over total cost","marginal cost must be rising or cut marginal revenue from below at the equilibrium output"],"answer":0,"explanation":"Loss-minimising equilibrium: in the short run a producer can be in equilibrium while incurring a loss if changing output would make the loss larger"},{"q":"Which statement best explains \"Profit-maximisation rule\"?","options":["an economic unit that organises production of goods or services for sale","output should be adjusted until the additional revenue from the last unit equals its additional cost with the stability condition satisfied","the output level at which the producer maximises profit or minimises loss and has no incentive to change output","when marginal revenue exceeds marginal cost, producing an additional unit adds to profit so output should expand"],"answer":1,"explanation":"Profit-maximisation rule: output should be adjusted until the additional revenue from the last unit equals its additional cost with the stability condition satisfied"}],"Moderate":[{"q":"Which concept best matches this situation? A firm combines labour and capital to make products.","options":["Profit","Producer","First MR–MC condition","MC greater than MR"],"answer":1,"explanation":"Producer: an economic unit that organises production of goods or services for sale"},{"q":"Which concept best matches this situation? TR ₹1,000 minus TC ₹800 gives profit ₹200.","options":["Producer equilibrium","Second MR–MC condition","Profit","Normal-profit equilibrium logic"],"answer":2,"explanation":"Profit: the excess of total revenue over total cost"},{"q":"Which concept best matches this situation? Changing output in either direction would reduce the producer’s objective.","options":["First MR–MC condition","MR greater than MC","Loss-minimising equilibrium","Producer equilibrium"],"answer":3,"explanation":"Producer equilibrium: the output level at which the producer maximises profit or minimises loss and has no incentive to change output"},{"q":"Which concept best matches this situation? The last unit adds exactly as much revenue as cost.","options":["First MR–MC condition","Second MR–MC condition","MC greater than MR","Profit-maximisation rule"],"answer":0,"explanation":"First MR–MC condition: at equilibrium marginal revenue must equal marginal cost"},{"q":"Which concept best matches this situation? After equality, MC moves above MR as output expands.","options":["MR greater than MC","Second MR–MC condition","Normal-profit equilibrium logic","Producer"],"answer":1,"explanation":"Second MR–MC condition: marginal cost must be rising or cut marginal revenue from below at the equilibrium output"},{"q":"Which concept best matches this situation? The next unit adds ₹20 revenue but costs only ₹15.","options":["MC greater than MR","Loss-minimising equilibrium","MR greater than MC","Profit"],"answer":2,"explanation":"MR greater than MC: when marginal revenue exceeds marginal cost, producing an additional unit adds to profit so output should expand"},{"q":"Which concept best matches this situation? The next unit adds ₹12 revenue but costs ₹18.","options":["Normal-profit equilibrium logic","Profit-maximisation rule","Producer equilibrium","MC greater than MR"],"answer":3,"explanation":"MC greater than MR: when marginal cost exceeds marginal revenue, the extra unit reduces profit so output should contract"},{"q":"Which concept best matches this situation? The firm has no incentive to change output at MR = MC with rising MC.","options":["Normal-profit equilibrium logic","Loss-minimising equilibrium","Producer","First MR–MC condition"],"answer":0,"explanation":"Normal-profit equilibrium logic: producer equilibrium depends on marginal comparison and can occur even when economic profit is only normal"},{"q":"Which concept best matches this situation? The chosen output gives the smallest feasible loss under current conditions.","options":["Profit-maximisation rule","Loss-minimising equilibrium","Profit","Second MR–MC condition"],"answer":1,"explanation":"Loss-minimising equilibrium: in the short run a producer can be in equilibrium while incurring a loss if changing output would make the loss larger"},{"q":"Which concept best matches this situation? The firm compares MR and MC unit by unit rather than average values.","options":["Producer","Producer equilibrium","Profit-maximisation rule","MR greater than MC"],"answer":2,"explanation":"Profit-maximisation rule: output should be adjusted until the additional revenue from the last unit equals its additional cost with the stability condition satisfied"}]}},{"id":"cbse-11-micro-ch11","board":"CBSE","classLevel":11,"subject":"Economics","title":"Theory of Supply","chapter":"Reference Chapter 11","sourceLabel":"T.R. Jain & V.K. Ohri — Introductory Microeconomics, Class XI (2020-21 reference edition); filtered to the CBSE 2026–27 Introductory Microeconomics scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Supply\"?","options":["the quantity of a commodity a producer is willing and able to offer for sale at a given price during a given period","a table showing quantities supplied at different possible prices","other things remaining constant, quantity supplied generally varies directly with own price","a rightward shift of the supply curve caused by a favourable non-price determinant"],"answer":0,"explanation":"Supply: the quantity of a commodity a producer is willing and able to offer for sale at a given price during a given period"},{"q":"Which statement best explains \"Supply schedule\"?","options":["the total quantity supplied by all firms in the market at a given price","a table showing quantities supplied at different possible prices","an increase in quantity supplied caused solely by a rise in the commodity’s own price","a fall in input prices generally increases supply while a rise generally decreases supply"],"answer":1,"explanation":"Supply schedule: a table showing quantities supplied at different possible prices"},{"q":"Which statement best explains \"Market supply\"?","options":["other things remaining constant, quantity supplied generally varies directly with own price","a decrease in quantity supplied caused solely by a fall in own price","the total quantity supplied by all firms in the market at a given price","the responsiveness of quantity supplied to a change in own price"],"answer":2,"explanation":"Market supply: the total quantity supplied by all firms in the market at a given price"},{"q":"Which statement best explains \"Law of supply\"?","options":["an increase in quantity supplied caused solely by a rise in the commodity’s own price","a rightward shift of the supply curve caused by a favourable non-price determinant","elasticity of supply equals percentage change in quantity supplied divided by percentage change in price","other things remaining constant, quantity supplied generally varies directly with own price"],"answer":3,"explanation":"Law of supply: other things remaining constant, quantity supplied generally varies directly with own price"},{"q":"Which statement best explains \"Extension of supply\"?","options":["an increase in quantity supplied caused solely by a rise in the commodity’s own price","a decrease in quantity supplied caused solely by a fall in own price","a fall in input prices generally increases supply while a rise generally decreases supply","the quantity of a commodity a producer is willing and able to offer for sale at a given price during a given period"],"answer":0,"explanation":"Extension of supply: an increase in quantity supplied caused solely by a rise in the commodity’s own price"},{"q":"Which statement best explains \"Contraction of supply\"?","options":["a rightward shift of the supply curve caused by a favourable non-price determinant","a decrease in quantity supplied caused solely by a fall in own price","the responsiveness of quantity supplied to a change in own price","a table showing quantities supplied at different possible prices"],"answer":1,"explanation":"Contraction of supply: a decrease in quantity supplied caused solely by a fall in own price"},{"q":"Which statement best explains \"Increase in supply\"?","options":["a fall in input prices generally increases supply while a rise generally decreases supply","elasticity of supply equals percentage change in quantity supplied divided by percentage change in price","a rightward shift of the supply curve caused by a favourable non-price determinant","the total quantity supplied by all firms in the market at a given price"],"answer":2,"explanation":"Increase in supply: a rightward shift of the supply curve caused by a favourable non-price determinant"},{"q":"Which statement best explains \"Input-price effect on supply\"?","options":["the responsiveness of quantity supplied to a change in own price","the quantity of a commodity a producer is willing and able to offer for sale at a given price during a given period","other things remaining constant, quantity supplied generally varies directly with own price","a fall in input prices generally increases supply while a rise generally decreases supply"],"answer":3,"explanation":"Input-price effect on supply: a fall in input prices generally increases supply while a rise generally decreases supply"},{"q":"Which statement best explains \"Price elasticity of supply\"?","options":["the responsiveness of quantity supplied to a change in own price","elasticity of supply equals percentage change in quantity supplied divided by percentage change in price","a table showing quantities supplied at different possible prices","an increase in quantity supplied caused solely by a rise in the commodity’s own price"],"answer":0,"explanation":"Price elasticity of supply: the responsiveness of quantity supplied to a change in own price"},{"q":"Which statement best explains \"Percentage method of supply elasticity\"?","options":["the quantity of a commodity a producer is willing and able to offer for sale at a given price during a given period","elasticity of supply equals percentage change in quantity supplied divided by percentage change in price","the total quantity supplied by all firms in the market at a given price","a decrease in quantity supplied caused solely by a fall in own price"],"answer":1,"explanation":"Percentage method of supply elasticity: elasticity of supply equals percentage change in quantity supplied divided by percentage change in price"}],"Moderate":[{"q":"Which concept best matches this situation? At ₹50 a seller is willing to offer 100 units this week.","options":["Supply schedule","Supply","Law of supply","Increase in supply"],"answer":1,"explanation":"Supply: the quantity of a commodity a producer is willing and able to offer for sale at a given price during a given period"},{"q":"Which concept best matches this situation? The table lists price and corresponding quantity offered for sale.","options":["Market supply","Extension of supply","Supply schedule","Input-price effect on supply"],"answer":2,"explanation":"Supply schedule: a table showing quantities supplied at different possible prices"},{"q":"Which concept best matches this situation? Supplies of firms A, B and C are added at each price.","options":["Law of supply","Contraction of supply","Price elasticity of supply","Market supply"],"answer":3,"explanation":"Market supply: the total quantity supplied by all firms in the market at a given price"},{"q":"Which concept best matches this situation? A higher market price encourages a firm to offer more output.","options":["Law of supply","Extension of supply","Increase in supply","Percentage method of supply elasticity"],"answer":0,"explanation":"Law of supply: other things remaining constant, quantity supplied generally varies directly with own price"},{"q":"Which concept best matches this situation? The firm moves upward along the same supply curve.","options":["Contraction of supply","Extension of supply","Input-price effect on supply","Supply"],"answer":1,"explanation":"Extension of supply: an increase in quantity supplied caused solely by a rise in the commodity’s own price"},{"q":"Which concept best matches this situation? The firm moves downward along the same supply curve.","options":["Increase in supply","Price elasticity of supply","Contraction of supply","Supply schedule"],"answer":2,"explanation":"Contraction of supply: a decrease in quantity supplied caused solely by a fall in own price"},{"q":"Which concept best matches this situation? A cost-saving technology lets firms supply more at every price.","options":["Input-price effect on supply","Percentage method of supply elasticity","Market supply","Increase in supply"],"answer":3,"explanation":"Increase in supply: a rightward shift of the supply curve caused by a favourable non-price determinant"},{"q":"Which concept best matches this situation? Cheaper raw material lowers production cost and shifts supply right.","options":["Input-price effect on supply","Price elasticity of supply","Supply","Law of supply"],"answer":0,"explanation":"Input-price effect on supply: a fall in input prices generally increases supply while a rise generally decreases supply"},{"q":"Which concept best matches this situation? A 10% price rise causes quantity supplied to rise by 20%.","options":["Percentage method of supply elasticity","Price elasticity of supply","Supply schedule","Extension of supply"],"answer":1,"explanation":"Price elasticity of supply: the responsiveness of quantity supplied to a change in own price"},{"q":"Which concept best matches this situation? Quantity supplied rises 15% after price rises 5%, giving elasticity 3.","options":["Supply","Market supply","Percentage method of supply elasticity","Contraction of supply"],"answer":2,"explanation":"Percentage method of supply elasticity: elasticity of supply equals percentage change in quantity supplied divided by percentage change in price"}]}},{"id":"cbse-11-micro-ch12","board":"CBSE","classLevel":11,"subject":"Economics","title":"Forms of Market","chapter":"Reference Chapter 12","sourceLabel":"T.R. Jain & V.K. Ohri — Introductory Microeconomics, Class XI (2020-21 reference edition); filtered to the CBSE 2026–27 Introductory Microeconomics scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Perfect competition\"?","options":["a market form with a very large number of buyers and sellers, homogeneous product and free entry and exit so an individual firm is a price taker","products of different firms are identical from the buyer’s point of view","firms can enter or leave the market without major artificial barriers in the long run","a market form with many sellers offering differentiated but close-substitute products"],"answer":0,"explanation":"Perfect competition: a market form with a very large number of buyers and sellers, homogeneous product and free entry and exit so an individual firm is a price taker"},{"q":"Which statement best explains \"Homogeneous product\"?","options":["a firm that accepts the market price because its individual output is too small to influence that price","products of different firms are identical from the buyer’s point of view","buyers and sellers are assumed to have complete relevant information about market conditions","real or perceived differences that make one firm’s product distinct from competing products"],"answer":1,"explanation":"Homogeneous product: products of different firms are identical from the buyer’s point of view"},{"q":"Which statement best explains \"Price taker\"?","options":["firms can enter or leave the market without major artificial barriers in the long run","a market form with a single seller and no close substitute for the product","a firm that accepts the market price because its individual output is too small to influence that price","a market form dominated by a few large firms whose decisions are interdependent"],"answer":2,"explanation":"Price taker: a firm that accepts the market price because its individual output is too small to influence that price"},{"q":"Which statement best explains \"Free entry and exit\"?","options":["buyers and sellers are assumed to have complete relevant information about market conditions","a market form with many sellers offering differentiated but close-substitute products","each firm must consider likely reactions of rival firms when making strategic decisions","firms can enter or leave the market without major artificial barriers in the long run"],"answer":3,"explanation":"Free entry and exit: firms can enter or leave the market without major artificial barriers in the long run"},{"q":"Which statement best explains \"Perfect knowledge\"?","options":["buyers and sellers are assumed to have complete relevant information about market conditions","a market form with a single seller and no close substitute for the product","real or perceived differences that make one firm’s product distinct from competing products","a market form with a very large number of buyers and sellers, homogeneous product and free entry and exit so an individual firm is a price taker"],"answer":0,"explanation":"Perfect knowledge: buyers and sellers are assumed to have complete relevant information about market conditions"},{"q":"Which statement best explains \"Monopoly\"?","options":["a market form with many sellers offering differentiated but close-substitute products","a market form with a single seller and no close substitute for the product","a market form dominated by a few large firms whose decisions are interdependent","products of different firms are identical from the buyer’s point of view"],"answer":1,"explanation":"Monopoly: a market form with a single seller and no close substitute for the product"},{"q":"Which statement best explains \"Monopolistic competition\"?","options":["real or perceived differences that make one firm’s product distinct from competing products","each firm must consider likely reactions of rival firms when making strategic decisions","a market form with many sellers offering differentiated but close-substitute products","a firm that accepts the market price because its individual output is too small to influence that price"],"answer":2,"explanation":"Monopolistic competition: a market form with many sellers offering differentiated but close-substitute products"},{"q":"Which statement best explains \"Product differentiation\"?","options":["a market form dominated by a few large firms whose decisions are interdependent","a market form with a very large number of buyers and sellers, homogeneous product and free entry and exit so an individual firm is a price taker","firms can enter or leave the market without major artificial barriers in the long run","real or perceived differences that make one firm’s product distinct from competing products"],"answer":3,"explanation":"Product differentiation: real or perceived differences that make one firm’s product distinct from competing products"},{"q":"Which statement best explains \"Oligopoly\"?","options":["a market form dominated by a few large firms whose decisions are interdependent","each firm must consider likely reactions of rival firms when making strategic decisions","products of different firms are identical from the buyer’s point of view","buyers and sellers are assumed to have complete relevant information about market conditions"],"answer":0,"explanation":"Oligopoly: a market form dominated by a few large firms whose decisions are interdependent"},{"q":"Which statement best explains \"Interdependence in oligopoly\"?","options":["a market form with a very large number of buyers and sellers, homogeneous product and free entry and exit so an individual firm is a price taker","each firm must consider likely reactions of rival firms when making strategic decisions","a firm that accepts the market price because its individual output is too small to influence that price","a market form with a single seller and no close substitute for the product"],"answer":1,"explanation":"Interdependence in oligopoly: each firm must consider likely reactions of rival firms when making strategic decisions"}],"Moderate":[{"q":"Which concept best matches this situation? Each firm sells an identical product at the market-determined price.","options":["Homogeneous product","Perfect competition","Free entry and exit","Monopolistic competition"],"answer":1,"explanation":"Perfect competition: a market form with a very large number of buyers and sellers, homogeneous product and free entry and exit so an individual firm is a price taker"},{"q":"Which concept best matches this situation? Consumers see no meaningful difference between units supplied by different firms.","options":["Price taker","Perfect knowledge","Homogeneous product","Product differentiation"],"answer":2,"explanation":"Homogeneous product: products of different firms are identical from the buyer’s point of view"},{"q":"Which concept best matches this situation? The firm chooses quantity but not the market price.","options":["Free entry and exit","Monopoly","Oligopoly","Price taker"],"answer":3,"explanation":"Price taker: a firm that accepts the market price because its individual output is too small to influence that price"},{"q":"Which concept best matches this situation? New firms can join when opportunities attract them.","options":["Free entry and exit","Perfect knowledge","Monopolistic competition","Interdependence in oligopoly"],"answer":0,"explanation":"Free entry and exit: firms can enter or leave the market without major artificial barriers in the long run"},{"q":"Which concept best matches this situation? Participants know the prevailing market price.","options":["Monopoly","Perfect knowledge","Product differentiation","Perfect competition"],"answer":1,"explanation":"Perfect knowledge: buyers and sellers are assumed to have complete relevant information about market conditions"},{"q":"Which concept best matches this situation? One supplier controls the market for a unique service with strong entry barriers.","options":["Monopolistic competition","Oligopoly","Monopoly","Homogeneous product"],"answer":2,"explanation":"Monopoly: a market form with a single seller and no close substitute for the product"},{"q":"Which concept best matches this situation? Many brands compete through product differences and selling efforts.","options":["Product differentiation","Interdependence in oligopoly","Price taker","Monopolistic competition"],"answer":3,"explanation":"Monopolistic competition: a market form with many sellers offering differentiated but close-substitute products"},{"q":"Which concept best matches this situation? Brands differ in design, packaging, quality or service.","options":["Product differentiation","Oligopoly","Perfect competition","Free entry and exit"],"answer":0,"explanation":"Product differentiation: real or perceived differences that make one firm’s product distinct from competing products"},{"q":"Which concept best matches this situation? Each major producer watches rivals before changing price or output.","options":["Interdependence in oligopoly","Oligopoly","Homogeneous product","Perfect knowledge"],"answer":1,"explanation":"Oligopoly: a market form dominated by a few large firms whose decisions are interdependent"},{"q":"Which concept best matches this situation? A price cut by one large firm may trigger responses from the others.","options":["Perfect competition","Price taker","Interdependence in oligopoly","Monopoly"],"answer":2,"explanation":"Interdependence in oligopoly: each firm must consider likely reactions of rival firms when making strategic decisions"}]}},{"id":"cbse-11-micro-ch13","board":"CBSE","classLevel":11,"subject":"Economics","title":"Market Equilibrium under Perfect Competition","chapter":"Reference Chapter 13","sourceLabel":"T.R. Jain & V.K. Ohri — Introductory Microeconomics, Class XI (2020-21 reference edition); filtered to the CBSE 2026–27 Introductory Microeconomics scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Market equilibrium\"?","options":["the market state where quantity demanded equals quantity supplied at a particular price","the price at which market demand equals market supply","a situation where quantity supplied exceeds quantity demanded at the prevailing price","with demand unchanged, a rightward supply shift lowers equilibrium price and raises equilibrium quantity"],"answer":0,"explanation":"Market equilibrium: the market state where quantity demanded equals quantity supplied at a particular price"},{"q":"Which statement best explains \"Equilibrium price\"?","options":["a situation where quantity demanded exceeds quantity supplied at the prevailing price","the price at which market demand equals market supply","with supply unchanged, a rightward demand shift raises both equilibrium price and equilibrium quantity","with demand unchanged, a leftward supply shift raises equilibrium price and lowers equilibrium quantity"],"answer":1,"explanation":"Equilibrium price: the price at which market demand equals market supply"},{"q":"Which statement best explains \"Excess demand\"?","options":["a situation where quantity supplied exceeds quantity demanded at the prevailing price","with supply unchanged, a leftward demand shift lowers both equilibrium price and equilibrium quantity","a situation where quantity demanded exceeds quantity supplied at the prevailing price","a legal maximum price set below equilibrium that can create excess demand or shortage"],"answer":2,"explanation":"Excess demand: a situation where quantity demanded exceeds quantity supplied at the prevailing price"},{"q":"Which statement best explains \"Excess supply\"?","options":["with supply unchanged, a rightward demand shift raises both equilibrium price and equilibrium quantity","with demand unchanged, a rightward supply shift lowers equilibrium price and raises equilibrium quantity","a legal minimum price set above equilibrium that can create excess supply","a situation where quantity supplied exceeds quantity demanded at the prevailing price"],"answer":3,"explanation":"Excess supply: a situation where quantity supplied exceeds quantity demanded at the prevailing price"},{"q":"Which statement best explains \"Increase in demand effect\"?","options":["with supply unchanged, a rightward demand shift raises both equilibrium price and equilibrium quantity","with supply unchanged, a leftward demand shift lowers both equilibrium price and equilibrium quantity","with demand unchanged, a leftward supply shift raises equilibrium price and lowers equilibrium quantity","the market state where quantity demanded equals quantity supplied at a particular price"],"answer":0,"explanation":"Increase in demand effect: with supply unchanged, a rightward demand shift raises both equilibrium price and equilibrium quantity"},{"q":"Which statement best explains \"Decrease in demand effect\"?","options":["with demand unchanged, a rightward supply shift lowers equilibrium price and raises equilibrium quantity","with supply unchanged, a leftward demand shift lowers both equilibrium price and equilibrium quantity","a legal maximum price set below equilibrium that can create excess demand or shortage","the price at which market demand equals market supply"],"answer":1,"explanation":"Decrease in demand effect: with supply unchanged, a leftward demand shift lowers both equilibrium price and equilibrium quantity"},{"q":"Which statement best explains \"Increase in supply effect\"?","options":["with demand unchanged, a leftward supply shift raises equilibrium price and lowers equilibrium quantity","a legal minimum price set above equilibrium that can create excess supply","with demand unchanged, a rightward supply shift lowers equilibrium price and raises equilibrium quantity","a situation where quantity demanded exceeds quantity supplied at the prevailing price"],"answer":2,"explanation":"Increase in supply effect: with demand unchanged, a rightward supply shift lowers equilibrium price and raises equilibrium quantity"},{"q":"Which statement best explains \"Decrease in supply effect\"?","options":["a legal maximum price set below equilibrium that can create excess demand or shortage","the market state where quantity demanded equals quantity supplied at a particular price","a situation where quantity supplied exceeds quantity demanded at the prevailing price","with demand unchanged, a leftward supply shift raises equilibrium price and lowers equilibrium quantity"],"answer":3,"explanation":"Decrease in supply effect: with demand unchanged, a leftward supply shift raises equilibrium price and lowers equilibrium quantity"},{"q":"Which statement best explains \"Price ceiling\"?","options":["a legal maximum price set below equilibrium that can create excess demand or shortage","a legal minimum price set above equilibrium that can create excess supply","the price at which market demand equals market supply","with supply unchanged, a rightward demand shift raises both equilibrium price and equilibrium quantity"],"answer":0,"explanation":"Price ceiling: a legal maximum price set below equilibrium that can create excess demand or shortage"},{"q":"Which statement best explains \"Price floor\"?","options":["the market state where quantity demanded equals quantity supplied at a particular price","a legal minimum price set above equilibrium that can create excess supply","a situation where quantity demanded exceeds quantity supplied at the prevailing price","with supply unchanged, a leftward demand shift lowers both equilibrium price and equilibrium quantity"],"answer":1,"explanation":"Price floor: a legal minimum price set above equilibrium that can create excess supply"}],"Moderate":[{"q":"Which concept best matches this situation? At ₹50 both buyers and sellers plan 1,000 units.","options":["Equilibrium price","Market equilibrium","Excess supply","Increase in supply effect"],"answer":1,"explanation":"Market equilibrium: the market state where quantity demanded equals quantity supplied at a particular price"},{"q":"Which concept best matches this situation? At this price there is neither excess demand nor excess supply.","options":["Excess demand","Increase in demand effect","Equilibrium price","Decrease in supply effect"],"answer":2,"explanation":"Equilibrium price: the price at which market demand equals market supply"},{"q":"Which concept best matches this situation? Consumers want 120 units but firms offer only 90.","options":["Excess supply","Decrease in demand effect","Price ceiling","Excess demand"],"answer":3,"explanation":"Excess demand: a situation where quantity demanded exceeds quantity supplied at the prevailing price"},{"q":"Which concept best matches this situation? Firms offer 150 units while consumers want 100.","options":["Excess supply","Increase in demand effect","Increase in supply effect","Price floor"],"answer":0,"explanation":"Excess supply: a situation where quantity supplied exceeds quantity demanded at the prevailing price"},{"q":"Which concept best matches this situation? Consumer preference strengthens while supply stays fixed.","options":["Decrease in demand effect","Increase in demand effect","Decrease in supply effect","Market equilibrium"],"answer":1,"explanation":"Increase in demand effect: with supply unchanged, a rightward demand shift raises both equilibrium price and equilibrium quantity"},{"q":"Which concept best matches this situation? Consumer preference weakens while supply stays fixed.","options":["Increase in supply effect","Price ceiling","Decrease in demand effect","Equilibrium price"],"answer":2,"explanation":"Decrease in demand effect: with supply unchanged, a leftward demand shift lowers both equilibrium price and equilibrium quantity"},{"q":"Which concept best matches this situation? Technology reduces production cost.","options":["Decrease in supply effect","Price floor","Excess demand","Increase in supply effect"],"answer":3,"explanation":"Increase in supply effect: with demand unchanged, a rightward supply shift lowers equilibrium price and raises equilibrium quantity"},{"q":"Which concept best matches this situation? Input costs rise sharply.","options":["Decrease in supply effect","Price ceiling","Market equilibrium","Excess supply"],"answer":0,"explanation":"Decrease in supply effect: with demand unchanged, a leftward supply shift raises equilibrium price and lowers equilibrium quantity"},{"q":"Which concept best matches this situation? Government fixes a maximum price below the market-clearing price.","options":["Price floor","Price ceiling","Equilibrium price","Increase in demand effect"],"answer":1,"explanation":"Price ceiling: a legal maximum price set below equilibrium that can create excess demand or shortage"},{"q":"Which concept best matches this situation? A minimum support price above the market-clearing price leads sellers to offer more than buyers demand.","options":["Market equilibrium","Excess demand","Price floor","Decrease in demand effect"],"answer":2,"explanation":"Price floor: a legal minimum price set above equilibrium that can create excess supply"}]}},{"id":"cbse-12-macro-national-income","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Macroeconomics","title":"National Income and Related Aggregates","chapter":"Macroeconomics Unit 1","sourceLabel":"Smit Sir Commerce — Class 12 Economics Quick Revision Pack (National Income, Money & Banking, Income Determination, Government Budget, Balance of Payments) + CBSE 2026–27 Economics syllabus","sourceStatus":"Smit Sir revision + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Final goods\"?","options":["goods and services purchased for final use and not for resale or further production in the accounting period","goods and services used as inputs for producing other goods or for resale during the accounting period","the fall in value of fixed capital due to normal wear and tear, expected obsolescence or accidental damage within the accounting treatment","a national-income method that adds factor incomes generated in production such as compensation, rent, interest and profit as applicable"],"answer":0,"explanation":"Final goods: goods and services purchased for final use and not for resale or further production in the accounting period"},{"q":"Which statement best explains \"Intermediate goods\"?","options":["a stock is measured at a point of time while a flow is measured over a period of time","goods and services used as inputs for producing other goods or for resale during the accounting period","the continuous movement of production, income and expenditure between producing units and households in the simplified economy","a national-income method that totals final expenditure on domestically produced final goods and services using the prescribed components"],"answer":1,"explanation":"Intermediate goods: goods and services used as inputs for producing other goods or for resale during the accounting period"},{"q":"Which statement best explains \"Stock and flow distinction\"?","options":["the fall in value of fixed capital due to normal wear and tear, expected obsolescence or accidental damage within the accounting treatment","a national-income method that adds value added by producing units and avoids double counting of intermediate goods","a stock is measured at a point of time while a flow is measured over a period of time","national aggregates are obtained from corresponding domestic aggregates by adding net factor income from abroad"],"answer":2,"explanation":"Stock and flow distinction: a stock is measured at a point of time while a flow is measured over a period of time"},{"q":"Which statement best explains \"Depreciation\"?","options":["the continuous movement of production, income and expenditure between producing units and households in the simplified economy","a national-income method that adds factor incomes generated in production such as compensation, rent, interest and profit as applicable","gross-to-net conversion subtracts depreciation, market-price-to-factor-cost conversion adjusts net indirect taxes where prescribed, and real GDP removes price-change effects from nominal GDP","the fall in value of fixed capital due to normal wear and tear, expected obsolescence or accidental damage within the accounting treatment"],"answer":3,"explanation":"Depreciation: the fall in value of fixed capital due to normal wear and tear, expected obsolescence or accidental damage within the accounting treatment"},{"q":"Which statement best explains \"Circular flow of income\"?","options":["the continuous movement of production, income and expenditure between producing units and households in the simplified economy","a national-income method that adds value added by producing units and avoids double counting of intermediate goods","a national-income method that totals final expenditure on domestically produced final goods and services using the prescribed components","goods and services purchased for final use and not for resale or further production in the accounting period"],"answer":0,"explanation":"Circular flow of income: the continuous movement of production, income and expenditure between producing units and households in the simplified economy"},{"q":"Which statement best explains \"Value added method\"?","options":["a national-income method that adds factor incomes generated in production such as compensation, rent, interest and profit as applicable","a national-income method that adds value added by producing units and avoids double counting of intermediate goods","national aggregates are obtained from corresponding domestic aggregates by adding net factor income from abroad","goods and services used as inputs for producing other goods or for resale during the accounting period"],"answer":1,"explanation":"Value added method: a national-income method that adds value added by producing units and avoids double counting of intermediate goods"},{"q":"Which statement best explains \"Income method\"?","options":["a national-income method that totals final expenditure on domestically produced final goods and services using the prescribed components","gross-to-net conversion subtracts depreciation, market-price-to-factor-cost conversion adjusts net indirect taxes where prescribed, and real GDP removes price-change effects from nominal GDP","a national-income method that adds factor incomes generated in production such as compensation, rent, interest and profit as applicable","a stock is measured at a point of time while a flow is measured over a period of time"],"answer":2,"explanation":"Income method: a national-income method that adds factor incomes generated in production such as compensation, rent, interest and profit as applicable"},{"q":"Which statement best explains \"Expenditure method\"?","options":["national aggregates are obtained from corresponding domestic aggregates by adding net factor income from abroad","goods and services purchased for final use and not for resale or further production in the accounting period","the fall in value of fixed capital due to normal wear and tear, expected obsolescence or accidental damage within the accounting treatment","a national-income method that totals final expenditure on domestically produced final goods and services using the prescribed components"],"answer":3,"explanation":"Expenditure method: a national-income method that totals final expenditure on domestically produced final goods and services using the prescribed components"},{"q":"Which statement best explains \"Domestic–national conversion\"?","options":["national aggregates are obtained from corresponding domestic aggregates by adding net factor income from abroad","gross-to-net conversion subtracts depreciation, market-price-to-factor-cost conversion adjusts net indirect taxes where prescribed, and real GDP removes price-change effects from nominal GDP","goods and services used as inputs for producing other goods or for resale during the accounting period","the continuous movement of production, income and expenditure between producing units and households in the simplified economy"],"answer":0,"explanation":"Domestic–national conversion: national aggregates are obtained from corresponding domestic aggregates by adding net factor income from abroad"},{"q":"Which statement best explains \"Gross, net, market-price and real-value checks\"?","options":["goods and services purchased for final use and not for resale or further production in the accounting period","gross-to-net conversion subtracts depreciation, market-price-to-factor-cost conversion adjusts net indirect taxes where prescribed, and real GDP removes price-change effects from nominal GDP","a stock is measured at a point of time while a flow is measured over a period of time","a national-income method that adds value added by producing units and avoids double counting of intermediate goods"],"answer":1,"explanation":"Gross, net, market-price and real-value checks: gross-to-net conversion subtracts depreciation, market-price-to-factor-cost conversion adjusts net indirect taxes where prescribed, and real GDP removes price-change effects from nominal GDP"}],"Moderate":[{"q":"Which concept best matches this situation? A household buys a refrigerator for use at home.","options":["Intermediate goods","Final goods","Depreciation","Income method"],"answer":1,"explanation":"Final goods: goods and services purchased for final use and not for resale or further production in the accounting period"},{"q":"Which concept best matches this situation? A bakery purchases flour to make bread for sale.","options":["Stock and flow distinction","Circular flow of income","Intermediate goods","Expenditure method"],"answer":2,"explanation":"Intermediate goods: goods and services used as inputs for producing other goods or for resale during the accounting period"},{"q":"Which concept best matches this situation? Wealth on 31 March is a stock, while income earned during the year is a flow.","options":["Depreciation","Value added method","Domestic–national conversion","Stock and flow distinction"],"answer":3,"explanation":"Stock and flow distinction: a stock is measured at a point of time while a flow is measured over a period of time"},{"q":"Which concept best matches this situation? A machine loses part of its productive value during the year.","options":["Depreciation","Circular flow of income","Income method","Gross, net, market-price and real-value checks"],"answer":0,"explanation":"Depreciation: the fall in value of fixed capital due to normal wear and tear, expected obsolescence or accidental damage within the accounting treatment"},{"q":"Which concept best matches this situation? Households supply factor services and receive income which is spent on goods and services.","options":["Value added method","Circular flow of income","Expenditure method","Final goods"],"answer":1,"explanation":"Circular flow of income: the continuous movement of production, income and expenditure between producing units and households in the simplified economy"},{"q":"Which concept best matches this situation? Output value minus intermediate consumption is calculated for each producer.","options":["Income method","Domestic–national conversion","Value added method","Intermediate goods"],"answer":2,"explanation":"Value added method: a national-income method that adds value added by producing units and avoids double counting of intermediate goods"},{"q":"Which concept best matches this situation? Factor payments generated by production are summed.","options":["Expenditure method","Gross, net, market-price and real-value checks","Stock and flow distinction","Income method"],"answer":3,"explanation":"Income method: a national-income method that adds factor incomes generated in production such as compensation, rent, interest and profit as applicable"},{"q":"Which concept best matches this situation? Final consumption, investment and relevant government/net-export components are combined.","options":["Expenditure method","Domestic–national conversion","Final goods","Depreciation"],"answer":0,"explanation":"Expenditure method: a national-income method that totals final expenditure on domestically produced final goods and services using the prescribed components"},{"q":"Which concept best matches this situation? GNPMP = GDPMP + NFIA.","options":["Gross, net, market-price and real-value checks","Domestic–national conversion","Intermediate goods","Circular flow of income"],"answer":1,"explanation":"Domestic–national conversion: national aggregates are obtained from corresponding domestic aggregates by adding net factor income from abroad"},{"q":"Which concept best matches this situation? NDPMP = GDPMP − depreciation, while real-versus-nominal comparison separates output change from price change.","options":["Final goods","Stock and flow distinction","Gross, net, market-price and real-value checks","Value added method"],"answer":2,"explanation":"Gross, net, market-price and real-value checks: gross-to-net conversion subtracts depreciation, market-price-to-factor-cost conversion adjusts net indirect taxes where prescribed, and real GDP removes price-change effects from nominal GDP"}]}},{"id":"cbse-12-macro-money-banking","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Macroeconomics","title":"Money and Banking","chapter":"Macroeconomics Unit 2","sourceLabel":"Smit Sir Commerce — Class 12 Economics Quick Revision Pack (National Income, Money & Banking, Income Determination, Government Budget, Balance of Payments) + CBSE 2026–27 Economics syllabus","sourceStatus":"Smit Sir revision + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Money\"?","options":["a generally accepted medium used to facilitate exchange and express value in monetary transactions","currency held by the public plus net demand deposits held with commercial banks under the prescribed measure","the banking system can expand deposits and credit through lending subject to reserve requirements and actual lending/deposit behaviour","the central bank maintains government banking relations and performs banking functions for the government"],"answer":0,"explanation":"Money: a generally accepted medium used to facilitate exchange and express value in monetary transactions"},{"q":"Which statement best explains \"Money supply in the CBSE scope\"?","options":["bank deposits withdrawable on demand and usable for making payments subject to banking arrangements","currency held by the public plus net demand deposits held with commercial banks under the prescribed measure","a higher required reserve ratio generally reduces deposit-expansion potential while a lower ratio generally increases it","the central bank holds banking-system reserves and can support banks facing liquidity needs within the policy framework"],"answer":1,"explanation":"Money supply in the CBSE scope: currency held by the public plus net demand deposits held with commercial banks under the prescribed measure"},{"q":"Which statement best explains \"Demand deposits\"?","options":["the banking system can expand deposits and credit through lending subject to reserve requirements and actual lending/deposit behaviour","the central bank performs the institutional function of issuing currency as provided by the monetary system","bank deposits withdrawable on demand and usable for making payments subject to banking arrangements","general monetary tools such as policy rates, reserve ratios and open-market operations influence overall liquidity and credit conditions"],"answer":2,"explanation":"Demand deposits: bank deposits withdrawable on demand and usable for making payments subject to banking arrangements"},{"q":"Which statement best explains \"Commercial-bank credit creation\"?","options":["a higher required reserve ratio generally reduces deposit-expansion potential while a lower ratio generally increases it","the central bank maintains government banking relations and performs banking functions for the government","the prescribed difference between the value of pledged security and the loan granted against it, used as a selective credit-control tool","the banking system can expand deposits and credit through lending subject to reserve requirements and actual lending/deposit behaviour"],"answer":3,"explanation":"Commercial-bank credit creation: the banking system can expand deposits and credit through lending subject to reserve requirements and actual lending/deposit behaviour"},{"q":"Which statement best explains \"Reserve requirement effect\"?","options":["a higher required reserve ratio generally reduces deposit-expansion potential while a lower ratio generally increases it","the central bank performs the institutional function of issuing currency as provided by the monetary system","the central bank holds banking-system reserves and can support banks facing liquidity needs within the policy framework","a generally accepted medium used to facilitate exchange and express value in monetary transactions"],"answer":0,"explanation":"Reserve requirement effect: a higher required reserve ratio generally reduces deposit-expansion potential while a lower ratio generally increases it"},{"q":"Which statement best explains \"Bank of issue\"?","options":["the central bank maintains government banking relations and performs banking functions for the government","the central bank performs the institutional function of issuing currency as provided by the monetary system","general monetary tools such as policy rates, reserve ratios and open-market operations influence overall liquidity and credit conditions","currency held by the public plus net demand deposits held with commercial banks under the prescribed measure"],"answer":1,"explanation":"Bank of issue: the central bank performs the institutional function of issuing currency as provided by the monetary system"},{"q":"Which statement best explains \"Banker to government\"?","options":["the central bank holds banking-system reserves and can support banks facing liquidity needs within the policy framework","the prescribed difference between the value of pledged security and the loan granted against it, used as a selective credit-control tool","the central bank maintains government banking relations and performs banking functions for the government","bank deposits withdrawable on demand and usable for making payments subject to banking arrangements"],"answer":2,"explanation":"Banker to government: the central bank maintains government banking relations and performs banking functions for the government"},{"q":"Which statement best explains \"Banker’s bank and lender-of-last-resort role\"?","options":["general monetary tools such as policy rates, reserve ratios and open-market operations influence overall liquidity and credit conditions","a generally accepted medium used to facilitate exchange and express value in monetary transactions","the banking system can expand deposits and credit through lending subject to reserve requirements and actual lending/deposit behaviour","the central bank holds banking-system reserves and can support banks facing liquidity needs within the policy framework"],"answer":3,"explanation":"Banker’s bank and lender-of-last-resort role: the central bank holds banking-system reserves and can support banks facing liquidity needs within the policy framework"},{"q":"Which statement best explains \"Quantitative credit control\"?","options":["general monetary tools such as policy rates, reserve ratios and open-market operations influence overall liquidity and credit conditions","the prescribed difference between the value of pledged security and the loan granted against it, used as a selective credit-control tool","currency held by the public plus net demand deposits held with commercial banks under the prescribed measure","a higher required reserve ratio generally reduces deposit-expansion potential while a lower ratio generally increases it"],"answer":0,"explanation":"Quantitative credit control: general monetary tools such as policy rates, reserve ratios and open-market operations influence overall liquidity and credit conditions"},{"q":"Which statement best explains \"Margin requirement\"?","options":["a generally accepted medium used to facilitate exchange and express value in monetary transactions","the prescribed difference between the value of pledged security and the loan granted against it, used as a selective credit-control tool","bank deposits withdrawable on demand and usable for making payments subject to banking arrangements","the central bank performs the institutional function of issuing currency as provided by the monetary system"],"answer":1,"explanation":"Margin requirement: the prescribed difference between the value of pledged security and the loan granted against it, used as a selective credit-control tool"}],"Moderate":[{"q":"Which concept best matches this situation? Currency is accepted in payment instead of requiring barter.","options":["Money supply in the CBSE scope","Money","Commercial-bank credit creation","Banker to government"],"answer":1,"explanation":"Money: a generally accepted medium used to facilitate exchange and express value in monetary transactions"},{"q":"Which concept best matches this situation? Public currency and eligible demand deposits are combined for the syllabus measure.","options":["Demand deposits","Reserve requirement effect","Money supply in the CBSE scope","Banker’s bank and lender-of-last-resort role"],"answer":2,"explanation":"Money supply in the CBSE scope: currency held by the public plus net demand deposits held with commercial banks under the prescribed measure"},{"q":"Which concept best matches this situation? A depositor uses a cheque or transfer from a current account.","options":["Commercial-bank credit creation","Bank of issue","Quantitative credit control","Demand deposits"],"answer":3,"explanation":"Demand deposits: bank deposits withdrawable on demand and usable for making payments subject to banking arrangements"},{"q":"Which concept best matches this situation? A loan credited to an account can become a deposit that supports further banking transactions.","options":["Commercial-bank credit creation","Reserve requirement effect","Banker to government","Margin requirement"],"answer":0,"explanation":"Commercial-bank credit creation: the banking system can expand deposits and credit through lending subject to reserve requirements and actual lending/deposit behaviour"},{"q":"Which concept best matches this situation? Banks must keep a larger share of deposits as reserves, leaving less capacity to extend credit.","options":["Bank of issue","Reserve requirement effect","Banker’s bank and lender-of-last-resort role","Money"],"answer":1,"explanation":"Reserve requirement effect: a higher required reserve ratio generally reduces deposit-expansion potential while a lower ratio generally increases it"},{"q":"Which concept best matches this situation? The RBI performs the central currency-issue role in India subject to the legal framework.","options":["Banker to government","Quantitative credit control","Bank of issue","Money supply in the CBSE scope"],"answer":2,"explanation":"Bank of issue: the central bank performs the institutional function of issuing currency as provided by the monetary system"},{"q":"Which concept best matches this situation? Government banking transactions are handled through the central-bank framework.","options":["Banker’s bank and lender-of-last-resort role","Margin requirement","Demand deposits","Banker to government"],"answer":3,"explanation":"Banker to government: the central bank maintains government banking relations and performs banking functions for the government"},{"q":"Which concept best matches this situation? Commercial banks maintain reserves with the RBI and rely on the central-bank system for liquidity support.","options":["Banker’s bank and lender-of-last-resort role","Quantitative credit control","Money","Commercial-bank credit creation"],"answer":0,"explanation":"Banker’s bank and lender-of-last-resort role: the central bank holds banking-system reserves and can support banks facing liquidity needs within the policy framework"},{"q":"Which concept best matches this situation? Selling government securities can withdraw liquidity from the market.","options":["Margin requirement","Quantitative credit control","Money supply in the CBSE scope","Reserve requirement effect"],"answer":1,"explanation":"Quantitative credit control: general monetary tools such as policy rates, reserve ratios and open-market operations influence overall liquidity and credit conditions"},{"q":"Which concept best matches this situation? A higher margin allows a smaller loan against the same security value.","options":["Money","Demand deposits","Margin requirement","Bank of issue"],"answer":2,"explanation":"Margin requirement: the prescribed difference between the value of pledged security and the loan granted against it, used as a selective credit-control tool"}]}},{"id":"cbse-12-macro-income-employment","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Macroeconomics","title":"Determination of Income and Employment","chapter":"Macroeconomics Unit 3","sourceLabel":"Smit Sir Commerce — Class 12 Economics Quick Revision Pack (National Income, Money & Banking, Income Determination, Government Budget, Balance of Payments) + CBSE 2026–27 Economics syllabus","sourceStatus":"Smit Sir revision + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Aggregate demand\"?","options":["planned aggregate expenditure on final goods and services in the simplified macro model, built from the relevant expenditure components","a relationship showing planned consumption at different income levels, commonly written C = a + bY in the simple linear case","MPC is change in consumption divided by change in income, while MPS is change in saving divided by change in income","the ratio of change in equilibrium income to the initial change in autonomous investment, equal to 1/(1−MPC) or 1/MPS in the simple model"],"answer":0,"explanation":"Aggregate demand: planned aggregate expenditure on final goods and services in the simplified macro model, built from the relevant expenditure components"},{"q":"Which statement best explains \"Consumption function\"?","options":["APC is consumption divided by income and APS is saving divided by income","a relationship showing planned consumption at different income levels, commonly written C = a + bY in the simple linear case","in the simple consumption-saving relationship MPC plus MPS equals one","full employment allows all willing workers at the prevailing conditions to find work apart from normal frictions, while involuntary unemployment exists when willing workers cannot find jobs"],"answer":1,"explanation":"Consumption function: a relationship showing planned consumption at different income levels, commonly written C = a + bY in the simple linear case"},{"q":"Which statement best explains \"Average propensities\"?","options":["MPC is change in consumption divided by change in income, while MPS is change in saving divided by change in income","equilibrium occurs where planned aggregate demand equals aggregate output or income in the simple model","APC is consumption divided by income and APS is saving divided by income","planned aggregate demand exceeds the full-employment level of output, creating inflationary pressure that may be corrected by contractionary fiscal or monetary measures"],"answer":2,"explanation":"Average propensities: APC is consumption divided by income and APS is saving divided by income"},{"q":"Which statement best explains \"Marginal propensities\"?","options":["in the simple consumption-saving relationship MPC plus MPS equals one","the ratio of change in equilibrium income to the initial change in autonomous investment, equal to 1/(1−MPC) or 1/MPS in the simple model","planned aggregate demand is insufficient to purchase the full-employment output, creating recessionary or unemployment pressure that may be corrected by expansionary measures","MPC is change in consumption divided by change in income, while MPS is change in saving divided by change in income"],"answer":3,"explanation":"Marginal propensities: MPC is change in consumption divided by change in income, while MPS is change in saving divided by change in income"},{"q":"Which statement best explains \"MPC–MPS identity\"?","options":["in the simple consumption-saving relationship MPC plus MPS equals one","equilibrium occurs where planned aggregate demand equals aggregate output or income in the simple model","full employment allows all willing workers at the prevailing conditions to find work apart from normal frictions, while involuntary unemployment exists when willing workers cannot find jobs","planned aggregate expenditure on final goods and services in the simplified macro model, built from the relevant expenditure components"],"answer":0,"explanation":"MPC–MPS identity: in the simple consumption-saving relationship MPC plus MPS equals one"},{"q":"Which statement best explains \"Short-run equilibrium output\"?","options":["the ratio of change in equilibrium income to the initial change in autonomous investment, equal to 1/(1−MPC) or 1/MPS in the simple model","equilibrium occurs where planned aggregate demand equals aggregate output or income in the simple model","planned aggregate demand exceeds the full-employment level of output, creating inflationary pressure that may be corrected by contractionary fiscal or monetary measures","a relationship showing planned consumption at different income levels, commonly written C = a + bY in the simple linear case"],"answer":1,"explanation":"Short-run equilibrium output: equilibrium occurs where planned aggregate demand equals aggregate output or income in the simple model"},{"q":"Which statement best explains \"Investment multiplier\"?","options":["full employment allows all willing workers at the prevailing conditions to find work apart from normal frictions, while involuntary unemployment exists when willing workers cannot find jobs","planned aggregate demand is insufficient to purchase the full-employment output, creating recessionary or unemployment pressure that may be corrected by expansionary measures","the ratio of change in equilibrium income to the initial change in autonomous investment, equal to 1/(1−MPC) or 1/MPS in the simple model","APC is consumption divided by income and APS is saving divided by income"],"answer":2,"explanation":"Investment multiplier: the ratio of change in equilibrium income to the initial change in autonomous investment, equal to 1/(1−MPC) or 1/MPS in the simple model"},{"q":"Which statement best explains \"Full employment and involuntary unemployment\"?","options":["planned aggregate demand exceeds the full-employment level of output, creating inflationary pressure that may be corrected by contractionary fiscal or monetary measures","planned aggregate expenditure on final goods and services in the simplified macro model, built from the relevant expenditure components","MPC is change in consumption divided by change in income, while MPS is change in saving divided by change in income","full employment allows all willing workers at the prevailing conditions to find work apart from normal frictions, while involuntary unemployment exists when willing workers cannot find jobs"],"answer":3,"explanation":"Full employment and involuntary unemployment: full employment allows all willing workers at the prevailing conditions to find work apart from normal frictions, while involuntary unemployment exists when willing workers cannot find jobs"},{"q":"Which statement best explains \"Excess demand\"?","options":["planned aggregate demand exceeds the full-employment level of output, creating inflationary pressure that may be corrected by contractionary fiscal or monetary measures","planned aggregate demand is insufficient to purchase the full-employment output, creating recessionary or unemployment pressure that may be corrected by expansionary measures","a relationship showing planned consumption at different income levels, commonly written C = a + bY in the simple linear case","in the simple consumption-saving relationship MPC plus MPS equals one"],"answer":0,"explanation":"Excess demand: planned aggregate demand exceeds the full-employment level of output, creating inflationary pressure that may be corrected by contractionary fiscal or monetary measures"},{"q":"Which statement best explains \"Deficient demand\"?","options":["planned aggregate expenditure on final goods and services in the simplified macro model, built from the relevant expenditure components","planned aggregate demand is insufficient to purchase the full-employment output, creating recessionary or unemployment pressure that may be corrected by expansionary measures","APC is consumption divided by income and APS is saving divided by income","equilibrium occurs where planned aggregate demand equals aggregate output or income in the simple model"],"answer":1,"explanation":"Deficient demand: planned aggregate demand is insufficient to purchase the full-employment output, creating recessionary or unemployment pressure that may be corrected by expansionary measures"}],"Moderate":[{"q":"Which concept best matches this situation? Consumption and investment together form the core two-sector aggregate demand.","options":["Consumption function","Aggregate demand","Marginal propensities","Investment multiplier"],"answer":1,"explanation":"Aggregate demand: planned aggregate expenditure on final goods and services in the simplified macro model, built from the relevant expenditure components"},{"q":"Which concept best matches this situation? Positive autonomous consumption allows some consumption even at zero current income.","options":["Average propensities","MPC–MPS identity","Consumption function","Full employment and involuntary unemployment"],"answer":2,"explanation":"Consumption function: a relationship showing planned consumption at different income levels, commonly written C = a + bY in the simple linear case"},{"q":"Which concept best matches this situation? At income 100, consumption 80 gives APC 0.8 and saving 20 gives APS 0.2.","options":["Marginal propensities","Short-run equilibrium output","Excess demand","Average propensities"],"answer":3,"explanation":"Average propensities: APC is consumption divided by income and APS is saving divided by income"},{"q":"Which concept best matches this situation? Income rises 100 and consumption rises 80, so MPC is 0.8 and MPS is 0.2.","options":["Marginal propensities","MPC–MPS identity","Investment multiplier","Deficient demand"],"answer":0,"explanation":"Marginal propensities: MPC is change in consumption divided by change in income, while MPS is change in saving divided by change in income"},{"q":"Which concept best matches this situation? If MPC is 0.75, MPS is 0.25.","options":["Short-run equilibrium output","MPC–MPS identity","Full employment and involuntary unemployment","Aggregate demand"],"answer":1,"explanation":"MPC–MPS identity: in the simple consumption-saving relationship MPC plus MPS equals one"},{"q":"Which concept best matches this situation? Firms have no reason to change output when planned expenditure matches output.","options":["Investment multiplier","Excess demand","Short-run equilibrium output","Consumption function"],"answer":2,"explanation":"Short-run equilibrium output: equilibrium occurs where planned aggregate demand equals aggregate output or income in the simple model"},{"q":"Which concept best matches this situation? MPC 0.8 gives a multiplier of 5.","options":["Full employment and involuntary unemployment","Deficient demand","Average propensities","Investment multiplier"],"answer":3,"explanation":"Investment multiplier: the ratio of change in equilibrium income to the initial change in autonomous investment, equal to 1/(1−MPC) or 1/MPS in the simple model"},{"q":"Which concept best matches this situation? People ready to work at the prevailing wage remain without jobs because aggregate demand is insufficient.","options":["Full employment and involuntary unemployment","Excess demand","Aggregate demand","Marginal propensities"],"answer":0,"explanation":"Full employment and involuntary unemployment: full employment allows all willing workers at the prevailing conditions to find work apart from normal frictions, while involuntary unemployment exists when willing workers cannot find jobs"},{"q":"Which concept best matches this situation? Government may reduce spending or raise taxes when demand is excessive.","options":["Deficient demand","Excess demand","Consumption function","MPC–MPS identity"],"answer":1,"explanation":"Excess demand: planned aggregate demand exceeds the full-employment level of output, creating inflationary pressure that may be corrected by contractionary fiscal or monetary measures"},{"q":"Which concept best matches this situation? Government may increase spending or reduce taxes to support aggregate demand.","options":["Aggregate demand","Average propensities","Deficient demand","Short-run equilibrium output"],"answer":2,"explanation":"Deficient demand: planned aggregate demand is insufficient to purchase the full-employment output, creating recessionary or unemployment pressure that may be corrected by expansionary measures"}]}},{"id":"cbse-12-macro-government-budget","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Macroeconomics","title":"Government Budget and the Economy","chapter":"Macroeconomics Unit 4","sourceLabel":"Smit Sir Commerce — Class 12 Economics Quick Revision Pack (National Income, Money & Banking, Income Determination, Government Budget, Balance of Payments) + CBSE 2026–27 Economics syllabus","sourceStatus":"Smit Sir revision + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Government budget\"?","options":["an annual statement of estimated government receipts and expenditure for the financial year","budget policy can influence allocation of resources toward socially desirable goods, public services or priority sectors","budget policy can help manage fluctuations in aggregate demand, employment and price stability","government expenditure that generally does not create assets or directly reduce liabilities and mainly supports routine functioning and services"],"answer":0,"explanation":"Government budget: an annual statement of estimated government receipts and expenditure for the financial year"},{"q":"Which statement best explains \"Allocation objective\"?","options":["tax and expenditure policies can be used to reduce undesirable inequalities in income and wealth","budget policy can influence allocation of resources toward socially desirable goods, public services or priority sectors","government receipts that neither create a liability nor reduce government assets","government expenditure that creates assets or reduces liabilities"],"answer":1,"explanation":"Allocation objective: budget policy can influence allocation of resources toward socially desirable goods, public services or priority sectors"},{"q":"Which statement best explains \"Redistribution objective\"?","options":["budget policy can help manage fluctuations in aggregate demand, employment and price stability","government receipts that either create a liability or reduce assets","tax and expenditure policies can be used to reduce undesirable inequalities in income and wealth","revenue expenditure minus revenue receipts"],"answer":2,"explanation":"Redistribution objective: tax and expenditure policies can be used to reduce undesirable inequalities in income and wealth"},{"q":"Which statement best explains \"Stabilisation objective\"?","options":["government receipts that neither create a liability nor reduce government assets","government expenditure that generally does not create assets or directly reduce liabilities and mainly supports routine functioning and services","fiscal deficit is total expenditure minus total receipts excluding borrowings, while primary deficit equals fiscal deficit minus interest payments","budget policy can help manage fluctuations in aggregate demand, employment and price stability"],"answer":3,"explanation":"Stabilisation objective: budget policy can help manage fluctuations in aggregate demand, employment and price stability"},{"q":"Which statement best explains \"Revenue receipts\"?","options":["government receipts that neither create a liability nor reduce government assets","government receipts that either create a liability or reduce assets","government expenditure that creates assets or reduces liabilities","an annual statement of estimated government receipts and expenditure for the financial year"],"answer":0,"explanation":"Revenue receipts: government receipts that neither create a liability nor reduce government assets"},{"q":"Which statement best explains \"Capital receipts\"?","options":["government expenditure that generally does not create assets or directly reduce liabilities and mainly supports routine functioning and services","government receipts that either create a liability or reduce assets","revenue expenditure minus revenue receipts","budget policy can influence allocation of resources toward socially desirable goods, public services or priority sectors"],"answer":1,"explanation":"Capital receipts: government receipts that either create a liability or reduce assets"},{"q":"Which statement best explains \"Revenue expenditure\"?","options":["government expenditure that creates assets or reduces liabilities","fiscal deficit is total expenditure minus total receipts excluding borrowings, while primary deficit equals fiscal deficit minus interest payments","government expenditure that generally does not create assets or directly reduce liabilities and mainly supports routine functioning and services","tax and expenditure policies can be used to reduce undesirable inequalities in income and wealth"],"answer":2,"explanation":"Revenue expenditure: government expenditure that generally does not create assets or directly reduce liabilities and mainly supports routine functioning and services"},{"q":"Which statement best explains \"Capital expenditure\"?","options":["revenue expenditure minus revenue receipts","an annual statement of estimated government receipts and expenditure for the financial year","budget policy can help manage fluctuations in aggregate demand, employment and price stability","government expenditure that creates assets or reduces liabilities"],"answer":3,"explanation":"Capital expenditure: government expenditure that creates assets or reduces liabilities"},{"q":"Which statement best explains \"Revenue deficit\"?","options":["revenue expenditure minus revenue receipts","fiscal deficit is total expenditure minus total receipts excluding borrowings, while primary deficit equals fiscal deficit minus interest payments","budget policy can influence allocation of resources toward socially desirable goods, public services or priority sectors","government receipts that neither create a liability nor reduce government assets"],"answer":0,"explanation":"Revenue deficit: revenue expenditure minus revenue receipts"},{"q":"Which statement best explains \"Fiscal and primary deficit\"?","options":["an annual statement of estimated government receipts and expenditure for the financial year","fiscal deficit is total expenditure minus total receipts excluding borrowings, while primary deficit equals fiscal deficit minus interest payments","tax and expenditure policies can be used to reduce undesirable inequalities in income and wealth","government receipts that either create a liability or reduce assets"],"answer":1,"explanation":"Fiscal and primary deficit: fiscal deficit is total expenditure minus total receipts excluding borrowings, while primary deficit equals fiscal deficit minus interest payments"}],"Moderate":[{"q":"Which concept best matches this situation? The government presents expected revenue, borrowing and spending for the coming year.","options":["Allocation objective","Government budget","Stabilisation objective","Revenue expenditure"],"answer":1,"explanation":"Government budget: an annual statement of estimated government receipts and expenditure for the financial year"},{"q":"Which concept best matches this situation? Public spending is directed toward education or infrastructure.","options":["Redistribution objective","Revenue receipts","Allocation objective","Capital expenditure"],"answer":2,"explanation":"Allocation objective: budget policy can influence allocation of resources toward socially desirable goods, public services or priority sectors"},{"q":"Which concept best matches this situation? Progressive taxation finances programmes benefiting lower-income groups.","options":["Stabilisation objective","Capital receipts","Revenue deficit","Redistribution objective"],"answer":3,"explanation":"Redistribution objective: tax and expenditure policies can be used to reduce undesirable inequalities in income and wealth"},{"q":"Which concept best matches this situation? Expansionary fiscal action is used during weak demand.","options":["Stabilisation objective","Revenue receipts","Revenue expenditure","Fiscal and primary deficit"],"answer":0,"explanation":"Stabilisation objective: budget policy can help manage fluctuations in aggregate demand, employment and price stability"},{"q":"Which concept best matches this situation? Tax revenue and many non-tax revenues are revenue receipts.","options":["Capital receipts","Revenue receipts","Capital expenditure","Government budget"],"answer":1,"explanation":"Revenue receipts: government receipts that neither create a liability nor reduce government assets"},{"q":"Which concept best matches this situation? Borrowings create liabilities and recovery of loans reduces financial assets.","options":["Revenue expenditure","Revenue deficit","Capital receipts","Allocation objective"],"answer":2,"explanation":"Capital receipts: government receipts that either create a liability or reduce assets"},{"q":"Which concept best matches this situation? Routine administrative expenditure is classified as revenue expenditure.","options":["Capital expenditure","Fiscal and primary deficit","Redistribution objective","Revenue expenditure"],"answer":3,"explanation":"Revenue expenditure: government expenditure that generally does not create assets or directly reduce liabilities and mainly supports routine functioning and services"},{"q":"Which concept best matches this situation? Building a public asset or repaying debt principal affects the capital account.","options":["Capital expenditure","Revenue deficit","Government budget","Stabilisation objective"],"answer":0,"explanation":"Capital expenditure: government expenditure that creates assets or reduces liabilities"},{"q":"Which concept best matches this situation? Revenue expenditure 900 and revenue receipts 750 gives revenue deficit 150.","options":["Fiscal and primary deficit","Revenue deficit","Allocation objective","Revenue receipts"],"answer":1,"explanation":"Revenue deficit: revenue expenditure minus revenue receipts"},{"q":"Which concept best matches this situation? Fiscal deficit 500 with interest payments 120 gives primary deficit 380.","options":["Government budget","Redistribution objective","Fiscal and primary deficit","Capital receipts"],"answer":2,"explanation":"Fiscal and primary deficit: fiscal deficit is total expenditure minus total receipts excluding borrowings, while primary deficit equals fiscal deficit minus interest payments"}]}},{"id":"cbse-12-macro-bop","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Macroeconomics","title":"Balance of Payments and Foreign Exchange","chapter":"Macroeconomics Unit 5","sourceLabel":"Smit Sir Commerce — Class 12 Economics Quick Revision Pack (National Income, Money & Banking, Income Determination, Government Budget, Balance of Payments) + CBSE 2026–27 Economics syllabus","sourceStatus":"Smit Sir revision + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Balance of Payments\"?","options":["a systematic record of economic transactions between residents of a country and the rest of the world during a period","the BOP account covering transactions such as goods, services, income flows and current transfers under the prescribed classification","a situation in which autonomous external payments exceed autonomous receipts so financing or reserve adjustment is required under the accounting framework","foreign-currency supply arising from external receipts such as exports, remittances or foreign investment inflows"],"answer":0,"explanation":"Balance of Payments: a systematic record of economic transactions between residents of a country and the rest of the world during a period"},{"q":"Which statement best explains \"Current account\"?","options":["the BOP side recording transactions that change international assets or liabilities such as investment and borrowing or lending flows","the BOP account covering transactions such as goods, services, income flows and current transfers under the prescribed classification","the price of one currency in terms of another currency","an exchange rate largely determined by market demand and supply for foreign exchange"],"answer":1,"explanation":"Current account: the BOP account covering transactions such as goods, services, income flows and current transfers under the prescribed classification"},{"q":"Which statement best explains \"Capital or financial account\"?","options":["a situation in which autonomous external payments exceed autonomous receipts so financing or reserve adjustment is required under the accounting framework","demand arising from external payments such as imports, foreign travel or investment abroad","the BOP side recording transactions that change international assets or liabilities such as investment and borrowing or lending flows","an exchange rate officially maintained at a specified or tightly controlled level through policy intervention"],"answer":2,"explanation":"Capital or financial account: the BOP side recording transactions that change international assets or liabilities such as investment and borrowing or lending flows"},{"q":"Which statement best explains \"BOP deficit\"?","options":["the price of one currency in terms of another currency","foreign-currency supply arising from external receipts such as exports, remittances or foreign investment inflows","a regime where market forces influence the exchange rate but the monetary authority may intervene to moderate movements","a situation in which autonomous external payments exceed autonomous receipts so financing or reserve adjustment is required under the accounting framework"],"answer":3,"explanation":"BOP deficit: a situation in which autonomous external payments exceed autonomous receipts so financing or reserve adjustment is required under the accounting framework"},{"q":"Which statement best explains \"Foreign exchange rate\"?","options":["the price of one currency in terms of another currency","demand arising from external payments such as imports, foreign travel or investment abroad","an exchange rate largely determined by market demand and supply for foreign exchange","a systematic record of economic transactions between residents of a country and the rest of the world during a period"],"answer":0,"explanation":"Foreign exchange rate: the price of one currency in terms of another currency"},{"q":"Which statement best explains \"Demand for foreign exchange\"?","options":["foreign-currency supply arising from external receipts such as exports, remittances or foreign investment inflows","demand arising from external payments such as imports, foreign travel or investment abroad","an exchange rate officially maintained at a specified or tightly controlled level through policy intervention","the BOP account covering transactions such as goods, services, income flows and current transfers under the prescribed classification"],"answer":1,"explanation":"Demand for foreign exchange: demand arising from external payments such as imports, foreign travel or investment abroad"},{"q":"Which statement best explains \"Supply of foreign exchange\"?","options":["an exchange rate largely determined by market demand and supply for foreign exchange","a regime where market forces influence the exchange rate but the monetary authority may intervene to moderate movements","foreign-currency supply arising from external receipts such as exports, remittances or foreign investment inflows","the BOP side recording transactions that change international assets or liabilities such as investment and borrowing or lending flows"],"answer":2,"explanation":"Supply of foreign exchange: foreign-currency supply arising from external receipts such as exports, remittances or foreign investment inflows"},{"q":"Which statement best explains \"Flexible exchange rate\"?","options":["an exchange rate officially maintained at a specified or tightly controlled level through policy intervention","a systematic record of economic transactions between residents of a country and the rest of the world during a period","a situation in which autonomous external payments exceed autonomous receipts so financing or reserve adjustment is required under the accounting framework","an exchange rate largely determined by market demand and supply for foreign exchange"],"answer":3,"explanation":"Flexible exchange rate: an exchange rate largely determined by market demand and supply for foreign exchange"},{"q":"Which statement best explains \"Fixed exchange rate\"?","options":["an exchange rate officially maintained at a specified or tightly controlled level through policy intervention","a regime where market forces influence the exchange rate but the monetary authority may intervene to moderate movements","the BOP account covering transactions such as goods, services, income flows and current transfers under the prescribed classification","the price of one currency in terms of another currency"],"answer":0,"explanation":"Fixed exchange rate: an exchange rate officially maintained at a specified or tightly controlled level through policy intervention"},{"q":"Which statement best explains \"Managed floating\"?","options":["a systematic record of economic transactions between residents of a country and the rest of the world during a period","a regime where market forces influence the exchange rate but the monetary authority may intervene to moderate movements","the BOP side recording transactions that change international assets or liabilities such as investment and borrowing or lending flows","demand arising from external payments such as imports, foreign travel or investment abroad"],"answer":1,"explanation":"Managed floating: a regime where market forces influence the exchange rate but the monetary authority may intervene to moderate movements"}],"Moderate":[{"q":"Which concept best matches this situation? Transactions involving goods, services, income, transfers and cross-border financial flows are recorded.","options":["Current account","Balance of Payments","BOP deficit","Supply of foreign exchange"],"answer":1,"explanation":"Balance of Payments: a systematic record of economic transactions between residents of a country and the rest of the world during a period"},{"q":"Which concept best matches this situation? Export of services is recorded on the current account.","options":["Capital or financial account","Foreign exchange rate","Current account","Flexible exchange rate"],"answer":2,"explanation":"Current account: the BOP account covering transactions such as goods, services, income flows and current transfers under the prescribed classification"},{"q":"Which concept best matches this situation? Foreign investment in domestic assets changes cross-border financial claims.","options":["BOP deficit","Demand for foreign exchange","Fixed exchange rate","Capital or financial account"],"answer":3,"explanation":"Capital or financial account: the BOP side recording transactions that change international assets or liabilities such as investment and borrowing or lending flows"},{"q":"Which concept best matches this situation? External transactions create a financing gap that must be met through appropriate capital or reserve flows.","options":["BOP deficit","Foreign exchange rate","Supply of foreign exchange","Managed floating"],"answer":0,"explanation":"BOP deficit: a situation in which autonomous external payments exceed autonomous receipts so financing or reserve adjustment is required under the accounting framework"},{"q":"Which concept best matches this situation? ₹ per US dollar states how many rupees exchange for one dollar.","options":["Demand for foreign exchange","Foreign exchange rate","Flexible exchange rate","Balance of Payments"],"answer":1,"explanation":"Foreign exchange rate: the price of one currency in terms of another currency"},{"q":"Which concept best matches this situation? An importer needs dollars to pay a US supplier.","options":["Supply of foreign exchange","Fixed exchange rate","Demand for foreign exchange","Current account"],"answer":2,"explanation":"Demand for foreign exchange: demand arising from external payments such as imports, foreign travel or investment abroad"},{"q":"Which concept best matches this situation? An exporter receives foreign currency from an overseas buyer.","options":["Flexible exchange rate","Managed floating","Capital or financial account","Supply of foreign exchange"],"answer":3,"explanation":"Supply of foreign exchange: foreign-currency supply arising from external receipts such as exports, remittances or foreign investment inflows"},{"q":"Which concept best matches this situation? A rise in demand for dollars can change the market exchange rate when other factors are unchanged.","options":["Flexible exchange rate","Fixed exchange rate","Balance of Payments","BOP deficit"],"answer":0,"explanation":"Flexible exchange rate: an exchange rate largely determined by market demand and supply for foreign exchange"},{"q":"Which concept best matches this situation? The monetary authority commits to defend a stated parity within the regime.","options":["Managed floating","Fixed exchange rate","Current account","Foreign exchange rate"],"answer":1,"explanation":"Fixed exchange rate: an exchange rate officially maintained at a specified or tightly controlled level through policy intervention"},{"q":"Which concept best matches this situation? The central bank buys or sells foreign currency while allowing the rate to move.","options":["Balance of Payments","Capital or financial account","Managed floating","Demand for foreign exchange"],"answer":2,"explanation":"Managed floating: a regime where market forces influence the exchange rate but the monetary authority may intervene to moderate movements"}]}},{"id":"cbse-12-ied-ch1","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Indian Economic Development","title":"Indian Economy on the Eve of Independence","chapter":"IED Chapter 1","sourceLabel":"T.R. Jain & V.K. Ohri — Indian Economic Development, Class XII (2020-21 reference edition); aligned to CBSE 2026–27 Indian Economic Development scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Colonial exploitation\"?","options":["use of India’s resources and economic structure primarily to serve the interests of British rule rather than India’s development","a land-revenue arrangement using intermediaries who collected revenue from cultivators, weakening incentives and resources for agricultural investment","trade policy favouring British manufactured goods and the export of Indian raw materials","weak development of modern basic and capital-goods industries alongside the decline of traditional industries"],"answer":0,"explanation":"Colonial exploitation: use of India’s resources and economic structure primarily to serve the interests of British rule rather than India’s development"},{"q":"Which statement best explains \"Zamindari system\"?","options":["decline of traditional Indian handicrafts under colonial trade and industrial policies","a land-revenue arrangement using intermediaries who collected revenue from cultivators, weakening incentives and resources for agricultural investment","an economy showing little or very slow growth in income and output over long periods","India became an exporter of primary materials and an importer of British manufactured goods, with trade serving colonial interests"],"answer":1,"explanation":"Zamindari system: a land-revenue arrangement using intermediaries who collected revenue from cultivators, weakening incentives and resources for agricultural investment"},{"q":"Which statement best explains \"Deindustrialisation of handicrafts\"?","options":["trade policy favouring British manufactured goods and the export of Indian raw materials","low productivity, poor technology, weak investment and heavy dependence on agriculture under colonial conditions","decline of traditional Indian handicrafts under colonial trade and industrial policies","high mortality, low life expectancy, poor health conditions and low literacy reflected weak human development under colonial rule"],"answer":2,"explanation":"Deindustrialisation of handicrafts: decline of traditional Indian handicrafts under colonial trade and industrial policies"},{"q":"Which statement best explains \"Discriminatory tariff policy\"?","options":["an economy showing little or very slow growth in income and output over long periods","weak development of modern basic and capital-goods industries alongside the decline of traditional industries","the workforce remained heavily concentrated in agriculture while infrastructure was developed selectively to support colonial administration and trade","trade policy favouring British manufactured goods and the export of Indian raw materials"],"answer":3,"explanation":"Discriminatory tariff policy: trade policy favouring British manufactured goods and the export of Indian raw materials"},{"q":"Which statement best explains \"Stagnant economy\"?","options":["an economy showing little or very slow growth in income and output over long periods","low productivity, poor technology, weak investment and heavy dependence on agriculture under colonial conditions","India became an exporter of primary materials and an importer of British manufactured goods, with trade serving colonial interests","use of India’s resources and economic structure primarily to serve the interests of British rule rather than India’s development"],"answer":0,"explanation":"Stagnant economy: an economy showing little or very slow growth in income and output over long periods"},{"q":"Which statement best explains \"Agricultural backwardness\"?","options":["weak development of modern basic and capital-goods industries alongside the decline of traditional industries","low productivity, poor technology, weak investment and heavy dependence on agriculture under colonial conditions","high mortality, low life expectancy, poor health conditions and low literacy reflected weak human development under colonial rule","a land-revenue arrangement using intermediaries who collected revenue from cultivators, weakening incentives and resources for agricultural investment"],"answer":1,"explanation":"Agricultural backwardness: low productivity, poor technology, weak investment and heavy dependence on agriculture under colonial conditions"},{"q":"Which statement best explains \"Industrial backwardness\"?","options":["India became an exporter of primary materials and an importer of British manufactured goods, with trade serving colonial interests","the workforce remained heavily concentrated in agriculture while infrastructure was developed selectively to support colonial administration and trade","weak development of modern basic and capital-goods industries alongside the decline of traditional industries","decline of traditional Indian handicrafts under colonial trade and industrial policies"],"answer":2,"explanation":"Industrial backwardness: weak development of modern basic and capital-goods industries alongside the decline of traditional industries"},{"q":"Which statement best explains \"Colonial foreign-trade pattern\"?","options":["high mortality, low life expectancy, poor health conditions and low literacy reflected weak human development under colonial rule","use of India’s resources and economic structure primarily to serve the interests of British rule rather than India’s development","trade policy favouring British manufactured goods and the export of Indian raw materials","India became an exporter of primary materials and an importer of British manufactured goods, with trade serving colonial interests"],"answer":3,"explanation":"Colonial foreign-trade pattern: India became an exporter of primary materials and an importer of British manufactured goods, with trade serving colonial interests"},{"q":"Which statement best explains \"Poor demographic profile\"?","options":["high mortality, low life expectancy, poor health conditions and low literacy reflected weak human development under colonial rule","the workforce remained heavily concentrated in agriculture while infrastructure was developed selectively to support colonial administration and trade","a land-revenue arrangement using intermediaries who collected revenue from cultivators, weakening incentives and resources for agricultural investment","an economy showing little or very slow growth in income and output over long periods"],"answer":0,"explanation":"Poor demographic profile: high mortality, low life expectancy, poor health conditions and low literacy reflected weak human development under colonial rule"},{"q":"Which statement best explains \"Unbalanced occupational and infrastructure structure\"?","options":["use of India’s resources and economic structure primarily to serve the interests of British rule rather than India’s development","the workforce remained heavily concentrated in agriculture while infrastructure was developed selectively to support colonial administration and trade","decline of traditional Indian handicrafts under colonial trade and industrial policies","low productivity, poor technology, weak investment and heavy dependence on agriculture under colonial conditions"],"answer":1,"explanation":"Unbalanced occupational and infrastructure structure: the workforce remained heavily concentrated in agriculture while infrastructure was developed selectively to support colonial administration and trade"}],"Moderate":[{"q":"Which concept best matches this situation? Trade, land revenue and industrial policy were shaped around colonial needs.","options":["Zamindari system","Colonial exploitation","Discriminatory tariff policy","Industrial backwardness"],"answer":1,"explanation":"Colonial exploitation: use of India’s resources and economic structure primarily to serve the interests of British rule rather than India’s development"},{"q":"Which concept best matches this situation? Actual tillers retained little surplus while intermediaries collected revenue.","options":["Deindustrialisation of handicrafts","Stagnant economy","Zamindari system","Colonial foreign-trade pattern"],"answer":2,"explanation":"Zamindari system: a land-revenue arrangement using intermediaries who collected revenue from cultivators, weakening incentives and resources for agricultural investment"},{"q":"Which concept best matches this situation? Imported machine-made goods displaced many domestic craft products.","options":["Discriminatory tariff policy","Agricultural backwardness","Poor demographic profile","Deindustrialisation of handicrafts"],"answer":3,"explanation":"Deindustrialisation of handicrafts: decline of traditional Indian handicrafts under colonial trade and industrial policies"},{"q":"Which concept best matches this situation? Indian raw materials moved outward while British finished goods entered Indian markets on favourable terms.","options":["Discriminatory tariff policy","Stagnant economy","Industrial backwardness","Unbalanced occupational and infrastructure structure"],"answer":0,"explanation":"Discriminatory tariff policy: trade policy favouring British manufactured goods and the export of Indian raw materials"},{"q":"Which concept best matches this situation? Per-capita income barely improves for decades.","options":["Agricultural backwardness","Stagnant economy","Colonial foreign-trade pattern","Colonial exploitation"],"answer":1,"explanation":"Stagnant economy: an economy showing little or very slow growth in income and output over long periods"},{"q":"Which concept best matches this situation? A large workforce depends on farming but output per worker remains low.","options":["Industrial backwardness","Poor demographic profile","Agricultural backwardness","Zamindari system"],"answer":2,"explanation":"Agricultural backwardness: low productivity, poor technology, weak investment and heavy dependence on agriculture under colonial conditions"},{"q":"Which concept best matches this situation? The economy depends heavily on imported machinery and lacks a broad industrial base.","options":["Colonial foreign-trade pattern","Unbalanced occupational and infrastructure structure","Deindustrialisation of handicrafts","Industrial backwardness"],"answer":3,"explanation":"Industrial backwardness: weak development of modern basic and capital-goods industries alongside the decline of traditional industries"},{"q":"Which concept best matches this situation? Raw cotton leaves India and manufactured textiles return from Britain.","options":["Colonial foreign-trade pattern","Poor demographic profile","Colonial exploitation","Discriminatory tariff policy"],"answer":0,"explanation":"Colonial foreign-trade pattern: India became an exporter of primary materials and an importer of British manufactured goods, with trade serving colonial interests"},{"q":"Which concept best matches this situation? Public-health and education outcomes remain poor despite a large population.","options":["Unbalanced occupational and infrastructure structure","Poor demographic profile","Zamindari system","Stagnant economy"],"answer":1,"explanation":"Poor demographic profile: high mortality, low life expectancy, poor health conditions and low literacy reflected weak human development under colonial rule"},{"q":"Which concept best matches this situation? Railways expand but productive diversification and broad social infrastructure remain limited.","options":["Colonial exploitation","Deindustrialisation of handicrafts","Unbalanced occupational and infrastructure structure","Agricultural backwardness"],"answer":2,"explanation":"Unbalanced occupational and infrastructure structure: the workforce remained heavily concentrated in agriculture while infrastructure was developed selectively to support colonial administration and trade"}]}},{"id":"cbse-12-ied-ch2","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Indian Economic Development","title":"Five Year Plans in India — Goals and Achievements","chapter":"IED Chapter 2","sourceLabel":"T.R. Jain & V.K. Ohri — Indian Economic Development, Class XII (2020-21 reference edition); aligned to CBSE 2026–27 Indian Economic Development scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Economic planning\"?","options":["deliberate allocation and coordination of resources through national plans to pursue specified development goals","raising the economy’s capacity to produce goods and services and increasing national and per-capita output over time","reducing excessive dependence on foreign assistance and building domestic capacity for essential production and development","the state was assigned a major role in heavy industry, infrastructure and strategic investment during the planning era"],"answer":0,"explanation":"Economic planning: deliberate allocation and coordination of resources through national plans to pursue specified development goals"},{"q":"Which statement best explains \"Growth goal\"?","options":["adoption of new technology, institutions and social outlooks that improve productivity and economic capability","raising the economy’s capacity to produce goods and services and increasing national and per-capita output over time","ensuring that the benefits of growth are distributed more fairly and basic needs are addressed","development plans allocate resources according to changing national priorities rather than treating all sectors identically"],"answer":1,"explanation":"Growth goal: raising the economy’s capacity to produce goods and services and increasing national and per-capita output over time"},{"q":"Which statement best explains \"Modernisation goal\"?","options":["reducing excessive dependence on foreign assistance and building domestic capacity for essential production and development","a development model in which both public and private sectors participate in economic activity","adoption of new technology, institutions and social outlooks that improve productivity and economic capability","planning tries to expand output while also ensuring that gains improve broader welfare"],"answer":2,"explanation":"Modernisation goal: adoption of new technology, institutions and social outlooks that improve productivity and economic capability"},{"q":"Which statement best explains \"Self-reliance goal\"?","options":["ensuring that the benefits of growth are distributed more fairly and basic needs are addressed","the state was assigned a major role in heavy industry, infrastructure and strategic investment during the planning era","the planned shift from a predominantly low-productivity agrarian economy toward more diversified industry and services","reducing excessive dependence on foreign assistance and building domestic capacity for essential production and development"],"answer":3,"explanation":"Self-reliance goal: reducing excessive dependence on foreign assistance and building domestic capacity for essential production and development"},{"q":"Which statement best explains \"Equity goal\"?","options":["ensuring that the benefits of growth are distributed more fairly and basic needs are addressed","a development model in which both public and private sectors participate in economic activity","development plans allocate resources according to changing national priorities rather than treating all sectors identically","deliberate allocation and coordination of resources through national plans to pursue specified development goals"],"answer":0,"explanation":"Equity goal: ensuring that the benefits of growth are distributed more fairly and basic needs are addressed"},{"q":"Which statement best explains \"Mixed-economy strategy\"?","options":["the state was assigned a major role in heavy industry, infrastructure and strategic investment during the planning era","a development model in which both public and private sectors participate in economic activity","planning tries to expand output while also ensuring that gains improve broader welfare","raising the economy’s capacity to produce goods and services and increasing national and per-capita output over time"],"answer":1,"explanation":"Mixed-economy strategy: a development model in which both public and private sectors participate in economic activity"},{"q":"Which statement best explains \"Public-sector leadership\"?","options":["development plans allocate resources according to changing national priorities rather than treating all sectors identically","the planned shift from a predominantly low-productivity agrarian economy toward more diversified industry and services","the state was assigned a major role in heavy industry, infrastructure and strategic investment during the planning era","adoption of new technology, institutions and social outlooks that improve productivity and economic capability"],"answer":2,"explanation":"Public-sector leadership: the state was assigned a major role in heavy industry, infrastructure and strategic investment during the planning era"},{"q":"Which statement best explains \"Plan priorities\"?","options":["planning tries to expand output while also ensuring that gains improve broader welfare","deliberate allocation and coordination of resources through national plans to pursue specified development goals","reducing excessive dependence on foreign assistance and building domestic capacity for essential production and development","development plans allocate resources according to changing national priorities rather than treating all sectors identically"],"answer":3,"explanation":"Plan priorities: development plans allocate resources according to changing national priorities rather than treating all sectors identically"},{"q":"Which statement best explains \"Growth–equity balance\"?","options":["planning tries to expand output while also ensuring that gains improve broader welfare","the planned shift from a predominantly low-productivity agrarian economy toward more diversified industry and services","raising the economy’s capacity to produce goods and services and increasing national and per-capita output over time","ensuring that the benefits of growth are distributed more fairly and basic needs are addressed"],"answer":0,"explanation":"Growth–equity balance: planning tries to expand output while also ensuring that gains improve broader welfare"},{"q":"Which statement best explains \"Structural transformation\"?","options":["deliberate allocation and coordination of resources through national plans to pursue specified development goals","the planned shift from a predominantly low-productivity agrarian economy toward more diversified industry and services","adoption of new technology, institutions and social outlooks that improve productivity and economic capability","a development model in which both public and private sectors participate in economic activity"],"answer":1,"explanation":"Structural transformation: the planned shift from a predominantly low-productivity agrarian economy toward more diversified industry and services"}],"Moderate":[{"q":"Which concept best matches this situation? The government sets priorities for investment across agriculture, industry and infrastructure.","options":["Growth goal","Economic planning","Self-reliance goal","Public-sector leadership"],"answer":1,"explanation":"Economic planning: deliberate allocation and coordination of resources through national plans to pursue specified development goals"},{"q":"Which concept best matches this situation? Investment expands productive capacity and output.","options":["Modernisation goal","Equity goal","Growth goal","Plan priorities"],"answer":2,"explanation":"Growth goal: raising the economy’s capacity to produce goods and services and increasing national and per-capita output over time"},{"q":"Which concept best matches this situation? Modern machinery and improved production methods are introduced.","options":["Self-reliance goal","Mixed-economy strategy","Growth–equity balance","Modernisation goal"],"answer":3,"explanation":"Modernisation goal: adoption of new technology, institutions and social outlooks that improve productivity and economic capability"},{"q":"Which concept best matches this situation? Domestic industries are developed to reduce critical import dependence.","options":["Self-reliance goal","Equity goal","Public-sector leadership","Structural transformation"],"answer":0,"explanation":"Self-reliance goal: reducing excessive dependence on foreign assistance and building domestic capacity for essential production and development"},{"q":"Which concept best matches this situation? Development policy seeks to reduce extreme inequality and deprivation.","options":["Mixed-economy strategy","Equity goal","Plan priorities","Economic planning"],"answer":1,"explanation":"Equity goal: ensuring that the benefits of growth are distributed more fairly and basic needs are addressed"},{"q":"Which concept best matches this situation? Private firms operate while the state controls or invests in strategic sectors.","options":["Public-sector leadership","Growth–equity balance","Mixed-economy strategy","Growth goal"],"answer":2,"explanation":"Mixed-economy strategy: a development model in which both public and private sectors participate in economic activity"},{"q":"Which concept best matches this situation? Government investment supports projects requiring large capital and long gestation periods.","options":["Plan priorities","Structural transformation","Modernisation goal","Public-sector leadership"],"answer":3,"explanation":"Public-sector leadership: the state was assigned a major role in heavy industry, infrastructure and strategic investment during the planning era"},{"q":"Which concept best matches this situation? A plan may emphasise agriculture first and later give more weight to industrialisation.","options":["Plan priorities","Growth–equity balance","Economic planning","Self-reliance goal"],"answer":0,"explanation":"Plan priorities: development plans allocate resources according to changing national priorities rather than treating all sectors identically"},{"q":"Which concept best matches this situation? A policy is assessed both for output growth and its effect on poorer groups.","options":["Structural transformation","Growth–equity balance","Growth goal","Equity goal"],"answer":1,"explanation":"Growth–equity balance: planning tries to expand output while also ensuring that gains improve broader welfare"},{"q":"Which concept best matches this situation? Investment in industry and infrastructure reduces excessive dependence on agriculture.","options":["Economic planning","Modernisation goal","Structural transformation","Mixed-economy strategy"],"answer":2,"explanation":"Structural transformation: the planned shift from a predominantly low-productivity agrarian economy toward more diversified industry and services"}]}},{"id":"cbse-12-ied-ch3","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Indian Economic Development","title":"Features, Problems and Policies of Agriculture","chapter":"IED Chapter 3","sourceLabel":"T.R. Jain & V.K. Ohri — Indian Economic Development, Class XII (2020-21 reference edition); aligned to CBSE 2026–27 Indian Economic Development scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Importance of agriculture\"?","options":["agriculture supports food supply, livelihoods, raw materials and links with the wider economy","institutional changes intended to improve the agrarian structure, tenancy conditions and distribution or use of land","a policy placing an upper limit on land holdings so surplus land can potentially be redistributed","the portion of farm output available for sale after meeting the producer household’s own requirements"],"answer":0,"explanation":"Importance of agriculture: agriculture supports food supply, livelihoods, raw materials and links with the wider economy"},{"q":"Which statement best explains \"Land reforms\"?","options":["a land-reform measure aimed at removing layers between the state and actual cultivators","institutional changes intended to improve the agrarian structure, tenancy conditions and distribution or use of land","the strategy of raising agricultural productivity through high-yielding seeds combined with irrigation, fertilisers and other modern inputs","farm finance provided through organised institutions such as cooperatives and banks rather than informal moneylenders"],"answer":1,"explanation":"Land reforms: institutional changes intended to improve the agrarian structure, tenancy conditions and distribution or use of land"},{"q":"Which statement best explains \"Abolition of intermediaries\"?","options":["a policy placing an upper limit on land holdings so surplus land can potentially be redistributed","improved seeds capable of producing higher output when supported by suitable inputs and conditions","a land-reform measure aimed at removing layers between the state and actual cultivators","government support that lowers the effective cost of selected farm inputs or services to pursue policy objectives"],"answer":2,"explanation":"Abolition of intermediaries: a land-reform measure aimed at removing layers between the state and actual cultivators"},{"q":"Which statement best explains \"Land ceiling\"?","options":["the strategy of raising agricultural productivity through high-yielding seeds combined with irrigation, fertilisers and other modern inputs","the portion of farm output available for sale after meeting the producer household’s own requirements","the need to raise output per unit of land or labour through better technology, irrigation, institutions and resource use","a policy placing an upper limit on land holdings so surplus land can potentially be redistributed"],"answer":3,"explanation":"Land ceiling: a policy placing an upper limit on land holdings so surplus land can potentially be redistributed"},{"q":"Which statement best explains \"Green Revolution\"?","options":["the strategy of raising agricultural productivity through high-yielding seeds combined with irrigation, fertilisers and other modern inputs","improved seeds capable of producing higher output when supported by suitable inputs and conditions","farm finance provided through organised institutions such as cooperatives and banks rather than informal moneylenders","agriculture supports food supply, livelihoods, raw materials and links with the wider economy"],"answer":0,"explanation":"Green Revolution: the strategy of raising agricultural productivity through high-yielding seeds combined with irrigation, fertilisers and other modern inputs"},{"q":"Which statement best explains \"High-Yielding Variety seeds\"?","options":["the portion of farm output available for sale after meeting the producer household’s own requirements","improved seeds capable of producing higher output when supported by suitable inputs and conditions","government support that lowers the effective cost of selected farm inputs or services to pursue policy objectives","institutional changes intended to improve the agrarian structure, tenancy conditions and distribution or use of land"],"answer":1,"explanation":"High-Yielding Variety seeds: improved seeds capable of producing higher output when supported by suitable inputs and conditions"},{"q":"Which statement best explains \"Marketable surplus\"?","options":["farm finance provided through organised institutions such as cooperatives and banks rather than informal moneylenders","the need to raise output per unit of land or labour through better technology, irrigation, institutions and resource use","the portion of farm output available for sale after meeting the producer household’s own requirements","a land-reform measure aimed at removing layers between the state and actual cultivators"],"answer":2,"explanation":"Marketable surplus: the portion of farm output available for sale after meeting the producer household’s own requirements"},{"q":"Which statement best explains \"Institutional agricultural credit\"?","options":["government support that lowers the effective cost of selected farm inputs or services to pursue policy objectives","agriculture supports food supply, livelihoods, raw materials and links with the wider economy","a policy placing an upper limit on land holdings so surplus land can potentially be redistributed","farm finance provided through organised institutions such as cooperatives and banks rather than informal moneylenders"],"answer":3,"explanation":"Institutional agricultural credit: farm finance provided through organised institutions such as cooperatives and banks rather than informal moneylenders"},{"q":"Which statement best explains \"Agricultural subsidies\"?","options":["government support that lowers the effective cost of selected farm inputs or services to pursue policy objectives","the need to raise output per unit of land or labour through better technology, irrigation, institutions and resource use","institutional changes intended to improve the agrarian structure, tenancy conditions and distribution or use of land","the strategy of raising agricultural productivity through high-yielding seeds combined with irrigation, fertilisers and other modern inputs"],"answer":0,"explanation":"Agricultural subsidies: government support that lowers the effective cost of selected farm inputs or services to pursue policy objectives"},{"q":"Which statement best explains \"Agricultural productivity challenge\"?","options":["agriculture supports food supply, livelihoods, raw materials and links with the wider economy","the need to raise output per unit of land or labour through better technology, irrigation, institutions and resource use","a land-reform measure aimed at removing layers between the state and actual cultivators","improved seeds capable of producing higher output when supported by suitable inputs and conditions"],"answer":1,"explanation":"Agricultural productivity challenge: the need to raise output per unit of land or labour through better technology, irrigation, institutions and resource use"}],"Moderate":[{"q":"Which concept best matches this situation? Farm output feeds households and supplies inputs to agro-based industries.","options":["Land reforms","Importance of agriculture","Land ceiling","Marketable surplus"],"answer":1,"explanation":"Importance of agriculture: agriculture supports food supply, livelihoods, raw materials and links with the wider economy"},{"q":"Which concept best matches this situation? Policy removes exploitative intermediaries and seeks more secure cultivation rights.","options":["Abolition of intermediaries","Green Revolution","Land reforms","Institutional agricultural credit"],"answer":2,"explanation":"Land reforms: institutional changes intended to improve the agrarian structure, tenancy conditions and distribution or use of land"},{"q":"Which concept best matches this situation? The cultivator gains a more direct relationship with land administration.","options":["Land ceiling","High-Yielding Variety seeds","Agricultural subsidies","Abolition of intermediaries"],"answer":3,"explanation":"Abolition of intermediaries: a land-reform measure aimed at removing layers between the state and actual cultivators"},{"q":"Which concept best matches this situation? Holdings above a prescribed limit become subject to redistribution rules.","options":["Land ceiling","Green Revolution","Marketable surplus","Agricultural productivity challenge"],"answer":0,"explanation":"Land ceiling: a policy placing an upper limit on land holdings so surplus land can potentially be redistributed"},{"q":"Which concept best matches this situation? Farmers adopt HYV seeds with assured water and chemical inputs.","options":["High-Yielding Variety seeds","Green Revolution","Institutional agricultural credit","Importance of agriculture"],"answer":1,"explanation":"Green Revolution: the strategy of raising agricultural productivity through high-yielding seeds combined with irrigation, fertilisers and other modern inputs"},{"q":"Which concept best matches this situation? A farmer combines HYV wheat seed with irrigation and fertiliser.","options":["Marketable surplus","Agricultural subsidies","High-Yielding Variety seeds","Land reforms"],"answer":2,"explanation":"High-Yielding Variety seeds: improved seeds capable of producing higher output when supported by suitable inputs and conditions"},{"q":"Which concept best matches this situation? A farmer keeps grain for family use and sells the remaining quantity.","options":["Institutional agricultural credit","Agricultural productivity challenge","Abolition of intermediaries","Marketable surplus"],"answer":3,"explanation":"Marketable surplus: the portion of farm output available for sale after meeting the producer household’s own requirements"},{"q":"Which concept best matches this situation? A farmer obtains a crop loan from a bank.","options":["Institutional agricultural credit","Agricultural subsidies","Importance of agriculture","Land ceiling"],"answer":0,"explanation":"Institutional agricultural credit: farm finance provided through organised institutions such as cooperatives and banks rather than informal moneylenders"},{"q":"Which concept best matches this situation? Support reduces the farmer’s effective cost of an input.","options":["Agricultural productivity challenge","Agricultural subsidies","Land reforms","Green Revolution"],"answer":1,"explanation":"Agricultural subsidies: government support that lowers the effective cost of selected farm inputs or services to pursue policy objectives"},{"q":"Which concept best matches this situation? The same land produces more because of improved seeds, water management and skills.","options":["Importance of agriculture","Abolition of intermediaries","Agricultural productivity challenge","High-Yielding Variety seeds"],"answer":2,"explanation":"Agricultural productivity challenge: the need to raise output per unit of land or labour through better technology, irrigation, institutions and resource use"}]}},{"id":"cbse-12-ied-ch4","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Indian Economic Development","title":"Strategy of Industrial Growth (1947–1990)","chapter":"IED Chapter 4","sourceLabel":"T.R. Jain & V.K. Ohri — Indian Economic Development, Class XII (2020-21 reference edition); aligned to CBSE 2026–27 Indian Economic Development scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Industrialisation strategy\"?","options":["post-independence policy aimed at building a diversified industrial base and reducing structural dependence on agriculture and imports","a major policy framework that assigned an important role to the public sector and classified industries by the extent of state responsibility","a regulatory system requiring government permission for establishing, expanding or changing capacity in many industries during the controlled regime","the strategy gave priority to capital goods and basic industries to build long-term productive capacity"],"answer":0,"explanation":"Industrialisation strategy: post-independence policy aimed at building a diversified industrial base and reducing structural dependence on agriculture and imports"},{"q":"Which statement best explains \"Industrial Policy Resolution 1956\"?","options":["government enterprises were expected to lead investment in strategic, basic and heavy industries requiring large capital","a major policy framework that assigned an important role to the public sector and classified industries by the extent of state responsibility","policy support to smaller enterprises for employment, regional dispersion and more equitable industrial development","private enterprise operated within a framework of licensing and policy controls during much of the pre-reform period"],"answer":1,"explanation":"Industrial Policy Resolution 1956: a major policy framework that assigned an important role to the public sector and classified industries by the extent of state responsibility"},{"q":"Which statement best explains \"Public-sector role in industry\"?","options":["a regulatory system requiring government permission for establishing, expanding or changing capacity in many industries during the controlled regime","certain products were reserved for production by small-scale units to protect and promote that sector","government enterprises were expected to lead investment in strategic, basic and heavy industries requiring large capital","industrial policy sought to spread industrial activity beyond already developed areas"],"answer":2,"explanation":"Public-sector role in industry: government enterprises were expected to lead investment in strategic, basic and heavy industries requiring large capital"},{"q":"Which statement best explains \"Industrial licensing\"?","options":["policy support to smaller enterprises for employment, regional dispersion and more equitable industrial development","the strategy gave priority to capital goods and basic industries to build long-term productive capacity","industrial policy also used small-scale and dispersed production to create jobs and broaden participation in growth","a regulatory system requiring government permission for establishing, expanding or changing capacity in many industries during the controlled regime"],"answer":3,"explanation":"Industrial licensing: a regulatory system requiring government permission for establishing, expanding or changing capacity in many industries during the controlled regime"},{"q":"Which statement best explains \"Small-scale industry promotion\"?","options":["policy support to smaller enterprises for employment, regional dispersion and more equitable industrial development","certain products were reserved for production by small-scale units to protect and promote that sector","private enterprise operated within a framework of licensing and policy controls during much of the pre-reform period","post-independence policy aimed at building a diversified industrial base and reducing structural dependence on agriculture and imports"],"answer":0,"explanation":"Small-scale industry promotion: policy support to smaller enterprises for employment, regional dispersion and more equitable industrial development"},{"q":"Which statement best explains \"Reservation for small-scale industries\"?","options":["the strategy gave priority to capital goods and basic industries to build long-term productive capacity","certain products were reserved for production by small-scale units to protect and promote that sector","industrial policy sought to spread industrial activity beyond already developed areas","a major policy framework that assigned an important role to the public sector and classified industries by the extent of state responsibility"],"answer":1,"explanation":"Reservation for small-scale industries: certain products were reserved for production by small-scale units to protect and promote that sector"},{"q":"Which statement best explains \"Heavy-industry emphasis\"?","options":["private enterprise operated within a framework of licensing and policy controls during much of the pre-reform period","industrial policy also used small-scale and dispersed production to create jobs and broaden participation in growth","the strategy gave priority to capital goods and basic industries to build long-term productive capacity","government enterprises were expected to lead investment in strategic, basic and heavy industries requiring large capital"],"answer":2,"explanation":"Heavy-industry emphasis: the strategy gave priority to capital goods and basic industries to build long-term productive capacity"},{"q":"Which statement best explains \"Private-sector regulation\"?","options":["industrial policy sought to spread industrial activity beyond already developed areas","post-independence policy aimed at building a diversified industrial base and reducing structural dependence on agriculture and imports","a regulatory system requiring government permission for establishing, expanding or changing capacity in many industries during the controlled regime","private enterprise operated within a framework of licensing and policy controls during much of the pre-reform period"],"answer":3,"explanation":"Private-sector regulation: private enterprise operated within a framework of licensing and policy controls during much of the pre-reform period"},{"q":"Which statement best explains \"Regional balance objective\"?","options":["industrial policy sought to spread industrial activity beyond already developed areas","industrial policy also used small-scale and dispersed production to create jobs and broaden participation in growth","a major policy framework that assigned an important role to the public sector and classified industries by the extent of state responsibility","policy support to smaller enterprises for employment, regional dispersion and more equitable industrial development"],"answer":0,"explanation":"Regional balance objective: industrial policy sought to spread industrial activity beyond already developed areas"},{"q":"Which statement best explains \"Employment and equity through industry\"?","options":["post-independence policy aimed at building a diversified industrial base and reducing structural dependence on agriculture and imports","industrial policy also used small-scale and dispersed production to create jobs and broaden participation in growth","government enterprises were expected to lead investment in strategic, basic and heavy industries requiring large capital","certain products were reserved for production by small-scale units to protect and promote that sector"],"answer":1,"explanation":"Employment and equity through industry: industrial policy also used small-scale and dispersed production to create jobs and broaden participation in growth"}],"Moderate":[{"q":"Which concept best matches this situation? Resources are directed toward manufacturing, machinery and infrastructure.","options":["Industrial Policy Resolution 1956","Industrialisation strategy","Industrial licensing","Heavy-industry emphasis"],"answer":1,"explanation":"Industrialisation strategy: post-independence policy aimed at building a diversified industrial base and reducing structural dependence on agriculture and imports"},{"q":"Which concept best matches this situation? Strategic and heavy industries receive strong state involvement.","options":["Public-sector role in industry","Small-scale industry promotion","Industrial Policy Resolution 1956","Private-sector regulation"],"answer":2,"explanation":"Industrial Policy Resolution 1956: a major policy framework that assigned an important role to the public sector and classified industries by the extent of state responsibility"},{"q":"Which concept best matches this situation? The state invests in steel, power or heavy engineering capacity.","options":["Industrial licensing","Reservation for small-scale industries","Regional balance objective","Public-sector role in industry"],"answer":3,"explanation":"Public-sector role in industry: government enterprises were expected to lead investment in strategic, basic and heavy industries requiring large capital"},{"q":"Which concept best matches this situation? A firm needs approval before major capacity expansion.","options":["Industrial licensing","Small-scale industry promotion","Heavy-industry emphasis","Employment and equity through industry"],"answer":0,"explanation":"Industrial licensing: a regulatory system requiring government permission for establishing, expanding or changing capacity in many industries during the controlled regime"},{"q":"Which concept best matches this situation? Credit, protection or reservation supports smaller manufacturing units.","options":["Reservation for small-scale industries","Small-scale industry promotion","Private-sector regulation","Industrialisation strategy"],"answer":1,"explanation":"Small-scale industry promotion: policy support to smaller enterprises for employment, regional dispersion and more equitable industrial development"},{"q":"Which concept best matches this situation? Large firms were restricted from producing selected reserved items.","options":["Heavy-industry emphasis","Regional balance objective","Reservation for small-scale industries","Industrial Policy Resolution 1956"],"answer":2,"explanation":"Reservation for small-scale industries: certain products were reserved for production by small-scale units to protect and promote that sector"},{"q":"Which concept best matches this situation? Investment in machinery and steel supports future industrial expansion.","options":["Private-sector regulation","Employment and equity through industry","Public-sector role in industry","Heavy-industry emphasis"],"answer":3,"explanation":"Heavy-industry emphasis: the strategy gave priority to capital goods and basic industries to build long-term productive capacity"},{"q":"Which concept best matches this situation? A private manufacturer faces capacity and entry approvals.","options":["Private-sector regulation","Regional balance objective","Industrialisation strategy","Industrial licensing"],"answer":0,"explanation":"Private-sector regulation: private enterprise operated within a framework of licensing and policy controls during much of the pre-reform period"},{"q":"Which concept best matches this situation? Policy incentives encourage factories in less-developed regions.","options":["Employment and equity through industry","Regional balance objective","Industrial Policy Resolution 1956","Small-scale industry promotion"],"answer":1,"explanation":"Regional balance objective: industrial policy sought to spread industrial activity beyond already developed areas"},{"q":"Which concept best matches this situation? Labour-intensive small firms are encouraged in multiple regions.","options":["Industrialisation strategy","Public-sector role in industry","Employment and equity through industry","Reservation for small-scale industries"],"answer":2,"explanation":"Employment and equity through industry: industrial policy also used small-scale and dispersed production to create jobs and broaden participation in growth"}]}},{"id":"cbse-12-ied-ch5","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Indian Economic Development","title":"India’s Foreign Trade","chapter":"IED Chapter 5","sourceLabel":"T.R. Jain & V.K. Ohri — Indian Economic Development, Class XII (2020-21 reference edition); aligned to CBSE 2026–27 Indian Economic Development scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Foreign trade\"?","options":["exchange of goods and services between residents of different countries through exports and imports","at independence India inherited a pattern dominated by primary exports and dependence on imported manufactured or capital goods","replacing imported goods with domestically produced alternatives","temporary protection can give new domestic industries time to develop scale, skills and competitiveness"],"answer":0,"explanation":"Foreign trade: exchange of goods and services between residents of different countries through exports and imports"},{"q":"Which statement best explains \"Colonial trade legacy\"?","options":["a development approach that protects domestic production and reduces reliance on imports","at independence India inherited a pattern dominated by primary exports and dependence on imported manufactured or capital goods","use of taxes on imports to raise their domestic price and protect home producers","the commodity pattern of a country’s exports and imports"],"answer":1,"explanation":"Colonial trade legacy: at independence India inherited a pattern dominated by primary exports and dependence on imported manufactured or capital goods"},{"q":"Which statement best explains \"Inward-looking trade strategy\"?","options":["replacing imported goods with domestically produced alternatives","a quantitative limit on the amount of a good that may be imported","a development approach that protects domestic production and reduces reliance on imports","the country-wise distribution of exports and imports across trading partners"],"answer":2,"explanation":"Inward-looking trade strategy: a development approach that protects domestic production and reduces reliance on imports"},{"q":"Which statement best explains \"Import substitution\"?","options":["use of taxes on imports to raise their domestic price and protect home producers","temporary protection can give new domestic industries time to develop scale, skills and competitiveness","excessive protection can weaken competition and efficiency if domestic producers remain insulated too long","replacing imported goods with domestically produced alternatives"],"answer":3,"explanation":"Import substitution: replacing imported goods with domestically produced alternatives"},{"q":"Which statement best explains \"Tariff protection\"?","options":["use of taxes on imports to raise their domestic price and protect home producers","a quantitative limit on the amount of a good that may be imported","the commodity pattern of a country’s exports and imports","exchange of goods and services between residents of different countries through exports and imports"],"answer":0,"explanation":"Tariff protection: use of taxes on imports to raise their domestic price and protect home producers"},{"q":"Which statement best explains \"Import quota\"?","options":["temporary protection can give new domestic industries time to develop scale, skills and competitiveness","a quantitative limit on the amount of a good that may be imported","the country-wise distribution of exports and imports across trading partners","at independence India inherited a pattern dominated by primary exports and dependence on imported manufactured or capital goods"],"answer":1,"explanation":"Import quota: a quantitative limit on the amount of a good that may be imported"},{"q":"Which statement best explains \"Infant-industry argument\"?","options":["the commodity pattern of a country’s exports and imports","excessive protection can weaken competition and efficiency if domestic producers remain insulated too long","temporary protection can give new domestic industries time to develop scale, skills and competitiveness","a development approach that protects domestic production and reduces reliance on imports"],"answer":2,"explanation":"Infant-industry argument: temporary protection can give new domestic industries time to develop scale, skills and competitiveness"},{"q":"Which statement best explains \"Composition of trade\"?","options":["the country-wise distribution of exports and imports across trading partners","exchange of goods and services between residents of different countries through exports and imports","replacing imported goods with domestically produced alternatives","the commodity pattern of a country’s exports and imports"],"answer":3,"explanation":"Composition of trade: the commodity pattern of a country’s exports and imports"},{"q":"Which statement best explains \"Direction of trade\"?","options":["the country-wise distribution of exports and imports across trading partners","excessive protection can weaken competition and efficiency if domestic producers remain insulated too long","at independence India inherited a pattern dominated by primary exports and dependence on imported manufactured or capital goods","use of taxes on imports to raise their domestic price and protect home producers"],"answer":0,"explanation":"Direction of trade: the country-wise distribution of exports and imports across trading partners"},{"q":"Which statement best explains \"Trade-strategy limitation\"?","options":["exchange of goods and services between residents of different countries through exports and imports","excessive protection can weaken competition and efficiency if domestic producers remain insulated too long","a development approach that protects domestic production and reduces reliance on imports","a quantitative limit on the amount of a good that may be imported"],"answer":1,"explanation":"Trade-strategy limitation: excessive protection can weaken competition and efficiency if domestic producers remain insulated too long"}],"Moderate":[{"q":"Which concept best matches this situation? India exports a service and imports machinery.","options":["Colonial trade legacy","Foreign trade","Import substitution","Infant-industry argument"],"answer":1,"explanation":"Foreign trade: exchange of goods and services between residents of different countries through exports and imports"},{"q":"Which concept best matches this situation? Raw materials were exported while many finished products were imported.","options":["Inward-looking trade strategy","Tariff protection","Colonial trade legacy","Composition of trade"],"answer":2,"explanation":"Colonial trade legacy: at independence India inherited a pattern dominated by primary exports and dependence on imported manufactured or capital goods"},{"q":"Which concept best matches this situation? Domestic industries are sheltered while capacity is built at home.","options":["Import substitution","Import quota","Direction of trade","Inward-looking trade strategy"],"answer":3,"explanation":"Inward-looking trade strategy: a development approach that protects domestic production and reduces reliance on imports"},{"q":"Which concept best matches this situation? Domestic machinery production is developed instead of buying all machines abroad.","options":["Import substitution","Tariff protection","Infant-industry argument","Trade-strategy limitation"],"answer":0,"explanation":"Import substitution: replacing imported goods with domestically produced alternatives"},{"q":"Which concept best matches this situation? An import duty makes a foreign product more expensive relative to a local product.","options":["Import quota","Tariff protection","Composition of trade","Foreign trade"],"answer":1,"explanation":"Tariff protection: use of taxes on imports to raise their domestic price and protect home producers"},{"q":"Which concept best matches this situation? Only a fixed quantity of a product is permitted to enter the country.","options":["Infant-industry argument","Direction of trade","Import quota","Colonial trade legacy"],"answer":2,"explanation":"Import quota: a quantitative limit on the amount of a good that may be imported"},{"q":"Which concept best matches this situation? A young industry is sheltered while it learns and expands.","options":["Composition of trade","Trade-strategy limitation","Inward-looking trade strategy","Infant-industry argument"],"answer":3,"explanation":"Infant-industry argument: temporary protection can give new domestic industries time to develop scale, skills and competitiveness"},{"q":"Which concept best matches this situation? The share of manufactured exports rises while some primary exports lose relative importance.","options":["Composition of trade","Direction of trade","Foreign trade","Import substitution"],"answer":0,"explanation":"Composition of trade: the commodity pattern of a country’s exports and imports"},{"q":"Which concept best matches this situation? The share of trade with one region rises relative to another.","options":["Trade-strategy limitation","Direction of trade","Colonial trade legacy","Tariff protection"],"answer":1,"explanation":"Direction of trade: the country-wise distribution of exports and imports across trading partners"},{"q":"Which concept best matches this situation? A protected firm faces little pressure to improve quality or reduce cost.","options":["Foreign trade","Inward-looking trade strategy","Trade-strategy limitation","Import quota"],"answer":2,"explanation":"Trade-strategy limitation: excessive protection can weaken competition and efficiency if domestic producers remain insulated too long"}]}},{"id":"cbse-12-ied-ch6","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Indian Economic Development","title":"Economic Reforms Since 1991 / New Economic Policy","chapter":"IED Chapter 6","sourceLabel":"T.R. Jain & V.K. Ohri — Indian Economic Development, Class XII (2020-21 reference edition); aligned to CBSE 2026–27 Indian Economic Development scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"1991 economic crisis\"?","options":["a severe macroeconomic and external-sector stress that created pressure for major policy reform","reduction of unnecessary controls and restrictions to give economic agents greater freedom in production, investment and trade","greater integration of the domestic economy with the world through trade, investment, technology and financial flows","changes aimed at simplifying, rationalising and improving the efficiency of the tax system"],"answer":0,"explanation":"1991 economic crisis: a severe macroeconomic and external-sector stress that created pressure for major policy reform"},{"q":"Which statement best explains \"Liberalisation\"?","options":["increasing the role of private ownership or management in economic activity and reducing exclusive state ownership in selected enterprises","reduction of unnecessary controls and restrictions to give economic agents greater freedom in production, investment and trade","sale of part or all of government ownership in a public enterprise","lower trade barriers and easier foreign-investment rules used to increase international integration and competition"],"answer":1,"explanation":"Liberalisation: reduction of unnecessary controls and restrictions to give economic agents greater freedom in production, investment and trade"},{"q":"Which statement best explains \"Privatisation\"?","options":["greater integration of the domestic economy with the world through trade, investment, technology and financial flows","changes intended to make banking and financial markets more efficient, competitive and market-oriented while strengthening regulation","increasing the role of private ownership or management in economic activity and reducing exclusive state ownership in selected enterprises","an international institution providing a rules-based framework for trade among member countries"],"answer":2,"explanation":"Privatisation: increasing the role of private ownership or management in economic activity and reducing exclusive state ownership in selected enterprises"},{"q":"Which statement best explains \"Globalisation\"?","options":["sale of part or all of government ownership in a public enterprise","changes aimed at simplifying, rationalising and improving the efficiency of the tax system","economic reforms are assessed by weighing gains such as efficiency and integration against concerns such as uneven benefits, employment or sectoral stress","greater integration of the domestic economy with the world through trade, investment, technology and financial flows"],"answer":3,"explanation":"Globalisation: greater integration of the domestic economy with the world through trade, investment, technology and financial flows"},{"q":"Which statement best explains \"Disinvestment\"?","options":["sale of part or all of government ownership in a public enterprise","changes intended to make banking and financial markets more efficient, competitive and market-oriented while strengthening regulation","lower trade barriers and easier foreign-investment rules used to increase international integration and competition","a severe macroeconomic and external-sector stress that created pressure for major policy reform"],"answer":0,"explanation":"Disinvestment: sale of part or all of government ownership in a public enterprise"},{"q":"Which statement best explains \"Financial-sector reforms\"?","options":["changes aimed at simplifying, rationalising and improving the efficiency of the tax system","changes intended to make banking and financial markets more efficient, competitive and market-oriented while strengthening regulation","an international institution providing a rules-based framework for trade among member countries","reduction of unnecessary controls and restrictions to give economic agents greater freedom in production, investment and trade"],"answer":1,"explanation":"Financial-sector reforms: changes intended to make banking and financial markets more efficient, competitive and market-oriented while strengthening regulation"},{"q":"Which statement best explains \"Tax reforms\"?","options":["lower trade barriers and easier foreign-investment rules used to increase international integration and competition","economic reforms are assessed by weighing gains such as efficiency and integration against concerns such as uneven benefits, employment or sectoral stress","changes aimed at simplifying, rationalising and improving the efficiency of the tax system","increasing the role of private ownership or management in economic activity and reducing exclusive state ownership in selected enterprises"],"answer":2,"explanation":"Tax reforms: changes aimed at simplifying, rationalising and improving the efficiency of the tax system"},{"q":"Which statement best explains \"Trade and investment reforms\"?","options":["an international institution providing a rules-based framework for trade among member countries","a severe macroeconomic and external-sector stress that created pressure for major policy reform","greater integration of the domestic economy with the world through trade, investment, technology and financial flows","lower trade barriers and easier foreign-investment rules used to increase international integration and competition"],"answer":3,"explanation":"Trade and investment reforms: lower trade barriers and easier foreign-investment rules used to increase international integration and competition"},{"q":"Which statement best explains \"World Trade Organization\"?","options":["an international institution providing a rules-based framework for trade among member countries","economic reforms are assessed by weighing gains such as efficiency and integration against concerns such as uneven benefits, employment or sectoral stress","reduction of unnecessary controls and restrictions to give economic agents greater freedom in production, investment and trade","sale of part or all of government ownership in a public enterprise"],"answer":0,"explanation":"World Trade Organization: an international institution providing a rules-based framework for trade among member countries"},{"q":"Which statement best explains \"Appraisal of reforms\"?","options":["a severe macroeconomic and external-sector stress that created pressure for major policy reform","economic reforms are assessed by weighing gains such as efficiency and integration against concerns such as uneven benefits, employment or sectoral stress","increasing the role of private ownership or management in economic activity and reducing exclusive state ownership in selected enterprises","changes intended to make banking and financial markets more efficient, competitive and market-oriented while strengthening regulation"],"answer":1,"explanation":"Appraisal of reforms: economic reforms are assessed by weighing gains such as efficiency and integration against concerns such as uneven benefits, employment or sectoral stress"}],"Moderate":[{"q":"Which concept best matches this situation? Foreign-exchange and fiscal difficulties force a shift in the policy framework.","options":["Liberalisation","1991 economic crisis","Globalisation","Tax reforms"],"answer":1,"explanation":"1991 economic crisis: a severe macroeconomic and external-sector stress that created pressure for major policy reform"},{"q":"Which concept best matches this situation? Industrial licensing is reduced for many activities.","options":["Privatisation","Disinvestment","Liberalisation","Trade and investment reforms"],"answer":2,"explanation":"Liberalisation: reduction of unnecessary controls and restrictions to give economic agents greater freedom in production, investment and trade"},{"q":"Which concept best matches this situation? Government reduces its stake or opens an activity to private participation.","options":["Globalisation","Financial-sector reforms","World Trade Organization","Privatisation"],"answer":3,"explanation":"Privatisation: increasing the role of private ownership or management in economic activity and reducing exclusive state ownership in selected enterprises"},{"q":"Which concept best matches this situation? Foreign firms and domestic firms participate more deeply in international markets.","options":["Globalisation","Disinvestment","Tax reforms","Appraisal of reforms"],"answer":0,"explanation":"Globalisation: greater integration of the domestic economy with the world through trade, investment, technology and financial flows"},{"q":"Which concept best matches this situation? The government sells a portion of shares it holds in a public-sector company.","options":["Financial-sector reforms","Disinvestment","Trade and investment reforms","1991 economic crisis"],"answer":1,"explanation":"Disinvestment: sale of part or all of government ownership in a public enterprise"},{"q":"Which concept best matches this situation? Interest-rate and banking rules become more market-linked within prudential oversight.","options":["Tax reforms","World Trade Organization","Financial-sector reforms","Liberalisation"],"answer":2,"explanation":"Financial-sector reforms: changes intended to make banking and financial markets more efficient, competitive and market-oriented while strengthening regulation"},{"q":"Which concept best matches this situation? Tax structures are redesigned to broaden the base and reduce distortions.","options":["Trade and investment reforms","Appraisal of reforms","Privatisation","Tax reforms"],"answer":3,"explanation":"Tax reforms: changes aimed at simplifying, rationalising and improving the efficiency of the tax system"},{"q":"Which concept best matches this situation? Import restrictions are reduced and investment rules are liberalised.","options":["Trade and investment reforms","World Trade Organization","1991 economic crisis","Globalisation"],"answer":0,"explanation":"Trade and investment reforms: lower trade barriers and easier foreign-investment rules used to increase international integration and competition"},{"q":"Which concept best matches this situation? Members negotiate and operate under multilateral trade rules.","options":["Appraisal of reforms","World Trade Organization","Liberalisation","Disinvestment"],"answer":1,"explanation":"World Trade Organization: an international institution providing a rules-based framework for trade among member countries"},{"q":"Which concept best matches this situation? A policy may raise competition but create adjustment pressure for some producers.","options":["1991 economic crisis","Privatisation","Appraisal of reforms","Financial-sector reforms"],"answer":2,"explanation":"Appraisal of reforms: economic reforms are assessed by weighing gains such as efficiency and integration against concerns such as uneven benefits, employment or sectoral stress"}]}},{"id":"cbse-12-ied-ch7","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Indian Economic Development","title":"Poverty","chapter":"IED Chapter 7","sourceLabel":"T.R. Jain & V.K. Ohri — Indian Economic Development, Class XII (2020-21 reference edition); aligned to CBSE 2026–27 Indian Economic Development scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Poverty\"?","options":["a condition of deprivation in which people lack sufficient resources to meet basic needs and participate adequately in economic life","poverty measured against a minimum standard required to meet basic needs","a threshold used to separate people classified as poor from those classified as non-poor under a chosen methodology","weak earning capacity and limited productive assets can trap households in continuing deprivation"],"answer":0,"explanation":"Poverty: a condition of deprivation in which people lack sufficient resources to meet basic needs and participate adequately in economic life"},{"q":"Which statement best explains \"Absolute poverty\"?","options":["poverty understood in relation to the distribution and living standards of the society","poverty measured against a minimum standard required to meet basic needs","poverty affecting households in rural areas, often linked with low agricultural productivity, underemployment and weak access to assets or services","creating productive and adequately paid work can reduce poverty by raising household earning capacity"],"answer":1,"explanation":"Absolute poverty: poverty measured against a minimum standard required to meet basic needs"},{"q":"Which statement best explains \"Relative poverty\"?","options":["a threshold used to separate people classified as poor from those classified as non-poor under a chosen methodology","poverty in towns and cities often associated with insecure informal work, low wages and inadequate housing or services","poverty understood in relation to the distribution and living standards of the society","government schemes may direct employment, credit, food support or livelihood assistance toward vulnerable groups"],"answer":2,"explanation":"Relative poverty: poverty understood in relation to the distribution and living standards of the society"},{"q":"Which statement best explains \"Poverty line\"?","options":["poverty affecting households in rural areas, often linked with low agricultural productivity, underemployment and weak access to assets or services","weak earning capacity and limited productive assets can trap households in continuing deprivation","economic growth reduces poverty more effectively when its employment and income gains reach lower-income groups","a threshold used to separate people classified as poor from those classified as non-poor under a chosen methodology"],"answer":3,"explanation":"Poverty line: a threshold used to separate people classified as poor from those classified as non-poor under a chosen methodology"},{"q":"Which statement best explains \"Rural poverty\"?","options":["poverty affecting households in rural areas, often linked with low agricultural productivity, underemployment and weak access to assets or services","poverty in towns and cities often associated with insecure informal work, low wages and inadequate housing or services","creating productive and adequately paid work can reduce poverty by raising household earning capacity","a condition of deprivation in which people lack sufficient resources to meet basic needs and participate adequately in economic life"],"answer":0,"explanation":"Rural poverty: poverty affecting households in rural areas, often linked with low agricultural productivity, underemployment and weak access to assets or services"},{"q":"Which statement best explains \"Urban poverty\"?","options":["weak earning capacity and limited productive assets can trap households in continuing deprivation","poverty in towns and cities often associated with insecure informal work, low wages and inadequate housing or services","government schemes may direct employment, credit, food support or livelihood assistance toward vulnerable groups","poverty measured against a minimum standard required to meet basic needs"],"answer":1,"explanation":"Urban poverty: poverty in towns and cities often associated with insecure informal work, low wages and inadequate housing or services"},{"q":"Which statement best explains \"Low income and low asset ownership as causes\"?","options":["creating productive and adequately paid work can reduce poverty by raising household earning capacity","economic growth reduces poverty more effectively when its employment and income gains reach lower-income groups","weak earning capacity and limited productive assets can trap households in continuing deprivation","poverty understood in relation to the distribution and living standards of the society"],"answer":2,"explanation":"Low income and low asset ownership as causes: weak earning capacity and limited productive assets can trap households in continuing deprivation"},{"q":"Which statement best explains \"Employment-oriented poverty reduction\"?","options":["government schemes may direct employment, credit, food support or livelihood assistance toward vulnerable groups","a condition of deprivation in which people lack sufficient resources to meet basic needs and participate adequately in economic life","a threshold used to separate people classified as poor from those classified as non-poor under a chosen methodology","creating productive and adequately paid work can reduce poverty by raising household earning capacity"],"answer":3,"explanation":"Employment-oriented poverty reduction: creating productive and adequately paid work can reduce poverty by raising household earning capacity"},{"q":"Which statement best explains \"Targeted anti-poverty programmes\"?","options":["government schemes may direct employment, credit, food support or livelihood assistance toward vulnerable groups","economic growth reduces poverty more effectively when its employment and income gains reach lower-income groups","poverty measured against a minimum standard required to meet basic needs","poverty affecting households in rural areas, often linked with low agricultural productivity, underemployment and weak access to assets or services"],"answer":0,"explanation":"Targeted anti-poverty programmes: government schemes may direct employment, credit, food support or livelihood assistance toward vulnerable groups"},{"q":"Which statement best explains \"Growth with inclusion\"?","options":["a condition of deprivation in which people lack sufficient resources to meet basic needs and participate adequately in economic life","economic growth reduces poverty more effectively when its employment and income gains reach lower-income groups","poverty understood in relation to the distribution and living standards of the society","poverty in towns and cities often associated with insecure informal work, low wages and inadequate housing or services"],"answer":1,"explanation":"Growth with inclusion: economic growth reduces poverty more effectively when its employment and income gains reach lower-income groups"}],"Moderate":[{"q":"Which concept best matches this situation? A household cannot secure adequate food, shelter, health and education.","options":["Absolute poverty","Poverty","Poverty line","Low income and low asset ownership as causes"],"answer":1,"explanation":"Poverty: a condition of deprivation in which people lack sufficient resources to meet basic needs and participate adequately in economic life"},{"q":"Which concept best matches this situation? Income or consumption is compared with a prescribed minimum threshold.","options":["Relative poverty","Rural poverty","Absolute poverty","Employment-oriented poverty reduction"],"answer":2,"explanation":"Absolute poverty: poverty measured against a minimum standard required to meet basic needs"},{"q":"Which concept best matches this situation? A group’s resources are very low compared with prevailing social standards.","options":["Poverty line","Urban poverty","Targeted anti-poverty programmes","Relative poverty"],"answer":3,"explanation":"Relative poverty: poverty understood in relation to the distribution and living standards of the society"},{"q":"Which concept best matches this situation? Household consumption is compared with the prescribed cutoff.","options":["Poverty line","Rural poverty","Low income and low asset ownership as causes","Growth with inclusion"],"answer":0,"explanation":"Poverty line: a threshold used to separate people classified as poor from those classified as non-poor under a chosen methodology"},{"q":"Which concept best matches this situation? A landless rural worker receives irregular low-paid employment.","options":["Urban poverty","Rural poverty","Employment-oriented poverty reduction","Poverty"],"answer":1,"explanation":"Rural poverty: poverty affecting households in rural areas, often linked with low agricultural productivity, underemployment and weak access to assets or services"},{"q":"Which concept best matches this situation? A migrant household survives on irregular casual work in a city.","options":["Low income and low asset ownership as causes","Targeted anti-poverty programmes","Urban poverty","Absolute poverty"],"answer":2,"explanation":"Urban poverty: poverty in towns and cities often associated with insecure informal work, low wages and inadequate housing or services"},{"q":"Which concept best matches this situation? A household without land, skills or stable employment struggles to raise income.","options":["Employment-oriented poverty reduction","Growth with inclusion","Relative poverty","Low income and low asset ownership as causes"],"answer":3,"explanation":"Low income and low asset ownership as causes: weak earning capacity and limited productive assets can trap households in continuing deprivation"},{"q":"Which concept best matches this situation? A public employment programme provides wage income to vulnerable households.","options":["Employment-oriented poverty reduction","Targeted anti-poverty programmes","Poverty","Poverty line"],"answer":0,"explanation":"Employment-oriented poverty reduction: creating productive and adequately paid work can reduce poverty by raising household earning capacity"},{"q":"Which concept best matches this situation? A programme is designed specifically for poor rural households.","options":["Growth with inclusion","Targeted anti-poverty programmes","Absolute poverty","Rural poverty"],"answer":1,"explanation":"Targeted anti-poverty programmes: government schemes may direct employment, credit, food support or livelihood assistance toward vulnerable groups"},{"q":"Which concept best matches this situation? Output rises together with broad-based job creation and access to services.","options":["Poverty","Relative poverty","Growth with inclusion","Urban poverty"],"answer":2,"explanation":"Growth with inclusion: economic growth reduces poverty more effectively when its employment and income gains reach lower-income groups"}]}},{"id":"cbse-12-ied-ch8","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Indian Economic Development","title":"Human Capital Formation in India","chapter":"IED Chapter 8","sourceLabel":"T.R. Jain & V.K. Ohri — Indian Economic Development, Class XII (2020-21 reference edition); aligned to CBSE 2026–27 Indian Economic Development scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Human capital\"?","options":["the stock of skills, knowledge, health and productive abilities embodied in people","the process of increasing people’s productive capabilities through investment in education, health, training and related activities","better health improves the ability to learn, work consistently and remain productive","information about education, jobs and markets helps people make better investment and employment decisions"],"answer":0,"explanation":"Human capital: the stock of skills, knowledge, health and productive abilities embodied in people"},{"q":"Which statement best explains \"Human capital formation\"?","options":["education builds knowledge and skills that can raise productivity and earning capacity","the process of increasing people’s productive capabilities through investment in education, health, training and related activities","skill formation that occurs through learning and practice while working","a more skilled and healthy population can raise productivity, innovation and the economy’s capacity to grow"],"answer":1,"explanation":"Human capital formation: the process of increasing people’s productive capabilities through investment in education, health, training and related activities"},{"q":"Which statement best explains \"Education as a source of human capital\"?","options":["better health improves the ability to learn, work consistently and remain productive","people may incur migration costs to access better employment opportunities and higher future earnings","education builds knowledge and skills that can raise productivity and earning capacity","human capital views education and health partly as means to productivity, while human development treats expansion of human capabilities and well-being as an end in itself"],"answer":2,"explanation":"Education as a source of human capital: education builds knowledge and skills that can raise productivity and earning capacity"},{"q":"Which statement best explains \"Health as a source of human capital\"?","options":["skill formation that occurs through learning and practice while working","information about education, jobs and markets helps people make better investment and employment decisions","unequal access, inadequate quality, resource constraints and skill mismatches can limit the benefits of education and health investment","better health improves the ability to learn, work consistently and remain productive"],"answer":3,"explanation":"Health as a source of human capital: better health improves the ability to learn, work consistently and remain productive"},{"q":"Which statement best explains \"On-the-job training\"?","options":["skill formation that occurs through learning and practice while working","people may incur migration costs to access better employment opportunities and higher future earnings","a more skilled and healthy population can raise productivity, innovation and the economy’s capacity to grow","the stock of skills, knowledge, health and productive abilities embodied in people"],"answer":0,"explanation":"On-the-job training: skill formation that occurs through learning and practice while working"},{"q":"Which statement best explains \"Migration as investment in human capital\"?","options":["information about education, jobs and markets helps people make better investment and employment decisions","people may incur migration costs to access better employment opportunities and higher future earnings","human capital views education and health partly as means to productivity, while human development treats expansion of human capabilities and well-being as an end in itself","the process of increasing people’s productive capabilities through investment in education, health, training and related activities"],"answer":1,"explanation":"Migration as investment in human capital: people may incur migration costs to access better employment opportunities and higher future earnings"},{"q":"Which statement best explains \"Information as a human-capital input\"?","options":["a more skilled and healthy population can raise productivity, innovation and the economy’s capacity to grow","unequal access, inadequate quality, resource constraints and skill mismatches can limit the benefits of education and health investment","information about education, jobs and markets helps people make better investment and employment decisions","education builds knowledge and skills that can raise productivity and earning capacity"],"answer":2,"explanation":"Information as a human-capital input: information about education, jobs and markets helps people make better investment and employment decisions"},{"q":"Which statement best explains \"Human capital and economic growth\"?","options":["human capital views education and health partly as means to productivity, while human development treats expansion of human capabilities and well-being as an end in itself","the stock of skills, knowledge, health and productive abilities embodied in people","better health improves the ability to learn, work consistently and remain productive","a more skilled and healthy population can raise productivity, innovation and the economy’s capacity to grow"],"answer":3,"explanation":"Human capital and economic growth: a more skilled and healthy population can raise productivity, innovation and the economy’s capacity to grow"},{"q":"Which statement best explains \"Human capital versus human development\"?","options":["human capital views education and health partly as means to productivity, while human development treats expansion of human capabilities and well-being as an end in itself","unequal access, inadequate quality, resource constraints and skill mismatches can limit the benefits of education and health investment","the process of increasing people’s productive capabilities through investment in education, health, training and related activities","skill formation that occurs through learning and practice while working"],"answer":0,"explanation":"Human capital versus human development: human capital views education and health partly as means to productivity, while human development treats expansion of human capabilities and well-being as an end in itself"},{"q":"Which statement best explains \"Human-capital formation challenge\"?","options":["the stock of skills, knowledge, health and productive abilities embodied in people","unequal access, inadequate quality, resource constraints and skill mismatches can limit the benefits of education and health investment","education builds knowledge and skills that can raise productivity and earning capacity","people may incur migration costs to access better employment opportunities and higher future earnings"],"answer":1,"explanation":"Human-capital formation challenge: unequal access, inadequate quality, resource constraints and skill mismatches can limit the benefits of education and health investment"}],"Moderate":[{"q":"Which concept best matches this situation? Education and health improve a worker’s productive capability.","options":["Human capital formation","Human capital","Health as a source of human capital","Information as a human-capital input"],"answer":1,"explanation":"Human capital: the stock of skills, knowledge, health and productive abilities embodied in people"},{"q":"Which concept best matches this situation? A country expands schooling and worker training.","options":["Education as a source of human capital","On-the-job training","Human capital formation","Human capital and economic growth"],"answer":2,"explanation":"Human capital formation: the process of increasing people’s productive capabilities through investment in education, health, training and related activities"},{"q":"Which concept best matches this situation? Technical education improves a worker’s ability to perform specialised tasks.","options":["Health as a source of human capital","Migration as investment in human capital","Human capital versus human development","Education as a source of human capital"],"answer":3,"explanation":"Education as a source of human capital: education builds knowledge and skills that can raise productivity and earning capacity"},{"q":"Which concept best matches this situation? Preventive healthcare reduces illness-related work loss.","options":["Health as a source of human capital","On-the-job training","Information as a human-capital input","Human-capital formation challenge"],"answer":0,"explanation":"Health as a source of human capital: better health improves the ability to learn, work consistently and remain productive"},{"q":"Which concept best matches this situation? A new employee learns to operate specialised equipment under supervision.","options":["Migration as investment in human capital","On-the-job training","Human capital and economic growth","Human capital"],"answer":1,"explanation":"On-the-job training: skill formation that occurs through learning and practice while working"},{"q":"Which concept best matches this situation? A trained worker moves to a city where specialised jobs are available.","options":["Information as a human-capital input","Human capital versus human development","Migration as investment in human capital","Human capital formation"],"answer":2,"explanation":"Migration as investment in human capital: people may incur migration costs to access better employment opportunities and higher future earnings"},{"q":"Which concept best matches this situation? A student compares training options and labour-market prospects before choosing a course.","options":["Human capital and economic growth","Human-capital formation challenge","Education as a source of human capital","Information as a human-capital input"],"answer":3,"explanation":"Information as a human-capital input: information about education, jobs and markets helps people make better investment and employment decisions"},{"q":"Which concept best matches this situation? Better-trained workers adopt and improve technology more effectively.","options":["Human capital and economic growth","Human capital versus human development","Human capital","Health as a source of human capital"],"answer":0,"explanation":"Human capital and economic growth: a more skilled and healthy population can raise productivity, innovation and the economy’s capacity to grow"},{"q":"Which concept best matches this situation? Education is valued both for higher productivity and for expanding personal capabilities.","options":["Human-capital formation challenge","Human capital versus human development","Human capital formation","On-the-job training"],"answer":1,"explanation":"Human capital versus human development: human capital views education and health partly as means to productivity, while human development treats expansion of human capabilities and well-being as an end in itself"},{"q":"Which concept best matches this situation? School enrolment rises but learning quality remains weak.","options":["Human capital","Education as a source of human capital","Human-capital formation challenge","Migration as investment in human capital"],"answer":2,"explanation":"Human-capital formation challenge: unequal access, inadequate quality, resource constraints and skill mismatches can limit the benefits of education and health investment"}]}},{"id":"cbse-12-ied-ch9","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Indian Economic Development","title":"Rural Development","chapter":"IED Chapter 9","sourceLabel":"T.R. Jain & V.K. Ohri — Indian Economic Development, Class XII (2020-21 reference edition); aligned to CBSE 2026–27 Indian Economic Development scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Rural development\"?","options":["a broad process of improving livelihoods, productivity, infrastructure, services and quality of life in rural areas","finance needed by rural households and producers for production, investment and livelihood activities","credit supplied through member-based cooperative institutions that pool local participation and financial services","shifting part of rural activity toward varied crops, allied activities or non-farm work to reduce risk and raise income opportunities"],"answer":0,"explanation":"Rural development: a broad process of improving livelihoods, productivity, infrastructure, services and quality of life in rural areas"},{"q":"Which statement best explains \"Rural credit\"?","options":["a development financial institution with a major role in supporting and refinancing rural and agricultural credit","finance needed by rural households and producers for production, investment and livelihood activities","small groups mobilise savings and facilitate access to modest loans, especially for households poorly served by formal finance","activities such as dairy, poultry, fisheries and horticulture that complement or supplement crop income"],"answer":1,"explanation":"Rural credit: finance needed by rural households and producers for production, investment and livelihood activities"},{"q":"Which statement best explains \"NABARD\"?","options":["credit supplied through member-based cooperative institutions that pool local participation and financial services","the system of assembling, grading, storage, transport and sale of farm products from producers to buyers","a development financial institution with a major role in supporting and refinancing rural and agricultural credit","farming that avoids or minimises synthetic chemical inputs and relies more on ecological and biological methods"],"answer":2,"explanation":"NABARD: a development financial institution with a major role in supporting and refinancing rural and agricultural credit"},{"q":"Which statement best explains \"Cooperative credit\"?","options":["small groups mobilise savings and facilitate access to modest loans, especially for households poorly served by formal finance","shifting part of rural activity toward varied crops, allied activities or non-farm work to reduce risk and raise income opportunities","income-generating work outside crop cultivation that can reduce excessive dependence on agriculture","credit supplied through member-based cooperative institutions that pool local participation and financial services"],"answer":3,"explanation":"Cooperative credit: credit supplied through member-based cooperative institutions that pool local participation and financial services"},{"q":"Which statement best explains \"Self-help groups and microcredit\"?","options":["small groups mobilise savings and facilitate access to modest loans, especially for households poorly served by formal finance","the system of assembling, grading, storage, transport and sale of farm products from producers to buyers","activities such as dairy, poultry, fisheries and horticulture that complement or supplement crop income","a broad process of improving livelihoods, productivity, infrastructure, services and quality of life in rural areas"],"answer":0,"explanation":"Self-help groups and microcredit: small groups mobilise savings and facilitate access to modest loans, especially for households poorly served by formal finance"},{"q":"Which statement best explains \"Agricultural marketing\"?","options":["shifting part of rural activity toward varied crops, allied activities or non-farm work to reduce risk and raise income opportunities","the system of assembling, grading, storage, transport and sale of farm products from producers to buyers","farming that avoids or minimises synthetic chemical inputs and relies more on ecological and biological methods","finance needed by rural households and producers for production, investment and livelihood activities"],"answer":1,"explanation":"Agricultural marketing: the system of assembling, grading, storage, transport and sale of farm products from producers to buyers"},{"q":"Which statement best explains \"Agricultural diversification\"?","options":["activities such as dairy, poultry, fisheries and horticulture that complement or supplement crop income","income-generating work outside crop cultivation that can reduce excessive dependence on agriculture","shifting part of rural activity toward varied crops, allied activities or non-farm work to reduce risk and raise income opportunities","a development financial institution with a major role in supporting and refinancing rural and agricultural credit"],"answer":2,"explanation":"Agricultural diversification: shifting part of rural activity toward varied crops, allied activities or non-farm work to reduce risk and raise income opportunities"},{"q":"Which statement best explains \"Allied rural activities\"?","options":["farming that avoids or minimises synthetic chemical inputs and relies more on ecological and biological methods","a broad process of improving livelihoods, productivity, infrastructure, services and quality of life in rural areas","credit supplied through member-based cooperative institutions that pool local participation and financial services","activities such as dairy, poultry, fisheries and horticulture that complement or supplement crop income"],"answer":3,"explanation":"Allied rural activities: activities such as dairy, poultry, fisheries and horticulture that complement or supplement crop income"},{"q":"Which statement best explains \"Organic farming\"?","options":["farming that avoids or minimises synthetic chemical inputs and relies more on ecological and biological methods","income-generating work outside crop cultivation that can reduce excessive dependence on agriculture","finance needed by rural households and producers for production, investment and livelihood activities","small groups mobilise savings and facilitate access to modest loans, especially for households poorly served by formal finance"],"answer":0,"explanation":"Organic farming: farming that avoids or minimises synthetic chemical inputs and relies more on ecological and biological methods"},{"q":"Which statement best explains \"Rural non-farm employment\"?","options":["a broad process of improving livelihoods, productivity, infrastructure, services and quality of life in rural areas","income-generating work outside crop cultivation that can reduce excessive dependence on agriculture","a development financial institution with a major role in supporting and refinancing rural and agricultural credit","the system of assembling, grading, storage, transport and sale of farm products from producers to buyers"],"answer":1,"explanation":"Rural non-farm employment: income-generating work outside crop cultivation that can reduce excessive dependence on agriculture"}],"Moderate":[{"q":"Which concept best matches this situation? Credit, roads, education, farm productivity and non-farm employment improve together.","options":["Rural credit","Rural development","Cooperative credit","Agricultural diversification"],"answer":1,"explanation":"Rural development: a broad process of improving livelihoods, productivity, infrastructure, services and quality of life in rural areas"},{"q":"Which concept best matches this situation? A farmer borrows before sowing to purchase seeds and inputs.","options":["NABARD","Self-help groups and microcredit","Rural credit","Allied rural activities"],"answer":2,"explanation":"Rural credit: finance needed by rural households and producers for production, investment and livelihood activities"},{"q":"Which concept best matches this situation? It supports the institutional credit system serving agriculture and rural development.","options":["Cooperative credit","Agricultural marketing","Organic farming","NABARD"],"answer":3,"explanation":"NABARD: a development financial institution with a major role in supporting and refinancing rural and agricultural credit"},{"q":"Which concept best matches this situation? Farmers access finance through a cooperative credit society.","options":["Cooperative credit","Self-help groups and microcredit","Agricultural diversification","Rural non-farm employment"],"answer":0,"explanation":"Cooperative credit: credit supplied through member-based cooperative institutions that pool local participation and financial services"},{"q":"Which concept best matches this situation? Members save regularly and obtain small group-linked loans.","options":["Agricultural marketing","Self-help groups and microcredit","Allied rural activities","Rural development"],"answer":1,"explanation":"Self-help groups and microcredit: small groups mobilise savings and facilitate access to modest loans, especially for households poorly served by formal finance"},{"q":"Which concept best matches this situation? Better storage lets farmers avoid distress sale immediately after harvest.","options":["Agricultural diversification","Organic farming","Agricultural marketing","Rural credit"],"answer":2,"explanation":"Agricultural marketing: the system of assembling, grading, storage, transport and sale of farm products from producers to buyers"},{"q":"Which concept best matches this situation? A household combines crop farming with dairy and horticulture.","options":["Allied rural activities","Rural non-farm employment","NABARD","Agricultural diversification"],"answer":3,"explanation":"Agricultural diversification: shifting part of rural activity toward varied crops, allied activities or non-farm work to reduce risk and raise income opportunities"},{"q":"Which concept best matches this situation? A farmer earns additional income through milk production.","options":["Allied rural activities","Organic farming","Rural development","Cooperative credit"],"answer":0,"explanation":"Allied rural activities: activities such as dairy, poultry, fisheries and horticulture that complement or supplement crop income"},{"q":"Which concept best matches this situation? Farmers use organic manure and biological pest management.","options":["Rural non-farm employment","Organic farming","Rural credit","Self-help groups and microcredit"],"answer":1,"explanation":"Organic farming: farming that avoids or minimises synthetic chemical inputs and relies more on ecological and biological methods"},{"q":"Which concept best matches this situation? A rural household earns from food processing, repair services or local manufacturing.","options":["Rural development","NABARD","Rural non-farm employment","Agricultural marketing"],"answer":2,"explanation":"Rural non-farm employment: income-generating work outside crop cultivation that can reduce excessive dependence on agriculture"}]}},{"id":"cbse-12-ied-ch10","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Indian Economic Development","title":"Employment and Unemployment","chapter":"IED Chapter 10","sourceLabel":"T.R. Jain & V.K. Ohri — Indian Economic Development, Class XII (2020-21 reference edition); aligned to CBSE 2026–27 Indian Economic Development scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Worker\"?","options":["a person engaged in an economic activity that contributes to production of goods or services","the total number of persons actually engaged in productive economic activity","a worker operating own account or family enterprise rather than working for a separate employer for wages or salary","a situation where output grows without a proportionate increase in employment opportunities"],"answer":0,"explanation":"Worker: a person engaged in an economic activity that contributes to production of goods or services"},{"q":"Which statement best explains \"Workforce\"?","options":["the proportion of the population that is actually working","the total number of persons actually engaged in productive economic activity","a hired worker receiving wages or salary on a regular basis under an employment arrangement","a rising share or significance of casual employment relative to more secure forms of work"],"answer":1,"explanation":"Workforce: the total number of persons actually engaged in productive economic activity"},{"q":"Which statement best explains \"Workforce participation rate\"?","options":["a worker operating own account or family enterprise rather than working for a separate employer for wages or salary","a hired worker engaged on a casual or short-term basis and paid according to work or time without regular job security","the proportion of the population that is actually working","a growing share of workers operating without the security and formal protections associated with organised employment"],"answer":2,"explanation":"Workforce participation rate: the proportion of the population that is actually working"},{"q":"Which statement best explains \"Self-employed worker\"?","options":["a hired worker receiving wages or salary on a regular basis under an employment arrangement","a situation where output grows without a proportionate increase in employment opportunities","a situation where more workers are engaged than necessary so the marginal contribution of some workers is approximately zero","a worker operating own account or family enterprise rather than working for a separate employer for wages or salary"],"answer":3,"explanation":"Self-employed worker: a worker operating own account or family enterprise rather than working for a separate employer for wages or salary"},{"q":"Which statement best explains \"Regular salaried employee\"?","options":["a hired worker receiving wages or salary on a regular basis under an employment arrangement","a hired worker engaged on a casual or short-term basis and paid according to work or time without regular job security","a rising share or significance of casual employment relative to more secure forms of work","a person engaged in an economic activity that contributes to production of goods or services"],"answer":0,"explanation":"Regular salaried employee: a hired worker receiving wages or salary on a regular basis under an employment arrangement"},{"q":"Which statement best explains \"Casual wage worker\"?","options":["a situation where output grows without a proportionate increase in employment opportunities","a hired worker engaged on a casual or short-term basis and paid according to work or time without regular job security","a growing share of workers operating without the security and formal protections associated with organised employment","the total number of persons actually engaged in productive economic activity"],"answer":1,"explanation":"Casual wage worker: a hired worker engaged on a casual or short-term basis and paid according to work or time without regular job security"},{"q":"Which statement best explains \"Jobless growth\"?","options":["a rising share or significance of casual employment relative to more secure forms of work","a situation where more workers are engaged than necessary so the marginal contribution of some workers is approximately zero","a situation where output grows without a proportionate increase in employment opportunities","the proportion of the population that is actually working"],"answer":2,"explanation":"Jobless growth: a situation where output grows without a proportionate increase in employment opportunities"},{"q":"Which statement best explains \"Casualisation of workforce\"?","options":["a growing share of workers operating without the security and formal protections associated with organised employment","a person engaged in an economic activity that contributes to production of goods or services","a worker operating own account or family enterprise rather than working for a separate employer for wages or salary","a rising share or significance of casual employment relative to more secure forms of work"],"answer":3,"explanation":"Casualisation of workforce: a rising share or significance of casual employment relative to more secure forms of work"},{"q":"Which statement best explains \"Informalisation of workforce\"?","options":["a growing share of workers operating without the security and formal protections associated with organised employment","a situation where more workers are engaged than necessary so the marginal contribution of some workers is approximately zero","the total number of persons actually engaged in productive economic activity","a hired worker receiving wages or salary on a regular basis under an employment arrangement"],"answer":0,"explanation":"Informalisation of workforce: a growing share of workers operating without the security and formal protections associated with organised employment"},{"q":"Which statement best explains \"Disguised unemployment\"?","options":["a person engaged in an economic activity that contributes to production of goods or services","a situation where more workers are engaged than necessary so the marginal contribution of some workers is approximately zero","the proportion of the population that is actually working","a hired worker engaged on a casual or short-term basis and paid according to work or time without regular job security"],"answer":1,"explanation":"Disguised unemployment: a situation where more workers are engaged than necessary so the marginal contribution of some workers is approximately zero"}],"Moderate":[{"q":"Which concept best matches this situation? A farmer, factory employee or self-employed shopkeeper contributes to production.","options":["Workforce","Worker","Self-employed worker","Jobless growth"],"answer":1,"explanation":"Worker: a person engaged in an economic activity that contributes to production of goods or services"},{"q":"Which concept best matches this situation? All employed persons in the economy are counted in the workforce.","options":["Workforce participation rate","Regular salaried employee","Workforce","Casualisation of workforce"],"answer":2,"explanation":"Workforce: the total number of persons actually engaged in productive economic activity"},{"q":"Which concept best matches this situation? Workforce is compared with total population to measure participation.","options":["Self-employed worker","Casual wage worker","Informalisation of workforce","Workforce participation rate"],"answer":3,"explanation":"Workforce participation rate: the proportion of the population that is actually working"},{"q":"Which concept best matches this situation? A person runs her own small shop.","options":["Self-employed worker","Regular salaried employee","Jobless growth","Disguised unemployment"],"answer":0,"explanation":"Self-employed worker: a worker operating own account or family enterprise rather than working for a separate employer for wages or salary"},{"q":"Which concept best matches this situation? An office employee receives a monthly salary.","options":["Casual wage worker","Regular salaried employee","Casualisation of workforce","Worker"],"answer":1,"explanation":"Regular salaried employee: a hired worker receiving wages or salary on a regular basis under an employment arrangement"},{"q":"Which concept best matches this situation? A construction worker is hired for a few days.","options":["Jobless growth","Informalisation of workforce","Casual wage worker","Workforce"],"answer":2,"explanation":"Casual wage worker: a hired worker engaged on a casual or short-term basis and paid according to work or time without regular job security"},{"q":"Which concept best matches this situation? GDP rises strongly while employment grows very slowly.","options":["Casualisation of workforce","Disguised unemployment","Workforce participation rate","Jobless growth"],"answer":3,"explanation":"Jobless growth: a situation where output grows without a proportionate increase in employment opportunities"},{"q":"Which concept best matches this situation? Firms rely increasingly on short-term casual workers.","options":["Casualisation of workforce","Informalisation of workforce","Worker","Self-employed worker"],"answer":0,"explanation":"Casualisation of workforce: a rising share or significance of casual employment relative to more secure forms of work"},{"q":"Which concept best matches this situation? More workers lack formal contracts or social-security benefits.","options":["Disguised unemployment","Informalisation of workforce","Workforce","Regular salaried employee"],"answer":1,"explanation":"Informalisation of workforce: a growing share of workers operating without the security and formal protections associated with organised employment"},{"q":"Which concept best matches this situation? Several family members work on a small farm even though output would not fall if some left.","options":["Worker","Workforce participation rate","Disguised unemployment","Casual wage worker"],"answer":2,"explanation":"Disguised unemployment: a situation where more workers are engaged than necessary so the marginal contribution of some workers is approximately zero"}]}},{"id":"cbse-12-ied-ch11","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Indian Economic Development","title":"Infrastructure","chapter":"IED Chapter 11","sourceLabel":"T.R. Jain & V.K. Ohri — Indian Economic Development, Class XII (2020-21 reference edition); aligned to CBSE 2026–27 Indian Economic Development scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Infrastructure\"?","options":["basic support systems and services that enable production, exchange and human development","support systems directly facilitating production and exchange such as energy, transport and communication","economic and social infrastructure reinforce each other in supporting sustainable growth and development","traditional energy sources often collected and used without regular market transactions, such as fuelwood or agricultural waste in some settings"],"answer":0,"explanation":"Infrastructure: basic support systems and services that enable production, exchange and human development"},{"q":"Which statement best explains \"Economic infrastructure\"?","options":["services and institutions such as health and education that develop human capabilities and social welfare","support systems directly facilitating production and exchange such as energy, transport and communication","systems that generate, transmit and supply energy needed by households and productive sectors","institutions, personnel and facilities that provide preventive and curative healthcare"],"answer":1,"explanation":"Economic infrastructure: support systems directly facilitating production and exchange such as energy, transport and communication"},{"q":"Which statement best explains \"Social infrastructure\"?","options":["economic and social infrastructure reinforce each other in supporting sustainable growth and development","energy sources bought and sold in markets such as coal, petroleum products and electricity","services and institutions such as health and education that develop human capabilities and social welfare","inadequate capacity or quality in support systems that restricts production, access or welfare"],"answer":2,"explanation":"Social infrastructure: services and institutions such as health and education that develop human capabilities and social welfare"},{"q":"Which statement best explains \"Complementarity of infrastructure\"?","options":["systems that generate, transmit and supply energy needed by households and productive sectors","traditional energy sources often collected and used without regular market transactions, such as fuelwood or agricultural waste in some settings","large external benefits, high capital needs and universal-access concerns often justify significant public involvement","economic and social infrastructure reinforce each other in supporting sustainable growth and development"],"answer":3,"explanation":"Complementarity of infrastructure: economic and social infrastructure reinforce each other in supporting sustainable growth and development"},{"q":"Which statement best explains \"Energy infrastructure\"?","options":["systems that generate, transmit and supply energy needed by households and productive sectors","energy sources bought and sold in markets such as coal, petroleum products and electricity","institutions, personnel and facilities that provide preventive and curative healthcare","basic support systems and services that enable production, exchange and human development"],"answer":0,"explanation":"Energy infrastructure: systems that generate, transmit and supply energy needed by households and productive sectors"},{"q":"Which statement best explains \"Commercial energy\"?","options":["traditional energy sources often collected and used without regular market transactions, such as fuelwood or agricultural waste in some settings","energy sources bought and sold in markets such as coal, petroleum products and electricity","inadequate capacity or quality in support systems that restricts production, access or welfare","support systems directly facilitating production and exchange such as energy, transport and communication"],"answer":1,"explanation":"Commercial energy: energy sources bought and sold in markets such as coal, petroleum products and electricity"},{"q":"Which statement best explains \"Non-commercial energy\"?","options":["institutions, personnel and facilities that provide preventive and curative healthcare","large external benefits, high capital needs and universal-access concerns often justify significant public involvement","traditional energy sources often collected and used without regular market transactions, such as fuelwood or agricultural waste in some settings","services and institutions such as health and education that develop human capabilities and social welfare"],"answer":2,"explanation":"Non-commercial energy: traditional energy sources often collected and used without regular market transactions, such as fuelwood or agricultural waste in some settings"},{"q":"Which statement best explains \"Health infrastructure\"?","options":["inadequate capacity or quality in support systems that restricts production, access or welfare","basic support systems and services that enable production, exchange and human development","economic and social infrastructure reinforce each other in supporting sustainable growth and development","institutions, personnel and facilities that provide preventive and curative healthcare"],"answer":3,"explanation":"Health infrastructure: institutions, personnel and facilities that provide preventive and curative healthcare"},{"q":"Which statement best explains \"Infrastructure bottleneck\"?","options":["inadequate capacity or quality in support systems that restricts production, access or welfare","large external benefits, high capital needs and universal-access concerns often justify significant public involvement","support systems directly facilitating production and exchange such as energy, transport and communication","systems that generate, transmit and supply energy needed by households and productive sectors"],"answer":0,"explanation":"Infrastructure bottleneck: inadequate capacity or quality in support systems that restricts production, access or welfare"},{"q":"Which statement best explains \"Public role in infrastructure\"?","options":["basic support systems and services that enable production, exchange and human development","large external benefits, high capital needs and universal-access concerns often justify significant public involvement","services and institutions such as health and education that develop human capabilities and social welfare","energy sources bought and sold in markets such as coal, petroleum products and electricity"],"answer":1,"explanation":"Public role in infrastructure: large external benefits, high capital needs and universal-access concerns often justify significant public involvement"}],"Moderate":[{"q":"Which concept best matches this situation? Energy, transport, communication, health and education support wider economic activity.","options":["Economic infrastructure","Infrastructure","Complementarity of infrastructure","Non-commercial energy"],"answer":1,"explanation":"Infrastructure: basic support systems and services that enable production, exchange and human development"},{"q":"Which concept best matches this situation? Reliable electricity and roads reduce production and logistics constraints.","options":["Social infrastructure","Energy infrastructure","Economic infrastructure","Health infrastructure"],"answer":2,"explanation":"Economic infrastructure: support systems directly facilitating production and exchange such as energy, transport and communication"},{"q":"Which concept best matches this situation? Hospitals improve health and productive capacity.","options":["Complementarity of infrastructure","Commercial energy","Infrastructure bottleneck","Social infrastructure"],"answer":3,"explanation":"Social infrastructure: services and institutions such as health and education that develop human capabilities and social welfare"},{"q":"Which concept best matches this situation? Roads improve access to schools and hospitals while healthier workers use productive infrastructure better.","options":["Complementarity of infrastructure","Energy infrastructure","Non-commercial energy","Public role in infrastructure"],"answer":0,"explanation":"Complementarity of infrastructure: economic and social infrastructure reinforce each other in supporting sustainable growth and development"},{"q":"Which concept best matches this situation? Electricity generation and transmission support factories and homes.","options":["Commercial energy","Energy infrastructure","Health infrastructure","Infrastructure"],"answer":1,"explanation":"Energy infrastructure: systems that generate, transmit and supply energy needed by households and productive sectors"},{"q":"Which concept best matches this situation? A factory purchases electricity from the grid.","options":["Non-commercial energy","Infrastructure bottleneck","Commercial energy","Economic infrastructure"],"answer":2,"explanation":"Commercial energy: energy sources bought and sold in markets such as coal, petroleum products and electricity"},{"q":"Which concept best matches this situation? A rural household collects biomass for cooking.","options":["Health infrastructure","Public role in infrastructure","Social infrastructure","Non-commercial energy"],"answer":3,"explanation":"Non-commercial energy: traditional energy sources often collected and used without regular market transactions, such as fuelwood or agricultural waste in some settings"},{"q":"Which concept best matches this situation? Primary health centres, hospitals and trained health workers serve the population.","options":["Health infrastructure","Infrastructure bottleneck","Infrastructure","Complementarity of infrastructure"],"answer":0,"explanation":"Health infrastructure: institutions, personnel and facilities that provide preventive and curative healthcare"},{"q":"Which concept best matches this situation? Unreliable electricity interrupts factory output.","options":["Public role in infrastructure","Infrastructure bottleneck","Economic infrastructure","Energy infrastructure"],"answer":1,"explanation":"Infrastructure bottleneck: inadequate capacity or quality in support systems that restricts production, access or welfare"},{"q":"Which concept best matches this situation? Government invests in roads, public health or rural electrification.","options":["Infrastructure","Social infrastructure","Public role in infrastructure","Commercial energy"],"answer":2,"explanation":"Public role in infrastructure: large external benefits, high capital needs and universal-access concerns often justify significant public involvement"}]}},{"id":"cbse-12-ied-ch12","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Indian Economic Development","title":"Environment and Sustainable Development","chapter":"IED Chapter 12","sourceLabel":"T.R. Jain & V.K. Ohri — Indian Economic Development, Class XII (2020-21 reference edition); aligned to CBSE 2026–27 Indian Economic Development scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"Environment\"?","options":["the biotic and abiotic surroundings and natural systems that affect life and economic activity","the environment provides natural resources used as inputs in production","the environment absorbs and processes wastes up to its assimilative capacity","deterioration in environmental quality through pollution, resource depletion or ecosystem damage"],"answer":0,"explanation":"Environment: the biotic and abiotic surroundings and natural systems that affect life and economic activity"},{"q":"Which statement best explains \"Resource-supply function of environment\"?","options":["natural systems provide conditions such as air, water and ecological balance necessary for life","the environment provides natural resources used as inputs in production","a natural resource that can regenerate or be replenished when use remains within sustainable limits","the ability of the environment to sustain resource use and absorb waste without unacceptable long-run damage"],"answer":1,"explanation":"Resource-supply function of environment: the environment provides natural resources used as inputs in production"},{"q":"Which statement best explains \"Life-support function of environment\"?","options":["the environment absorbs and processes wastes up to its assimilative capacity","a resource with a fixed or extremely slow-forming stock that is depleted through extraction","natural systems provide conditions such as air, water and ecological balance necessary for life","development that meets present needs while protecting the ability of future generations to meet their needs"],"answer":2,"explanation":"Life-support function of environment: natural systems provide conditions such as air, water and ecological balance necessary for life"},{"q":"Which statement best explains \"Waste-assimilation function\"?","options":["a natural resource that can regenerate or be replenished when use remains within sustainable limits","deterioration in environmental quality through pollution, resource depletion or ecosystem damage","policies such as renewable energy, organic farming, efficient waste management, public transport and conservation reduce environmental pressure while supporting development","the environment absorbs and processes wastes up to its assimilative capacity"],"answer":3,"explanation":"Waste-assimilation function: the environment absorbs and processes wastes up to its assimilative capacity"},{"q":"Which statement best explains \"Renewable resource\"?","options":["a natural resource that can regenerate or be replenished when use remains within sustainable limits","a resource with a fixed or extremely slow-forming stock that is depleted through extraction","the ability of the environment to sustain resource use and absorb waste without unacceptable long-run damage","the biotic and abiotic surroundings and natural systems that affect life and economic activity"],"answer":0,"explanation":"Renewable resource: a natural resource that can regenerate or be replenished when use remains within sustainable limits"},{"q":"Which statement best explains \"Non-renewable resource\"?","options":["deterioration in environmental quality through pollution, resource depletion or ecosystem damage","a resource with a fixed or extremely slow-forming stock that is depleted through extraction","development that meets present needs while protecting the ability of future generations to meet their needs","the environment provides natural resources used as inputs in production"],"answer":1,"explanation":"Non-renewable resource: a resource with a fixed or extremely slow-forming stock that is depleted through extraction"},{"q":"Which statement best explains \"Environmental degradation\"?","options":["the ability of the environment to sustain resource use and absorb waste without unacceptable long-run damage","policies such as renewable energy, organic farming, efficient waste management, public transport and conservation reduce environmental pressure while supporting development","deterioration in environmental quality through pollution, resource depletion or ecosystem damage","natural systems provide conditions such as air, water and ecological balance necessary for life"],"answer":2,"explanation":"Environmental degradation: deterioration in environmental quality through pollution, resource depletion or ecosystem damage"},{"q":"Which statement best explains \"Carrying capacity\"?","options":["development that meets present needs while protecting the ability of future generations to meet their needs","the biotic and abiotic surroundings and natural systems that affect life and economic activity","the environment absorbs and processes wastes up to its assimilative capacity","the ability of the environment to sustain resource use and absorb waste without unacceptable long-run damage"],"answer":3,"explanation":"Carrying capacity: the ability of the environment to sustain resource use and absorb waste without unacceptable long-run damage"},{"q":"Which statement best explains \"Sustainable development\"?","options":["development that meets present needs while protecting the ability of future generations to meet their needs","policies such as renewable energy, organic farming, efficient waste management, public transport and conservation reduce environmental pressure while supporting development","the environment provides natural resources used as inputs in production","a natural resource that can regenerate or be replenished when use remains within sustainable limits"],"answer":0,"explanation":"Sustainable development: development that meets present needs while protecting the ability of future generations to meet their needs"},{"q":"Which statement best explains \"Sustainable-development strategy\"?","options":["the biotic and abiotic surroundings and natural systems that affect life and economic activity","policies such as renewable energy, organic farming, efficient waste management, public transport and conservation reduce environmental pressure while supporting development","natural systems provide conditions such as air, water and ecological balance necessary for life","a resource with a fixed or extremely slow-forming stock that is depleted through extraction"],"answer":1,"explanation":"Sustainable-development strategy: policies such as renewable energy, organic farming, efficient waste management, public transport and conservation reduce environmental pressure while supporting development"}],"Moderate":[{"q":"Which concept best matches this situation? Air, water, soil, plants and animals together form the environment.","options":["Resource-supply function of environment","Environment","Waste-assimilation function","Environmental degradation"],"answer":1,"explanation":"Environment: the biotic and abiotic surroundings and natural systems that affect life and economic activity"},{"q":"Which concept best matches this situation? Minerals, water and timber support production processes.","options":["Life-support function of environment","Renewable resource","Resource-supply function of environment","Carrying capacity"],"answer":2,"explanation":"Resource-supply function of environment: the environment provides natural resources used as inputs in production"},{"q":"Which concept best matches this situation? Clean air and water are essential for human survival.","options":["Waste-assimilation function","Non-renewable resource","Sustainable development","Life-support function of environment"],"answer":3,"explanation":"Life-support function of environment: natural systems provide conditions such as air, water and ecological balance necessary for life"},{"q":"Which concept best matches this situation? Natural systems can break down some waste when the burden is not excessive.","options":["Waste-assimilation function","Renewable resource","Environmental degradation","Sustainable-development strategy"],"answer":0,"explanation":"Waste-assimilation function: the environment absorbs and processes wastes up to its assimilative capacity"},{"q":"Which concept best matches this situation? A well-managed forest can regrow over time.","options":["Non-renewable resource","Renewable resource","Carrying capacity","Environment"],"answer":1,"explanation":"Renewable resource: a natural resource that can regenerate or be replenished when use remains within sustainable limits"},{"q":"Which concept best matches this situation? Fossil-fuel reserves decline when extracted and burned.","options":["Environmental degradation","Sustainable development","Non-renewable resource","Resource-supply function of environment"],"answer":2,"explanation":"Non-renewable resource: a resource with a fixed or extremely slow-forming stock that is depleted through extraction"},{"q":"Which concept best matches this situation? Excessive groundwater extraction lowers the water table while pollutants reduce water quality.","options":["Carrying capacity","Sustainable-development strategy","Life-support function of environment","Environmental degradation"],"answer":3,"explanation":"Environmental degradation: deterioration in environmental quality through pollution, resource depletion or ecosystem damage"},{"q":"Which concept best matches this situation? Resource extraction remains within regeneration and waste stays within assimilative limits.","options":["Carrying capacity","Sustainable development","Environment","Waste-assimilation function"],"answer":0,"explanation":"Carrying capacity: the ability of the environment to sustain resource use and absorb waste without unacceptable long-run damage"},{"q":"Which concept best matches this situation? Economic growth relies more on efficient resource use and cleaner energy.","options":["Sustainable-development strategy","Sustainable development","Resource-supply function of environment","Renewable resource"],"answer":1,"explanation":"Sustainable development: development that meets present needs while protecting the ability of future generations to meet their needs"},{"q":"Which concept best matches this situation? Solar power and improved public transport lower reliance on polluting fuels.","options":["Environment","Life-support function of environment","Sustainable-development strategy","Non-renewable resource"],"answer":2,"explanation":"Sustainable-development strategy: policies such as renewable energy, organic farming, efficient waste management, public transport and conservation reduce environmental pressure while supporting development"}]}},{"id":"cbse-12-ied-ch13","board":"CBSE","classLevel":12,"subject":"Economics","stream":"Indian Economic Development","title":"Development Experience of India, Pakistan and China — Comparative Study","chapter":"IED Chapter 13","sourceLabel":"T.R. Jain & V.K. Ohri — Indian Economic Development, Class XII (2020-21 reference edition); aligned to CBSE 2026–27 Indian Economic Development scope","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Which statement best explains \"India–Pakistan post-independence strategy\"?","options":["both countries initially used mixed-economy approaches with important roles for public and private sectors","China initially placed extensive ownership and production decisions under state control after the establishment of the People’s Republic","China’s late-1950s campaign aimed at rapid industrial and agricultural transformation through mass mobilisation","India adopted a broad liberalisation, privatisation and globalisation programme in response to economic pressures"],"answer":0,"explanation":"India–Pakistan post-independence strategy: both countries initially used mixed-economy approaches with important roles for public and private sectors"},{"q":"Which statement best explains \"China’s statist strategy\"?","options":["a strategy emphasising domestic production and reduced dependence on external markets during early development","China initially placed extensive ownership and production decisions under state control after the establishment of the People’s Republic","China gradually introduced market-oriented incentives and greater openness while retaining a significant state role","development comparison uses indicators such as population growth, sex ratio and fertility alongside income measures"],"answer":1,"explanation":"China’s statist strategy: China initially placed extensive ownership and production decisions under state control after the establishment of the People’s Republic"},{"q":"Which statement best explains \"Inward-looking development\"?","options":["China’s late-1950s campaign aimed at rapid industrial and agricultural transformation through mass mobilisation","Pakistan moved toward significant liberalisation and reform before India’s 1991 programme, with major changes during the late 1980s","a strategy emphasising domestic production and reduced dependence on external markets during early development","countries can differ in the shares and growth of agriculture, industry and services as development proceeds"],"answer":2,"explanation":"Inward-looking development: a strategy emphasising domestic production and reduced dependence on external markets during early development"},{"q":"Which statement best explains \"Great Leap Forward\"?","options":["China gradually introduced market-oriented incentives and greater openness while retaining a significant state role","India adopted a broad liberalisation, privatisation and globalisation programme in response to economic pressures","comparative development also considers health, education and other quality-of-life indicators rather than GDP alone","China’s late-1950s campaign aimed at rapid industrial and agricultural transformation through mass mobilisation"],"answer":3,"explanation":"Great Leap Forward: China’s late-1950s campaign aimed at rapid industrial and agricultural transformation through mass mobilisation"},{"q":"Which statement best explains \"Chinese economic reforms from 1978\"?","options":["China gradually introduced market-oriented incentives and greater openness while retaining a significant state role","Pakistan moved toward significant liberalisation and reform before India’s 1991 programme, with major changes during the late 1980s","development comparison uses indicators such as population growth, sex ratio and fertility alongside income measures","both countries initially used mixed-economy approaches with important roles for public and private sectors"],"answer":0,"explanation":"Chinese economic reforms from 1978: China gradually introduced market-oriented incentives and greater openness while retaining a significant state role"},{"q":"Which statement best explains \"Pakistan economic reforms\"?","options":["India adopted a broad liberalisation, privatisation and globalisation programme in response to economic pressures","Pakistan moved toward significant liberalisation and reform before India’s 1991 programme, with major changes during the late 1980s","countries can differ in the shares and growth of agriculture, industry and services as development proceeds","China initially placed extensive ownership and production decisions under state control after the establishment of the People’s Republic"],"answer":1,"explanation":"Pakistan economic reforms: Pakistan moved toward significant liberalisation and reform before India’s 1991 programme, with major changes during the late 1980s"},{"q":"Which statement best explains \"India’s 1991 reforms\"?","options":["development comparison uses indicators such as population growth, sex ratio and fertility alongside income measures","comparative development also considers health, education and other quality-of-life indicators rather than GDP alone","India adopted a broad liberalisation, privatisation and globalisation programme in response to economic pressures","a strategy emphasising domestic production and reduced dependence on external markets during early development"],"answer":2,"explanation":"India’s 1991 reforms: India adopted a broad liberalisation, privatisation and globalisation programme in response to economic pressures"},{"q":"Which statement best explains \"Demographic comparison\"?","options":["countries can differ in the shares and growth of agriculture, industry and services as development proceeds","both countries initially used mixed-economy approaches with important roles for public and private sectors","China’s late-1950s campaign aimed at rapid industrial and agricultural transformation through mass mobilisation","development comparison uses indicators such as population growth, sex ratio and fertility alongside income measures"],"answer":3,"explanation":"Demographic comparison: development comparison uses indicators such as population growth, sex ratio and fertility alongside income measures"},{"q":"Which statement best explains \"Sectoral development comparison\"?","options":["countries can differ in the shares and growth of agriculture, industry and services as development proceeds","comparative development also considers health, education and other quality-of-life indicators rather than GDP alone","China initially placed extensive ownership and production decisions under state control after the establishment of the People’s Republic","China gradually introduced market-oriented incentives and greater openness while retaining a significant state role"],"answer":0,"explanation":"Sectoral development comparison: countries can differ in the shares and growth of agriculture, industry and services as development proceeds"},{"q":"Which statement best explains \"Human-development comparison\"?","options":["both countries initially used mixed-economy approaches with important roles for public and private sectors","comparative development also considers health, education and other quality-of-life indicators rather than GDP alone","a strategy emphasising domestic production and reduced dependence on external markets during early development","Pakistan moved toward significant liberalisation and reform before India’s 1991 programme, with major changes during the late 1980s"],"answer":1,"explanation":"Human-development comparison: comparative development also considers health, education and other quality-of-life indicators rather than GDP alone"}],"Moderate":[{"q":"Which concept best matches this situation? The state led major investment while private enterprise also operated.","options":["China’s statist strategy","India–Pakistan post-independence strategy","Great Leap Forward","India’s 1991 reforms"],"answer":1,"explanation":"India–Pakistan post-independence strategy: both countries initially used mixed-economy approaches with important roles for public and private sectors"},{"q":"Which concept best matches this situation? Critical resources and production decisions were centrally controlled.","options":["Inward-looking development","Chinese economic reforms from 1978","China’s statist strategy","Demographic comparison"],"answer":2,"explanation":"China’s statist strategy: China initially placed extensive ownership and production decisions under state control after the establishment of the People’s Republic"},{"q":"Which concept best matches this situation? Domestic capacity is protected while imports are restrained.","options":["Great Leap Forward","Pakistan economic reforms","Sectoral development comparison","Inward-looking development"],"answer":3,"explanation":"Inward-looking development: a strategy emphasising domestic production and reduced dependence on external markets during early development"},{"q":"Which concept best matches this situation? Production was reorganised through large collective efforts to accelerate output.","options":["Great Leap Forward","Chinese economic reforms from 1978","India’s 1991 reforms","Human-development comparison"],"answer":0,"explanation":"Great Leap Forward: China’s late-1950s campaign aimed at rapid industrial and agricultural transformation through mass mobilisation"},{"q":"Which concept best matches this situation? Reforms begin in agriculture and later expand toward industry and external trade.","options":["Pakistan economic reforms","Chinese economic reforms from 1978","Demographic comparison","India–Pakistan post-independence strategy"],"answer":1,"explanation":"Chinese economic reforms from 1978: China gradually introduced market-oriented incentives and greater openness while retaining a significant state role"},{"q":"Which concept best matches this situation? Policy gives a larger role to markets and private enterprise.","options":["India’s 1991 reforms","Sectoral development comparison","Pakistan economic reforms","China’s statist strategy"],"answer":2,"explanation":"Pakistan economic reforms: Pakistan moved toward significant liberalisation and reform before India’s 1991 programme, with major changes during the late 1980s"},{"q":"Which concept best matches this situation? Industrial and trade controls were reduced and external integration increased.","options":["Demographic comparison","Human-development comparison","Inward-looking development","India’s 1991 reforms"],"answer":3,"explanation":"India’s 1991 reforms: India adopted a broad liberalisation, privatisation and globalisation programme in response to economic pressures"},{"q":"Which concept best matches this situation? Two countries with similar GDP growth may have very different demographic outcomes.","options":["Demographic comparison","Sectoral development comparison","India–Pakistan post-independence strategy","Great Leap Forward"],"answer":0,"explanation":"Demographic comparison: development comparison uses indicators such as population growth, sex ratio and fertility alongside income measures"},{"q":"Which concept best matches this situation? One country may industrialise faster while another becomes service-led.","options":["Human-development comparison","Sectoral development comparison","China’s statist strategy","Chinese economic reforms from 1978"],"answer":1,"explanation":"Sectoral development comparison: countries can differ in the shares and growth of agriculture, industry and services as development proceeds"},{"q":"Which concept best matches this situation? A country with lower income may outperform another on life expectancy or literacy.","options":["India–Pakistan post-independence strategy","Inward-looking development","Human-development comparison","Pakistan economic reforms"],"answer":2,"explanation":"Human-development comparison: comparative development also considers health, education and other quality-of-life indicators rather than GDP alone"}]}},{"id":"cbse-12-business-studies-ch1","board":"CBSE","classLevel":12,"subject":"Business Studies","title":"Nature and Significance of Management — Board Mastery","chapter":"Chapter 1","sourceLabel":"VK Global Business Studies Class XII — Chapter 1: Nature and Significance of Management; aligned to CBSE 2026–27 Unit 1","sourceStatus":"Reference-book + syllabus verified","levelCounts":{"Easy":10,"Moderate":10,"Hard":10,"Extreme":10},"levels":{"Easy":[{"q":"Management is a process of getting things done with the aim of achieving goals:","options":["Effectively and efficiently","Only quickly","Only at minimum cost","Without planning"],"answer":0,"explanation":"The chapter defines management as getting things done to achieve goals effectively and efficiently."},{"q":"Completing the given task or achieving the goal on time is called:","options":["Efficiency","Effectiveness","Coordination","Staffing"],"answer":1,"explanation":"Effectiveness is concerned with doing the right task and achieving the intended result on time."},{"q":"Completing a task with minimum cost and optimum use of resources is called:","options":["Efficiency","Effectiveness","Planning","Directing"],"answer":0,"explanation":"Efficiency focuses on doing the task in the right way with minimum cost and optimum utilisation of resources."},{"q":"Management is required in business as well as non-business organisations. This shows that management is:","options":["Pervasive","Intangible","Temporary","Restricted"],"answer":0,"explanation":"Pervasive means management is required in all types of organisations, departments and levels."},{"q":"Management of work, people and operations makes management:","options":["Multidimensional","Static","Individual","Professionally restricted"],"answer":0,"explanation":"The source identifies work, people and operations as the three dimensions of management."},{"q":"Which is an organisational objective of management?","options":["Survival","Employee recognition","Safe working conditions","Community health programme"],"answer":0,"explanation":"Survival, profit and growth are the three organisational objectives listed in the chapter."},{"q":"Providing quality products at reasonable prices is mainly a:","options":["Social objective","Personal objective","Organisational objective","Staffing function"],"answer":0,"explanation":"The source includes quality products at reasonable prices among social objectives."},{"q":"Training and promotion of employees are mainly related to:","options":["Personal objectives","Social objectives","Only survival","Only profit"],"answer":0,"explanation":"Training, promotion and personal development are listed under personal or individual objectives."},{"q":"Which designation belongs to top-level management?","options":["Chief Executive Officer","Sales Manager","Foreman","Supervisor"],"answer":0,"explanation":"The source places the CEO among top-level managers."},{"q":"The process of synchronising the activities of different departments is called:","options":["Coordination","Recruitment","Controlling","Planning"],"answer":0,"explanation":"The chapter defines coordination as synchronising and integrating the activities of different departments."}],"Moderate":[{"q":"Planning, organising, staffing, directing and controlling are performed repeatedly. This shows management is:","options":["A continuous process","A one-time activity","A restricted profession","Only a science"],"answer":0,"explanation":"Management is continuous because its functions are performed on an ongoing basis."},{"q":"A company changes its objectives and methods when technology and competition change. This shows management is:","options":["Dynamic","Intangible only","Static","Individual"],"answer":0,"explanation":"Management is dynamic because it adapts organisational goals and activities to changes in the environment."},{"q":"Management cannot be physically seen, but its presence can be felt through orderliness and coordination. This means management is:","options":["Intangible","Pervasive","A profession","A physical resource"],"answer":0,"explanation":"The source describes management as intangible because it is felt through results rather than seen directly."},{"q":"Reducing cost and improving productivity with minimum wastage shows that management:","options":["Increases efficiency","Eliminates planning","Removes all objectives","Reduces coordination"],"answer":0,"explanation":"One importance of management is increasing efficiency through lower cost and better productivity."},{"q":"Why is management described as an inexact or social science in the reference book?","options":["Human behaviour cannot be predicted with the same exactness as natural science","Management has no organised knowledge","Management has no principles","Managers never use observation"],"answer":0,"explanation":"Management has systematic knowledge and observed principles, but human behaviour makes universal exactness difficult."},{"q":"Which feature most strongly supports management as an art?","options":["Personalised application of knowledge","Compulsory legal licence","Universal validity of every principle","Fixed entry examination"],"answer":0,"explanation":"Art requires personal skill, creativity and application of theoretical knowledge."},{"q":"Which feature of a full profession is NOT compulsory for becoming a manager?","options":["Restricted entry through a compulsory qualification","Use of knowledge","Working toward objectives","Decision-making"],"answer":0,"explanation":"The source notes that there is no legal restriction requiring a particular degree or licence before becoming a manager."},{"q":"Middle-level managers primarily act as a link between:","options":["Top and supervisory levels","Customers and competitors only","Shareholders and government only","Workers and suppliers only"],"answer":0,"explanation":"Middle management interprets top-level policies and connects them with lower-level execution."},{"q":"Deciding in advance what to do, how to do, when to do and who will do it is:","options":["Planning","Staffing","Directing","Controlling"],"answer":0,"explanation":"Planning is the first function and deals with deciding future action in advance."},{"q":"Comparing actual performance with planned performance and taking corrective action is:","options":["Controlling","Organising","Staffing","Coordination only"],"answer":0,"explanation":"Controlling measures actual performance against plans, identifies deviations and initiates correction."}]}},{"id":"gseb-12-economics-ch3","board":"GSEB","classLevel":12,"subject":"Economics","title":"Money and Inflation","chapter":"Chapter 3","sourceLabel":"GSEB Class 12 Economics — Chapter 3 Money and Inflation textbook-based notes","sourceStatus":"Verified textbook-based source used","levelCounts":{"Easy":5,"Moderate":5,"Hard":5,"Extreme":5},"levels":{"Easy":[{"q":"Barter means:","options":["Exchange using only bank deposits","Direct exchange of goods/services without money","Only foreign trade","Borrowing from banks"],"answer":1,"explanation":"The source defines barter as direct exchange without a medium such as money."},{"q":"Which is a main limitation of barter?","options":["Too much paper money","Double coincidence of wants","Excess bank credit","High interest only"],"answer":1,"explanation":"Barter requires both parties to want exactly what the other offers."},{"q":"Which function of money solves the double coincidence of wants problem?","options":["Store of value","Medium of exchange","Measure of value","Tax payment only"],"answer":1,"explanation":"Money acts as an intermediary, separating selling from buying."},{"q":"Inflation means a continuous rise in:","options":["One product price only","General price level","Only wages","Only import prices"],"answer":1,"explanation":"The source defines inflation as a sustained general price-level rise, not a temporary single-price increase."},{"q":"During inflation, purchasing power of money generally:","options":["Rises","Falls","Never changes","Becomes zero"],"answer":1,"explanation":"As the general price level rises, the same money buys fewer goods and services."}],"Moderate":[{"q":"Which function of money solves the barter problem of storing exchange value?","options":["Medium of exchange","Store of value","Measure of value","Unit of production"],"answer":1,"explanation":"Money can be saved for future use, overcoming the storage limitation of barter."},{"q":"Which function provides a common yardstick for comparing prices?","options":["Store of value","Measure of value","Medium of exchange only","Credit creation"],"answer":1,"explanation":"Measure of value allows different goods and services to be valued in common money terms."},{"q":"According to the source, true inflation after full employment is associated with:","options":["Marshall","Robertson","Keynes","Robbins"],"answer":2,"explanation":"The notes identify Keynes with the view that true inflation occurs beyond full employment."},{"q":"When government controls visible price rise through rules or subsidies, the source calls it:","options":["Demand-pull inflation","Suppressed inflation","Deflation","Barter inflation"],"answer":1,"explanation":"Underlying inflation may exist even when visible price increases are suppressed by controls."},{"q":"A rise in production costs causing firms to increase prices is:","options":["Demand-pull inflation","Cost-push inflation","Only monetary inflation","No inflation"],"answer":1,"explanation":"Cost-push inflation comes from the supply/cost side."}]}}];
export function getQuizPacks(board, classLevel, subject) { return verifiedQuizPacks.filter(p => p.board === board && p.classLevel === classLevel && p.subject === subject); }
